Table_Dialog_Left_43 = {
  [508292] = "{id=508292,Voice='Npc_Quest/508292',Text='诡计，已经出现了。',Speaker=813768,}",
  [508295] = "{id=508295,Voice='Npc_Quest/508295',Text='保持警惕，互相支援。',Speaker=813768,}",
  [508296] = "{id=508296,Voice='Npc_Quest/508296',Text='支援赤鳞团！',Speaker=813768,}",
  [508297] = "{id=508297,Voice='Npc_Quest/508297',Text='人类来这里做什么？你们是如何能进来的？',Speaker=813769,}",
  [508298] = "{id=508298,Voice='Npc_Quest/508298',Text='我们是时空龙的使节。',Speaker=813768,}",
  [508299] = "{id=508299,Voice='Npc_Quest/508299',Text='使节？听说时空龙大人已经很久没有管过关于龙族的事务，为什么会派你们来闪麟高地？',Speaker=813769,}",
  [508301] = "{id=508301,Voice='Npc_Quest/508301',Text='是时空龙的赐福……让他们进来。',Speaker=813818,}",
  [508324] = "{id=508324,Voice='Npc_Quest/508324',Text='怎么样，有新的情报吗？',Speaker=813768,Option='说明情况',}",
  [508325] = "{id=508325,Voice='Npc_Quest/508325',Text='赤炎龙想要带领所有的龙族离开深渊之湖寻求更好的生活，为此她正在建造“[c][ffff00]自由之门[-][/c]”。',Speaker=813768,}",
  [508326] = "{id=508326,Voice='Npc_Quest/508326',Text='而她与黑炎龙的理念相违背，两方势力产生了矛盾，引发了战争。',Speaker=813768,}",
  [508327] = "{id=508327,Voice='Npc_Quest/508327',Text='高尔团长！高尔团长！我需要您的帮助！',Speaker=813776,}",
  [508328] = "{id=508328,Voice='Npc_Quest/508328',Text='我们已经等待许久，却未能得到赤炎龙的接见。',Speaker=813768,}",
  [508329] = "{id=508329,Voice='Npc_Quest/508329',Text='一定有事发生，去听听那位侍女说了些什么。',Speaker=813768,}",
  [508341] = "{id=508341,Voice='Npc_Quest/508341',Text='感谢二位的帮助，久等了，蕾蒂西亚大人已经苏醒，要召见二位。请随我来。',Speaker=813776,}",
  [508349] = "{id=508349,Voice='Npc_Quest/508349',Text='我可以交出我的赤炎之星，但不是现在！我还需要用它开启自由之门，[c][ffff00]将所有子民从深渊之湖送出去，这也是大人的心愿。[-][/c]',Speaker=813777,}",
  [508350] = "{id=508350,Voice='Npc_Quest/508350',Text='只是距离造好自由之门，还需要等上一些时间。',Speaker=813777,}",
  [508351] = "{id=508351,Voice='Npc_Quest/508351',Text='合作。我们帮助你建造自由之门，事成之后，你交出你的赤炎之星。',Speaker=813768,}",
  [508352] = "{id=508352,Voice='Npc_Quest/508352',Text='赤炎之火，燃烧吧！',Speaker=813777,}",
  [508367] = "{id=508367,Voice='Npc_Quest/508367',Text='我看到了……将古龙们的龙炎闪鳞带回来吧！',Speaker=813776,}",
  [508381] = "{id=508381,Voice='Npc_Quest/508381',Text='出逃者再次出现了！就是泰莉亚！',Speaker=813768,}",
  [508382] = "{id=508382,Voice='Npc_Quest/508382',Text='果然……正如古龙们所说——龙族战败、神族布下的结界，但听起来都指向[c][ffff00]龙族无法离开深渊之湖[-][/c]的事实。',Speaker=813768,Option='{没错,0},{我也记得是这样,0}',}",
  [508383] = "{id=508383,Voice='Npc_Quest/508383',Text='还有……在神殿遗迹中，扮作神影的出逃者，也曾提及龙族困守深渊之湖源于一个“约定”，如果这一切是真的，出逃者早就知道龙族无法离开深渊之湖……',Speaker=813768,}",
  [508384] = "{id=508384,Voice='Npc_Quest/508384',Text='那么自由之门……真的可以带走龙族吗？只有那扇门能给我们答案！走，追上泰莉亚！！',Speaker=813768,}",
  [508390] = "{id=508390,Voice='Npc_Quest/508390',Text='这扇门，和时空隙谷的时空矩阵一模一样！看来自由之门与启动时空矩阵有关，我们必须阻止出逃者的阴谋!',Speaker=813768,}",
  [508391] = "{id=508391,Voice='Npc_Quest/508391',Text='阴魂不散的家伙！',Speaker=813776,}",
  [508392] = "{id=508392,Voice='Npc_Quest/508392',Text='这扇门通往的并不是自由的世界，而是死亡。它会吞噬龙族的力量为时空矩阵供能。',Speaker=813817,}",
  [508393] = "{id=508393,Voice='Npc_Quest/508393',Text='无名者虽然暂时用力量压制住了它，但这不是长久之计。',Speaker=813817,}",
  [508394] = "{id=508394,Voice='Npc_Quest/508394',Text='要彻底关闭它，需要斩断它与时空乱流的链接！这里交给我和无名者，你快去！解决这些问题才能[c][ffff00]找到蕾蒂西亚拿到赤炎之星[-][/c]！',Speaker=813817,}",
  [508395] = "{id=508395,Voice='Npc_Quest/508395',Text='从这些时空垃圾身上获取更多的坍缩器！',Speaker=813817,}",
  [508396] = "{id=508396,Voice='Npc_Quest/508396',Text='超时空坍缩器可以用于关闭超时空之眼。',Speaker=813817,}",
  [508397] = "{id=508397,Voice='Npc_Quest/508397',Text='各位！这一切都是赤炎龙的阴谋！她打着尼德霍格大人的名号，利用我们，只是为了增强自己的力量！',Speaker=813779,}",
  [508398] = "{id=508398,Voice='Npc_Quest/508398',Text='赤炎龙这个疯女人！自从被黑炎龙重创后，想出这么残忍的方法，为的就是恢复她的力量！',Speaker=813779,}",
  [508399] = "{id=508399,Voice='Npc_Quest/508399',Text='可恶的赤炎龙，所有的龙族子民都不该这样枉死！我们要报仇！',Speaker=813779,}",
  [508400] = "{id=508400,Text='讨伐赤炎龙！讨伐赤炎龙！',}",
  [508401] = "{id=508401,Voice='Npc_Quest/508401',Text='安静！',Speaker=813769,}",
  [508403] = "{id=508403,Voice='Npc_Quest/508403',Text='一场彻头彻尾的诡计，所有龙族子民在煽动之下，开始憎恨他们曾爱戴的赤炎龙。',Speaker=813768,}",
  [508404] = "{id=508404,Voice='Npc_Quest/508404',Text='时空矩阵被关闭，出逃者不会轻易放弃，它一定会继续它的诡计——找到激活时空矩阵的力量！',Speaker=813817,}",
  [508405] = "{id=508405,Voice='Npc_Quest/508405',Text='就如它之前想要抢夺你的力量一样，赤炎龙是他唯一的目标！我们要尽快找到赤炎龙！',Speaker=813768,Option='可她在哪儿',}",
  [508406] = "{id=508406,Voice='Npc_Quest/508406',Text='诡计会给出答案——出逃者去往的方向就是赤炎龙所在的地方！',Speaker=813768,}",
  [508407] = "{id=508407,Voice='Npc_Quest/508407',Text='那个方向……是霞光王座！',Speaker=813817,}",
  [508408] = "{id=508408,Voice='Npc_Quest/508408',Text='这枚手镯为蕾蒂西亚制造了一个梦境，并通过梦境吸收她的力量，最终彻底掌控她的身体。',Speaker=813817,}",
  [508409] = "{id=508409,Voice='Npc_Quest/508409',Text='你们要尽快进入她的梦境中，将其唤醒！看起来离[c][ffff00]拿到赤炎之星[-][/c]又远了一步！',Speaker=813817,}",
  [508410] = "{id=508410,Voice='Npc_Quest/508410',Text='快去将寒霜鳞片、冷凝之泪和霞光结晶带过来，我来为你们打开进入梦境的通道。',Speaker=813817,}",
  [508411] = "{id=508411,Voice='Npc_Quest/508411',Text='希望一切还来得及！',Speaker=813817,}",
  [508412] = "{id=508412,Voice='Npc_Quest/508412',Text='连接梦境的通道已经被打开，进入其中去唤醒蕾蒂西亚吧。',Speaker=813817,}",
  [508415] = "{id=508415,Voice='Npc_Quest/508415',Text='吾乃天地树之饲育者，大地之守护者，神裁之尼德霍格！蕾蒂西亚，吾最忠诚的子民，听吾之命——',Speaker=813789,}",
  [508416] = "{id=508416,Voice='Npc_Quest/508416',Text='带领所有龙族，挣脱深渊之湖的枷锁，重获自由！吾将派遣特使协助你完成这一伟大使命。',Speaker=813789,}",
  [508417] = "{id=508417,Voice='Npc_Quest/508417',Text='我是龙族最忠诚的子民……我一定会遵守尼德霍格大人的旨意。',Speaker=813777,}",
  [508418] = "{id=508418,Voice='Npc_Quest/508418',Text='是他……那个出逃者！他通过伪装迷惑赤炎龙！',Speaker=813768,}",
  [508419] = "{id=508419,Voice='Npc_Quest/508419',Text='感受死亡，深渊的忤逆者！',Speaker=813789,}",
  [508420] = "{id=508420,Voice='Npc_Quest/508420',Text='你是谁？你不是尼德霍格大人…… 那谁来指引我们……挣脱枷锁……重获自由……',Speaker=813777,}",
  [508422] = "{id=508422,Voice='Npc_Quest/508422',Text='蕾蒂西亚，抬起你的头，吾要看到你的忠诚和决心，',Speaker=813789,}",
  [508423] = "{id=508423,Voice='Npc_Quest/508423',Text='现在，集合所有的力量建造自由之门！通过它，所有龙族都可以离开这片被诅咒的土地……为了龙族美好的明天……',Speaker=813789,}",
  [508424] = "{id=508424,Voice='Npc_Quest/508424',Text='为了龙族，蕾蒂西亚一定会完成尼德霍格大人的嘱托。',Speaker=813777,}",
  [508425] = "{id=508425,Voice='Npc_Quest/508425',Text='假扮原初之龙，真是个大胆的诡计！揭开它的伪装！',Speaker=813768,}",
  [508426] = "{id=508426,Voice='Npc_Quest/508426',Text='深渊将吞噬一切！',Speaker=813789,}",
  [508427] = "{id=508427,Voice='Npc_Quest/508427',Text='自由之门真的可以带龙族离开诅咒之地吗？……',Speaker=813777,}",
  [508428] = "{id=508428,Voice='Npc_Quest/508428',Text='黑炎龙已经背叛了龙族。决不能让他阻碍我们的计划！',Speaker=813789,}",
  [508429] = "{id=508429,Voice='Npc_Quest/508429',Text='蕾蒂西亚，发起战争吧！唯有你能帮吾拯救龙族……',Speaker=813789,}",
  [508430] = "{id=508430,Voice='Npc_Quest/508430',Text='战争是自由唯一的出口！！',Speaker=813777,}",
  [508431] = "{id=508431,Voice='Npc_Quest/508431',Text='利用赤炎龙的忠诚，假扮尼德霍格，挑起战争……它究竟想做什么？！揭开它的伪装！',Speaker=813768,}",
  [508432] = "{id=508432,Voice='Npc_Quest/508432',Text='吾是深渊的主宰！',Speaker=813789,}",
  [508433] = "{id=508433,Voice='Npc_Quest/508433',Text='龙族早已厌倦了战争，而我又是为何要再次燃起战火……？',Speaker=813777,}",
  [508434] = "{id=508434,Voice='Npc_Quest/508434',Text='挣脱梦境中的虚妄，龙族子民还在等待你平息战火！',Speaker=813768,}",
  [508440] = "{id=508440,Voice='Npc_Quest/508440',Text='赤炎龙蕾蒂西亚，醒来吧！梦境中的一切都是假的。',Speaker=813768,}",
  [508441] = "{id=508441,Voice='Npc_Quest/508441',Text='他们，是我的敌人，是龙族的敌人，你不会让他们伤害我的，对吗，蕾蒂西亚？',Speaker=813789,}",
  [508442] = "{id=508442,Voice='Npc_Quest/508442',Text='是的，尼德霍格大人。我会为你清除所有的障碍……',Speaker=813777,}",
  [508449] = "{id=508449,Voice='Npc_Quest/508449',Text='爷爷，她好可怕啊。她不是我们喜欢的赤炎龙大人了，是怪物！',Speaker=813781,}",
  [508450] = "{id=508450,Voice='Npc_Quest/508450',Text='为什么……为什么……这样……看着我……',Speaker=813777,}",
  [508452] = "{id=508452,Voice='Npc_Quest/508452',Text='这个世界已经无法容下诡计。',Speaker=813819,}",
  [508468] = "{id=508468,Voice='Npc_Quest/508468',Text='逆转时间线，哪怕只是这么短的时间这么小的范围，你要付出的，是你的全部。',Speaker=813817,}",
  [508469] = "{id=508469,Voice='Npc_Quest/508469',Text='我会死，我明白。',Speaker=813777,}",
  [508470] = "{id=508470,Voice='Npc_Quest/508470',Text='这是赤炎之星，接下来的一切都要交给你们了，无论是消失在自由之门的子民还是……深渊之湖的未来……',Speaker=813777,}",
  [508471] = "{id=508471,Voice='Npc_Quest/508471',Text='我犯了错……以我最爱之人的名义，伤害了我最想保护的人……',Speaker=813777,}",
  [508472] = "{id=508472,Voice='Npc_Quest/508472',Text='接下来拜托你了……',Speaker=813777,}",
  [508473] = "{id=508473,Voice='Npc_Quest/508473',Text='以赤炎龙蕾蒂西亚之名，带你们回家。',Speaker=813817,}",
  [508474] = "{id=508474,Voice='Npc_Quest/508474',Text='赤炎龙大人她……到底发生了什么？请告诉我们，我们需要一个真相。',Speaker=813769,Option='{她被欺骗而犯下错误,0},{为弥补错误而牺牲自己,0}',}",
  [508475] = "{id=508475,Voice='Npc_Quest/508475',Text='原来是这样……我一直坚信，赤炎龙大人绝不会背叛我们！',Speaker=813769,}",
  [508476] = "{id=508476,Voice='Npc_Quest/508476',Text='可是……接下来我们该怎么办……谁还能领导我们在深渊之湖这样的地方活下去……',Speaker=813769,}",
  [508477] = "{id=508477,Voice='Npc_Quest/508477',Text='时空龙大人……你……',Speaker=813769,}",
  [508478] = "{id=508478,Voice='Npc_Quest/508478',Text='打住，我没有时间也没有兴趣接受她的烂摊子。',Speaker=813817,}",
  [508479] = "{id=508479,Voice='Npc_Quest/508479',Text='赤炎龙是尼德霍格用最炙热的火焰创造的生命，将龙蛋放回火山中吧。',Speaker=813817,}",
  [508480] = "{id=508480,Voice='Npc_Quest/508480',Text='或许在漫长时间的浴火中，有一天她还会重新诞生在这个世界。',Speaker=813817,}",
  [508481] = "{id=508481,Voice='Npc_Quest/508481',Text='一直以来你们都躲藏在她的庇护之下，这一次也该轮到你们守护她了。',Speaker=813817,}",
  [508482] = "{id=508482,Voice='Npc_Quest/508482',Text='是……我们一定可以做到！',Speaker=813769,}",
  [508483] = "{id=508483,Voice='Npc_Quest/508483',Text='看来，赤炎龙蕾蒂西亚的故事并未结束。',Speaker=813768,}",
  [508484] = "{id=508484,Voice='Npc_Quest/508484',Text='嗯……你们两个的任务也还未结束，带上赤炎之星，我会在老地方等你们。',Speaker=813817,}",
  [508486] = "{id=508486,Voice='Npc_Quest/508486',Text='目前为止出逃者还未察觉我们正在治愈天地树，但我们仍需加快速度获取另外两颗龙族之星。',Speaker=813768,}",
  [508487] = "{id=508487,Voice='Npc_Quest/508487',Text='嗯，可接下来你们要面对的是黑炎龙参宿四，一个邪恶而又非同寻常的龙族。',Speaker=813767,Option='{他是个反派？,0},{我和他交过手,0}',}",
  [508488] = "{id=508488,Voice='Npc_Quest/508488',Text='他与我和蕾蒂西亚不同，他并非尼德霍格大人直接创造的龙族，而是后来在龙族的自然繁衍中诞生的。',Speaker=813767,}",
  [508489] = "{id=508489,Voice='Npc_Quest/508489',Text='一个没有最纯粹原初之力的龙族能成为四大龙主之一，除了依靠他自己的心智，还有他不择手段获取的邪恶力量。',Speaker=813767,}",
  [508490] = "{id=508490,Voice='Npc_Quest/508490',Text='现在还不是前往无相沼泽的时候，我会在合适的时机引导你们。',Speaker=813767,}",
  [508491] = "{id=508491,Voice='Npc_Quest/508491',Text='蕾蒂西亚可是让我的时空秩序出现了大纰漏，哎，真令人头疼……',Speaker=813767,}",
  [508492] = "{id=508492,Voice='Npc_Quest/508492',Text='不择手段获取的邪恶力量吗？……这可是诡计最适宜生长的土壤……',Speaker=813768,}",
  [508493] = "{id=508493,Voice='Npc_Quest/508493',Text='谁也不能离开深渊之湖！绝不能！',Speaker=813811,}",
  [508496] = "{id=508496,Voice='Npc_Quest/508496',Text='他是暗爪营的人！！好了，觐见蕾蒂西亚大人吧！',Speaker=813776,}",
  [508497] = "{id=508497,Voice='Npc_Quest/508497',Text='奥斯卡那老家伙派来的人身手不错。',Speaker=813777,}",
  [508504] = "{id=508504,Text='无名者与冒险者携时空龙奥斯卡的赐福来到烈焰堡垒，却被赤鳞团龙骑士拦下。彼时的闪鳞高地正值撤离深渊之湖计划的关键时刻，赤鳞团戒备森严。一位红发少女察觉二人身上的赐福，破例准许他们进入。堡垒内，龙族子民正为通过\"自由之门\"离开深渊之湖做准备。而闪鳞高地的女王蕾蒂西亚却因旧疾暂不见客，由泰莉亚代为接洽。\n在协助取得治愈蕾蒂西亚的药物后，虚弱的蕾蒂西亚终于现身，原来她就是那位红发少女。在得知天地树危机后，她承诺在自由之门开启后交出赤炎之星。\n为加速开启自由之门，无名者提出合作，并受指引收集来自古龙时代的龙炎闪麟时，而古龙却通过只言片语留下启示——\"战败？结界...\"似乎都在暗示着龙族无法真正离开深渊之湖的宿命。\n当无名者将闪麟交给泰莉亚熔炼时，她眼中闪过的蓝光引起无名者的警觉。泰莉亚反诬二人阻拦开启自由之之门的计划，召唤龙骑士围困他们。\n尽管无名者奋力追击，泰莉亚仍将力量注入自由之门。\n随着自由之门的开启，大量龙族子民被吞噬，其力量被用于建立时空矩阵与深渊之湖的链接。无名者与冒险者击败泰莉亚，附在泰莉亚身上的出逃者再次逃跑。\n断开时空矩阵链接后，时空龙之影降临告诉所有龙族子民真相：自由之门实为陷阱，出逃者通过自由之门汲取龙族子民的力量，从而建立时空矩阵与深渊之湖的链接。但时空龙之影的到来并未给龙族子民带来安慰。\n幸存的龙族子民愤怒不已，认为这一切都因蕾蒂西亚而起，并决定讨伐她。时空龙之影推测，出逃者的诡计再次失败，一定会寻找其他力量来开启时空矩阵，而这个力量极有可能就是消失不见的蕾蒂西亚。\n在霞光王座中，所有人看到了沉睡的蕾蒂西亚，她被梦核包裹着，梦境里不断重演着“尼德霍格”的指引。当无名者刺穿所有梦核后，蕾蒂西亚的泪水灼烧了这片土地，被蛊惑的女王终于清醒。在她的梦境中，无名者和冒险者目睹了整个诡计的始末——出逃者利用了蕾蒂西亚对尼德霍格的尊崇以及对龙族子民的珍重，假扮尼德霍格指引她建造自由之门，并带领所有龙族子民进入其中。\n蕾蒂西亚为了弥补自己的过错，以及拯救她心爱的龙族子民，她以赤炎之星威胁时空龙之影逆转时空，将那些死去的龙族子民带回现实。时空龙之影不得不同意。就此，蕾蒂西亚虚弱的声音消散在空中，而她的力量化作赤红粒子中包裹着自由之门，死去的龙族子民从自由之门中折返，而王座上只剩一枚布满裂痕的龙蛋及赤炎之星。\n最终，无名者和冒险者将蕾蒂西亚的赤炎之星浇灌了天地树根，使得天地树根得到了些许恢复。\n时空龙之影则要修复因为蕾蒂西亚导致的时空纰漏，而冒险者和无名者则踏上下一段旅程——前往无相沼泽，获取黑炎龙的黑炎之星。',}",
  [508527] = "{id=508527,Text='等待片刻后',}",
  [508528] = "{id=508528,Voice='Npc_Quest/508528',Text='没错！就是这些！',Speaker=813776,}",
  [508620] = "{id=508620,Voice='Npc_Quest/508620',Text='我们做错了什么……',Speaker=813877,}",
  [508621] = "{id=508621,Voice='Npc_Quest/508621',Text='悲鸣吧，惨叫吧，你们的死亡是无相沼泽最美的风景。',Speaker=813878,}",
  [508622] = "{id=508622,Voice='Npc_Quest/508622',Text='破坏黑火雷！否则也会危及我们！',Speaker=813872,}",
  [508626] = "{id=508626,Voice='Npc_Quest/508626',Text='时空龙的人，告诉我，你们到这里，究竟想得到什么？',Speaker=813878,}",
  [508627] = "{id=508627,Voice='Npc_Quest/508627',Text='黑炎之星！天地树仍在等待修复，而你守护的黑炎之星是关键！但现在的你……',Speaker=813872,}",
  [508628] = "{id=508628,Voice='Npc_Quest/508628',Text='脏东西——滚出去！！',Speaker=813878,}",
  [508639] = "{id=508639,Voice='Npc_Quest/508639',Text='哈哈！我要你永远困在你的记忆中！',Speaker=813881,}",
  [508640] = "{id=508640,Voice='Npc_Quest/508640',Text='记忆的主人命令过——这里禁止踏入。即使窥探了记忆，也无法从这里带走！',Speaker=813882,}",
  [508641] = "{id=508641,Voice='Npc_Quest/508641',Text='红色代表智慧，蓝色代表诡计，你们都是我身体中的一部分，是我力量的来源。',Speaker=813883,}",
  [508642] = "{id=508642,Voice='Npc_Quest/508642',Text='你无权窥视被封印的过去，离开！即使窥探了记忆，也无法从这里带走！',Speaker=813882,}",
  [508643] = "{id=508643,Voice='Npc_Quest/508643',Text='只要我还存在，这样的错误会永远重演！',Speaker=813883,}",
  [508644] = "{id=508644,Voice='Npc_Quest/508644',Text='不..……是智慧未能预见，力量未能阻止。',Speaker=813883,}",
  [508645] = "{id=508645,Voice='Npc_Quest/508645',Text='你知道记忆为什么是红色的吗？因为真相需要付出鲜血的代价。即使窥探了记忆，也无法从这里带走！',Speaker=813882,}",
  [508646] = "{id=508646,Voice='Npc_Quest/508646',Text='我们本是一体！',Speaker=813883,}",
  [508647] = "{id=508647,Voice='Npc_Quest/508647',Text='正因如此 ，才应该由我跨出这一步。所以，这就是我的选择！',Speaker=813883,}",
  [508648] = "{id=508648,Voice='Npc_Quest/508648',Text='你已经做出了选择，从此你的神格、你的记忆、你的名讳——你的一切都将被无名替代，直到你决定再次使用你的名字。',Speaker=813882,}",
  [508649] = "{id=508649,Voice='Npc_Quest/508649',Text='离开深渊之湖，守护这个世界。',Speaker=813882,}",
  [508650] = "{id=508650,Voice='Npc_Quest/508650',Text='我似乎看清了一些事，但有一股力量正在阻止我想起那一切。就像隔着迷雾看画——明明有轮廓，却抓不住细节。',Speaker=813872,}",
  [508651] = "{id=508651,Voice='Npc_Quest/508651',Text='我看到了蓝色手环，它本该和我的红色手环在一起，还有一个神影……虽然已经记不起他的脸……',Speaker=813872,}",
  [508652] = "{id=508652,Voice='Npc_Quest/508652',Text='但他的话，仍在回响——你的一切都将被无名替代！',Speaker=813872,}",
  [508653] = "{id=508653,Voice='Npc_Quest/508653',Text='滚开！别来烦我们！',Speaker=813884,}",
  [508697] = "{id=508697,Voice='Npc_Quest/508697',Text='谁敢闯入大人的“归巢计划”基地！！',Speaker=813894,}",
  [508737] = "{id=508737,Voice='Npc_Quest/508737',Text='和时空垃圾有什么好说的？',Speaker=813878,}",
  [508738] = "{id=508738,Voice='Npc_Quest/508738',Text='无名者，你还不明白吗，你的怜悯只会让更多的龙族之骨铺就他们“归巢”的路！可笑！',Speaker=813878,}",
  [508739] = "{id=508739,Voice='Npc_Quest/508739',Text='我的战士们，因为我，才得以让那些肮脏的东西在你们的身体中筑巢。',Speaker=813878,}",
  [508740] = "{id=508740,Voice='Npc_Quest/508740',Text='我一定会把所有时空垃圾烧成灰烬！这是他们欺骗我的代价！',Speaker=813878,}",
  [508751] = "{id=508751,Voice='Npc_Quest/508751',Text='任务完成啦~可是刚才那位戴着红圈圈的大人到底藏在哪里呢？',Speaker=813885,}",
  [508752] = "{id=508752,Voice='Npc_Quest/508752',Text='嘘！我刚才听到那边传来很凶很凶的说话声！会不会是时空垃圾……',Speaker=813885,}",
  [508753] = "{id=508753,Voice='Npc_Quest/508753',Text='滚开！和我合作？做梦。你们只是侥幸爬到我的脚下竟然和我谈条件。',Speaker=813905,}",
  [508797] = "{id=508797,Voice='Npc_Quest/508797',Text='精彩，真是精彩！无名者，你果然没让我失望，帮我找到了黑炎龙！',Speaker=813881,}",
  [508798] = "{id=508798,Voice='Npc_Quest/508798',Text='怎么样，到现在还相信赛达的谎言？以为黑炎龙真是屠杀同族的暴君？',Speaker=813881,}",
  [508799] = "{id=508799,Voice='Npc_Quest/508799',Text='哈哈哈...这一切不过是我略施小计。',Speaker=813881,}",
  [508800] = "{id=508800,Voice='Npc_Quest/508800',Text='黑炎龙阁下，该让你尝尝……被活活抽干力量的滋味了。',Speaker=813881,}",
  [508801] = "{id=508801,Voice='Npc_Quest/508801',Text='这一局真正的饵是我自己！',Speaker=813872,}",
  [508803] = "{id=508803,Voice='Npc_Quest/508803',Text='不可能……！无名者你怎么可能和黑炎龙联手？！你们根本不可能信任彼此！！',Speaker=813881,}",
  [508818] = "{id=508818,Voice='Npc_Quest/508818',Text='向我求饶吧，本座会把你和其他垃圾们的哀嚎，好好收藏起来。',Speaker=813878,}",
  [508819] = "{id=508819,Voice='Npc_Quest/508819',Text='杀了我，我的同伴自然会回到时空乱流回收站中，没必要那么麻烦！',Speaker=813881,}",
  [508820] = "{id=508820,Voice='Npc_Quest/508820',Text='用我同僚的骸骨当垃圾的容器——你连谈条件的资格都没有！',Speaker=813878,}",
  [508821] = "{id=508821,Voice='Npc_Quest/508821',Text='只有一人的黑炎龙阁下？真是一个笑话，看看这荒芜的沼泽，不会有新的龙族加入你们，暗爪营名存实亡，可悲啊。',Speaker=813881,}",
  [508822] = "{id=508822,Voice='Npc_Quest/508822',Text='而你最终只会成为一个守墓者。你拿什么与我们迎战？哈哈哈……哈哈哈！！！',Speaker=813881,}",
  [508823] = "{id=508823,Voice='Npc_Quest/508823',Text='看着我的眼睛……告诉我，你还剩下什么？拿什么对抗我们！你根本不是渴望你的同僚被复活，而是害怕打败仗！',Speaker=813881,}",
  [508824] = "{id=508824,Voice='Npc_Quest/508824',Text='看着我的眼睛。',Speaker=813880,}",
  [508825] = "{id=508825,Voice='Npc_Quest/508825',Text='别看他的眼睛——！',Speaker=813872,}",
  [508826] = "{id=508826,Voice='Npc_Quest/508826',Text='我……还有……永不失败的自己！',Speaker=813878,}",
  [508827] = "{id=508827,Voice='Npc_Quest/508827',Text='对，就是你！呵呵~这具身躯我收下了！',Speaker=813880,}",
  [508828] = "{id=508828,Voice='Npc_Quest/508828',Text='追上他！',Speaker=813872,}",
  [508829] = "{id=508829,Voice='Npc_Quest/508829',Text='从这些时空垃圾身上获取更多的坍缩器！',Speaker=813872,}",
  [508830] = "{id=508830,Voice='Npc_Quest/508830',Text='超时空坍缩器可以用于关闭超时空之眼。',Speaker=813872,}",
  [508831] = "{id=508831,Voice='Npc_Quest/508831',Text='黑炎龙，你已经和所有时空乱流回收站中的我们一样，都是这个世界抛弃的错误。',Speaker=813880,}",
  [508832] = "{id=508832,Voice='Npc_Quest/508832',Text='看看现在的你，不再高高在上，不再孤独挣扎，你终于找到了同类。',Speaker=813880,}",
  [508833] = "{id=508833,Voice='Npc_Quest/508833',Text='我是谁……',Speaker=813878,}",
  [508834] = "{id=508834,Voice='Npc_Quest/508834',Text='你是我的同谋，你自由了，不需要再背负过去的荣耀，也无需再为与你无关的世界牺牲。',Speaker=813880,}",
  [508835] = "{id=508835,Voice='Npc_Quest/508835',Text='（咆哮）呃啊——',Speaker=813906,}",
  [508836] = "{id=508836,Voice='Npc_Quest/508836',Text='很好，用他们的鲜血向我证明，你已经彻底臣服于我！',Speaker=813880,}",
  [508837] = "{id=508837,Voice='Npc_Quest/508837',Text='以时空之名，审判你们！',Speaker=813942,}",
  [508838] = "{id=508838,Voice='Npc_Quest/508838',Text='扫兴的家伙！',Speaker=813880,}",
  [508839] = "{id=508839,Voice='Npc_Quest/508839',Text='呃啊——我究竟是谁……',Speaker=813878,}",
  [508840] = "{id=508840,Voice='Npc_Quest/508840',Text='这个参宿四……居然搞这么大动静，连死去的龙战士都敢复活。真是完全没把管理时空的我放在眼里。',Speaker=813942,}",
  [508841] = "{id=508841,Voice='Npc_Quest/508841',Text='不过他自己也摊上大事了，他的命运轨迹正在断裂，再继续下去，他也会发展成“错误的存在”',Speaker=813942,}",
  [508842] = "{id=508842,Voice='Npc_Quest/508842',Text='所谓的错误存在的判定标准？',Speaker=813872,}",
  [508843] = "{id=508843,Voice='Npc_Quest/508843',Text='简单来说就是偏离时间女神书写的命运轨迹，在诸神黄昏后，我就像个勤快的清洁工，把那些背离了命运轨迹的错误，打包进时空乱流回收站中。',Speaker=813942,}",
  [508844] = "{id=508844,Voice='Npc_Quest/508844',Text='说起来，时空乱流回收站还是由一名神族建立，因为在当时错误的存在给这个世界带来了混乱，我们不得不做出这样的决定。',Speaker=813942,}",
  [508845] = "{id=508845,Voice='Npc_Quest/508845',Text='距今为止，除了出逃者以外的所有时空垃圾都有备案记录。',Speaker=813942,}",
  [508846] = "{id=508846,Voice='Npc_Quest/508846',Text='而参宿四……正一步步走向那里。除非我们能帮他恢复身份认知。',Speaker=813942,}",
  [508847] = "{id=508847,Voice='Npc_Quest/508847',Text='不准你这么做！！黑炎龙大人才不是什么时空垃圾！他是我们的王！是暗爪营的希望！！',Speaker=813885,}",
  [508848] = "{id=508848,Voice='Npc_Quest/508848',Text='喂喂喂，我又没说放弃治疗。你这小家伙看起来倒是和参宿四小时候很像嘛，我回溯过他的过去，小时候的他还没有现在这么讨厌。',Speaker=813942,}",
  [508849] = "{id=508849,Voice='Npc_Quest/508849',Text='眼下我们需要找到能够唤醒他记忆的东西。只有那些最珍贵的记忆，才能吹散他心中的迷雾。',Speaker=813942,}",
  [508850] = "{id=508850,Voice='Npc_Quest/508850',Text='渴望复活龙战士是他的执念，也就说明他和那些死去的战友有着极深的情感联系。从那些龙战士复活体中入手！',Speaker=813872,}",
  [508851] = "{id=508851,Voice='Npc_Quest/508851',Text='我知道龙战士复活体在哪里！我把他们藏在了……藏在了只有我知道的秘密基地！',Speaker=813885,}",
  [508852] = "{id=508852,Voice='Npc_Quest/508852',Text='走！快一点哟~',Speaker=813885,}",
  [508877] = "{id=508877,Voice='Npc_Quest/508877',Text='我曾经用结界掩盖了我们正在修复天地树的痕迹，但现在这个结界已经被破坏了。',Speaker=813872,}",
  [508878] = "{id=508878,Voice='Npc_Quest/508878',Text='这些不是普通的破坏痕迹，而是出逃者故意留下的挑衅。出逃者已经察觉到我们的行动了。',Speaker=813872,}",
  [508879] = "{id=508879,Voice='Npc_Quest/508879',Text='不必躲藏了——我知道你在看着！',Speaker=813872,}",
  [508880] = "{id=508880,Voice='Npc_Quest/508880',Text='你说错了，这不是挑衅，这是宣战！我一定会阻止你做这一切！',Speaker=813880,}",
  [508881] = "{id=508881,Voice='Npc_Quest/508881',Text='既然当初是我决定离开你，离开这个世界，我的命运才因此被改写！那么现在——就该由我来决定如何毁灭你和这个世界！！',Speaker=813880,}",
  [508882] = "{id=508882,Voice='Npc_Quest/508882',Text='我和你，到底是什么关系？',Speaker=813872,}",
  [508883] = "{id=508883,Voice='Npc_Quest/508883',Text='我们曾互为半身！但此刻背道而驰！',Speaker=813880,}",
  [508891] = "{id=508891,Voice='Npc_Quest/508891',Text='还差最后一步——希望之星。',Speaker=813871,}",
  [508892] = "{id=508892,Voice='Npc_Quest/508892',Text='想要拿到它……就得去赐福密林找到沉眠的尼德霍格。',Speaker=813871,}",
  [508893] = "{id=508893,Voice='Npc_Quest/508893',Text='也正是因为她的沉眠，那里的时间早已紊乱不堪。',Speaker=813871,}",
  [508894] = "{id=508894,Voice='Npc_Quest/508894',Text='我会先稳定赐福密林的时间流，否则你们踏入的瞬间，便会被时间吞噬。',Speaker=813871,}",
  [508895] = "{id=508895,Voice='Npc_Quest/508895',Text='等我信号——时机到了，我会为你们引路。',Speaker=813871,}",
  [508896] = "{id=508896,Voice='Npc_Quest/508896',Text='快了，等待拿到希望之星后，我们就能终结这一切的混乱。',Speaker=813872,}",
  [508897] = "{id=508897,Text='无相沼泽的迷雾中，死亡的气息如影随形。\n成堆的龙族白骨散落荒野，像是某种禁忌仪式的残骸。而在这些骸骨之间，游荡着一群\"活着\"的龙族——他们的眼神空洞，动作僵硬，仿佛早已被抽走了灵魂。\n在这片死寂之地，唯有渴望加入暗爪营的小黑龙托尔斯，眼中还跳动着希望的火光。\n与此同时，自称斯诺的龙族向主角团求助，声称黑炎龙已被出逃者操控，开始屠戮同族。但随着调查深入，一个更可怕的真相浮出水面——密道中的灵魂转存仪碎片、复活体血液报告、实验日志......以及一份黑炎龙与出逃者签订的合作契约。\n原来，那些被\"屠杀\"的龙族，是早已死去的龙战士。以他们龙骨制作的复活体被时空垃圾寄生，以伪龙的形态\"复活\"。当黑炎龙识破这场骗局，猎杀便开始了——他要用黑炎净化这些亵渎亡者的存在。\n\"我们只是想回家......\"撕下伪装的时空垃圾赛达嘶吼着，\"就像龙族想要离开深渊之湖一样！我们不是天生的错误，是错误的世界让我们成了错误！\"\n无名者第一次动摇了。如果诡计能在混沌中建立秩序，它是否也值得被接纳？\n然而，黑炎龙的黑炎突然席卷而来，所有时空垃圾全部毙命。\"你的怜悯，只会用更多龙骨铺就他们'归巢'的路！\"他在黑炎中冷笑，转身消失在迷雾里。面对黑炎龙的质疑，无名者并未沉默，而是决定追上他的脚步。\n此后，无名者变了。当冒险者察觉异样时，他只留下一句谜语：\"智慧如果被过去定义的规则束缚……那么所有人都无法走出深渊之湖\"\n陷阱布下，猎物入网——当出逃者得意地现身时，却不知眼前的\"黑炎龙\"正是无名者所扮，这不过是以其人之道还治其人之身。\n然而被禁锢的出逃者，却用最锋利的言语刺穿了黑炎龙的心防：\"你守护的暗爪营还剩什么？一堆白骨，和你这可怜的暴君名号。\"\n黑炎龙因此被出逃者操控，成为对抗冒险团的最强力量。\n就在黑炎龙即将崩溃时，小黑龙托尔斯的声音划破阴霾：\"只要黑炎还在，暗爪营就会再次壮大！\"\n在小黑龙托尔斯的鼓舞下，黑炎重燃。黑炎龙挣脱出逃者操控，将黑炎之星抛向主角团后，不再回头！\n无相沼泽的尽头，新的火把正在点燃。\n现在，三颗龙族之星已汇聚，天地树的生命正在缓慢复苏。而最后的答案，将在赐福密林的深处揭晓——那里沉睡着尼德霍格，会带来怎样的启示？\n而智慧与诡计，也终有一战。',}",
  [508910] = "{id=508910,Voice='Npc_Quest/508910',Text='以时间之名，溯流而上——诺顿，响应时空的召唤。',Speaker=813966,}",
  [508911] = "{id=508911,Voice='Npc_Quest/508911',Text='诺顿没有回应。不出意外，那里已经发生了意外。',Speaker=813966,}",
  [508912] = "{id=508912,Voice='Npc_Quest/508912',Text='诺顿的沉默，意味着沉眠之地已经成为诡计的猎场，我们该行动了！',Speaker=813967,}",
  [508913] = "{id=508913,Voice='Npc_Quest/508913',Text='听我说，你们的任务优先级得重新排序：第一，确保尼德霍格躯体未被侵扰；第二，查明三头龙状况；第三，安全取得生命之星。',Speaker=813966,}",
  [508914] = "{id=508914,Voice='Npc_Quest/508914',Text='这一次我仍无法同行，但我会时刻监控时间线的波动。',Speaker=813966,}",
  [508915] = "{id=508915,Voice='Npc_Quest/508915',Text='祝你们好运，虽然运气通常是最靠不住的东西！',Speaker=813966,}",
  [508916] = "{id=508916,Voice='Npc_Quest/508916',Text='好了，出发吧。别让我在你们搞出大乱子之后不得不出现……',Speaker=813966,}",
  [508917] = "{id=508917,Voice='Npc_Quest/508917',Text='我为什么握着这把剑。',Speaker=813969,}",
  [508918] = "{id=508918,Voice='Npc_Quest/508918',Text='孩子，你握剑的姿势不对。',Speaker=813970,}",
  [508919] = "{id=508919,Voice='Npc_Quest/508919',Text='这该死的生长痛啊……',Speaker=813971,}",
  [508934] = "{id=508934,Voice='Npc_Quest/508934',Text='看落叶的流向，并不是时间自然流动的轨迹，而是交错的。',Speaker=813967,}",
  [508935] = "{id=508935,Voice='Npc_Quest/508935',Text='入……侵……者……出……现……清……除……',Speaker=813976,}",
  [508936] = "{id=508936,Voice='Npc_Quest/508936',Text='他就是三头龙——诺顿！',Speaker=813967,}",
  [508937] = "{id=508937,Voice='Npc_Quest/508937',Text='清……除……',Speaker=813976,}",
  [508947] = "{id=508947,Voice='Npc_Quest/508947',Text='力……量……时……间……',Speaker=813976,}",
  [508948] = "{id=508948,Voice='Npc_Quest/508948',Text='诺顿被抽取的时间之力被藏在缺口中！！',Speaker=813967,}",
  [508949] = "{id=508949,Voice='Npc_Quest/508949',Text='现在，我们只有找到诺顿的时间之力，帮助他恢复意识，才能知道尼德霍格的行踪。',Speaker=813967,}",
  [508950] = "{id=508950,Voice='Npc_Quest/508950',Text='我们进入了异时空……这里的时间停滞了。',Speaker=813967,Option='{这到底是哪儿,0},{出逃者为什么这么做,0}',}",
  [508951] = "{id=508951,Voice='Npc_Quest/508951',Text='查看那些凝固的气流——它们被时间冻结了，这上面也许会提供线索。',Speaker=813967,}",
  [508952] = "{id=508952,Voice='Npc_Quest/508952',Text='这些不是普通的气流——是时空废气！我们就在——',Speaker=813967,Option='{时空乱流回收站中,0},{出逃者逃出的地方,0}',}",
  [508953] = "{id=508953,Voice='Npc_Quest/508953',Text='看来出逃者驱动了第四个时空矩阵，并将黄金树与时空乱流回收站链接。黄金树上的缺口因此而生。',Speaker=813967,}",
  [508954] = "{id=508954,Voice='Npc_Quest/508954',Text='力量的来源——我希望不会是尼德霍格，否则我们无法顺利取得生命之星。',Speaker=813967,Option='{但愿如此,0},{我有不好的预感,0}',}",
  [508955] = "{id=508955,Voice='Npc_Quest/508955',Text='只有将时间之力带给三头龙，我们才能知道沉眠之地，到底发生了什么！',Speaker=813967,}",
  [508956] = "{id=508956,Voice='Npc_Quest/508956',Text='他们，闻着味道来了。',Speaker=813967,}",
  [508957] = "{id=508957,Voice='Npc_Quest/508957',Text='三头龙的东西，还是被你们找到了！',Speaker=813977,}",
  [508958] = "{id=508958,Voice='Npc_Quest/508958',Text='看看我们的身体，我们不过是一些老的老，残的残，我们等了很久，筹备了很久，每次出口的开启，都有你们两个所谓正确的人挡路。',Speaker=813977,}",
  [508959] = "{id=508959,Voice='Npc_Quest/508959',Text='知道在回收站里活着的滋味吗？',Speaker=813977,}",
  [508960] = "{id=508960,Voice='Npc_Quest/508960',Text='每一秒都在生锈腐烂，又被迫清醒着感受！看看啊，现在留在这里的只剩下一些老弱病残，没有战斗力的我们，只能等待大人计划成功。',Speaker=813977,}",
  [508961] = "{id=508961,Voice='Npc_Quest/508961',Text='那三头龙和把我们扔进这里的“那些人”是一伙的！可讽刺的是，他的时间之力，反倒让我们可以在这里多活了一时。',Speaker=813977,}",
  [508962] = "{id=508962,Voice='Npc_Quest/508962',Text='时间之力属于诺顿，我们必须带走它。',Speaker=813967,}",
  [508963] = "{id=508963,Voice='Npc_Quest/508963',Text='既然时间之力无法属于我们，那我们就毁了它！没有时间之力，你们也别想好过。',Speaker=813977,Option='{别冲动,0},{我们再聊聊,0}',}",
  [508964] = "{id=508964,Voice='Npc_Quest/508964',Text='拦住他，收回时间之力！',Speaker=813967,}",
  [508965] = "{id=508965,Voice='Npc_Quest/508965',Text='我们不是天生的错误，是错误的世界让我们成了错误！',Speaker=813973,}",
  [508967] = "{id=508967,Voice='Npc_Quest/508967',Text='救命，这些乱流会像抹除错误一样，将我们杀死！',Speaker=813973,}",
  [508968] = "{id=508968,Voice='Npc_Quest/508968',Text='时间之力可以终止气流对我们的侵蚀。',Speaker=813974,}",
  [508970] = "{id=508970,Voice='Npc_Quest/508970',Text='“未来之力”？只有大人能带给我们未来！',Speaker=813977,}",
  [509031] = "{id=509031,Voice='Npc_Quest/509031',Text='该你了。',Speaker=813967,}",
  [509040] = "{id=509040,Voice='Npc_Quest/509040',Text='凋零之力还在牵引着尼德霍格的力量！生命与凋零的界限还未分明！',Speaker=813967,}",
  [509041] = "{id=509041,Voice='Npc_Quest/509041',Text='重新划下生与死的界限！',Speaker=813967,}",
  [509081] = "{id=509081,Voice='Npc_Quest/509081',Text='谢谢你们，是你们让我想起了花开的声音。',Speaker=813982,}",
  [509082] = "{id=509082,Voice='Npc_Quest/509082',Text='你们不是敌人，就像天地树护生，黄金树容死一样，智慧可以引路，诡计可以破局。',Speaker=813982,}",
  [509083] = "{id=509083,Voice='Npc_Quest/509083',Text='你即是我，我即是你。',Speaker=813967,}",
  [509110] = "{id=509110,Voice='Npc_Quest/509110',Text='不对！快松手！！',Speaker=813967,}",
  [509111] = "{id=509111,Voice='Npc_Quest/509111',Text='我的诡计之力……正在被它反向抽取！',Speaker=813968,}",
  [509112] = "{id=509112,Voice='Npc_Quest/509112',Text='这些树魂是黄金树用我的力量滋生的。',Speaker=813968,}",
  [509113] = "{id=509113,Voice='Npc_Quest/509113',Text='清除异己！',Speaker=813993,}",
  [509114] = "{id=509114,Voice='Npc_Quest/509114',Text='大人……被吞了……',Speaker=813992,}",
  [509115] = "{id=509115,Voice='Npc_Quest/509115',Text='难怪天地树以切断外界链接的方式来自保，并非是天地树不愿意接纳黄金树，而是她早已感应到来自黄金树的威胁——',Speaker=813967,}",
  [509116] = "{id=509116,Voice='Npc_Quest/509116',Text='黄金树早已被出逃者种下的诡计之力腐蚀。而现在，黄金树要的不仅是出逃者的力量，还要吞噬一切，包括它的创造者！',Speaker=813967,}",
  [509117] = "{id=509117,Voice='Npc_Quest/509117',Text='在诡计彻底失控前！我们必须阻止它！',Speaker=813967,}",
  [509118] = "{id=509118,Voice='Npc_Quest/509118',Text='救命',}",
  [509123] = "{id=509123,Voice='Npc_Quest/509123',Text='停下，无名者。',Speaker=813966,}",
  [509124] = "{id=509124,Voice='Npc_Quest/509124',Text='你的愚蠢和仁慈正在危及我们的时间线！让黄金树和诡计一同湮灭，才是正确的选择！',Speaker=813966,}",
  [509125] = "{id=509125,Voice='Npc_Quest/509125',Text='时间线有其秩序，不容分割，不容改写。若黄金树成为时空乱流回收站的载体，那么时间线便会因此产生分支。',Speaker=813966,}",
  [509126] = "{id=509126,Voice='Npc_Quest/509126',Text='这违背了时间管理局的铁律：时间只有一条，秩序不容撕裂。',Speaker=813966,}",
  [509127] = "{id=509127,Voice='Npc_Quest/509127',Text='你所维护的秩序，到底是什么？',Speaker=813967,}",
  [509128] = "{id=509128,Voice='Npc_Quest/509128',Text='奥斯卡，你是在维护秩序，还是在恐惧未知？',Speaker=813967,}",
  [509129] = "{id=509129,Voice='Npc_Quest/509129',Text='真正的秩序不应该是建立在无辜者的牺牲之上。',Speaker=813967,}",
  [509130] = "{id=509130,Voice='Npc_Quest/509130',Text='无名者……看来我不该解除对你的怀疑。你已从关联者，升级为——出逃者的帮凶。冒险者，清除所有扰乱秩序者！',Speaker=813966,Option='{抱歉,0},{这一次我不能帮你,0}',}",
  [509131] = "{id=509131,Voice='Npc_Quest/509131',Text='疯了！！时间的秩序，绝不允许被改写！',Speaker=813966,}",
  [509132] = "{id=509132,Voice='Npc_Quest/509132',Text='分开行动！我会拖住奥斯卡！',Speaker=813967,}",
  [509133] = "{id=509133,Voice='Npc_Quest/509133',Text='冒险者，必须救出逃者！越快越好！',Speaker=813967,}",
  [509134] = "{id=509134,Voice='Npc_Quest/509134',Text='真是讽刺。我居然会沦落到需要你们来救。我失败了。',Speaker=813968,}",
  [509135] = "{id=509135,Voice='Npc_Quest/509135',Text='听着，还没有结束。我们必须说服奥斯卡，否则一切只会回到原点！',Speaker=813967,}",
  [509136] = "{id=509136,Voice='Npc_Quest/509136',Text='黄金树之泪，可以用于浇灌天地树根，两棵树因此才能共鸣。这样我们能让所有人都活下来！',Speaker=813967,}",
  [509137] = "{id=509137,Voice='Npc_Quest/509137',Text='够了！我绝不允许你让这家伙再次靠近天地树！',Speaker=814005,}",
  [509138] = "{id=509138,Voice='Npc_Quest/509138',Text='天地树已经因为自保而切断了为各个世界的供能，若再出差池，时间线会彻底崩溃！',Speaker=814005,}",
  [509139] = "{id=509139,Voice='Npc_Quest/509139',Text='现在唯一的路，是用生命之星治愈天地树！其余一切都是干扰！',Speaker=814005,}",
  [509140] = "{id=509140,Voice='Npc_Quest/509140',Text='把出逃者和时空垃圾扔回回收站，一切就能平息。为什么非要违背规则，把简单的事情搞得一团糟？！共存，不可能！',Speaker=814005,Option='{你有些冷血噢,0},{你就是怕工作麻烦,0}',}",
  [509141] = "{id=509141,Voice='Npc_Quest/509141',Text='短暂的平息只会迎来下一个出逃者，而龙族世代仍将困在深渊之湖中。',Speaker=813967,}",
  [509142] = "{id=509142,Voice='Npc_Quest/509142',Text='那正是他们的命运。秩序的存续，从来都需要牺牲，这一次，也不例外！',Speaker=814005,}",
  [509143] = "{id=509143,Voice='Npc_Quest/509143',Text='回来，智慧与诡计不应该分开。',Speaker=813967,}",
  [509144] = "{id=509144,Voice='Npc_Quest/509144',Text='哼…这可是你自找的！别到时候又想把我踢开！',Speaker=813968,}",
  [509145] = "{id=509145,Voice='Npc_Quest/509145',Text='奥斯卡，吾会告诉你，秩序，该如何守护。',Speaker=813983,}",
  [509146] = "{id=509146,Voice='Npc_Quest/509146',Text='停下！！',Speaker=813982,}",
  [509147] = "{id=509147,Voice='Npc_Quest/509147',Text='洛基~你的选择十分冒险！但世界最有趣的进步，就是从冒险开始的！',Speaker=813982,}",
  [509148] = "{id=509148,Voice='Npc_Quest/509148',Text='冒险？这叫拿九界当实验品！时间线一旦分裂，谁来管？谁来修？谁来擦屁股？没有维系者，就等于没有秩序！',Speaker=813966,}",
  [509149] = "{id=509149,Voice='Npc_Quest/509149',Text='共存的大话谁不会说？要是当初就能平衡，干嘛等到现在——让天地树快死了、龙族快打散架、连我加班都加到咳咳咳……',Speaker=813966,}",
  [509150] = "{id=509150,Voice='Npc_Quest/509150',Text='质疑是智慧的起点，奥斯卡。吾不可否认空谈无益。',Speaker=813983,}",
  [509151] = "{id=509151,Voice='Npc_Quest/509151',Text='过去，吾曾以为——是诡计带来了灾祸。诸神黄昏之后，吾将诡计放逐，以为阴谋、欺骗将破坏世界的秩序。',Speaker=813983,}",
  [509152] = "{id=509152,Voice='Npc_Quest/509152',Text='可正是分离之后，智慧在孤独中看见了共存，诡计在放逐中学会了责任。',Speaker=813983,}",
  [509153] = "{id=509153,Voice='Npc_Quest/509153',Text='它们各自走过深渊，才终于看清——真正的平衡，不在单一的自己，而在两者的共行之中。',Speaker=813983,}",
  [509154] = "{id=509154,Voice='Npc_Quest/509154',Text='往后，吾将穿梭于天地树、黄金树两条时间线之间，维系它们的平衡。',Speaker=813983,}",
  [509155] = "{id=509155,Voice='Npc_Quest/509155',Text='噢，这番演讲倒是很符合神族的出场。但我凭什么把整个时间线的未来，押在你的顿悟上？',Speaker=813966,}",
  [509156] = "{id=509156,Voice='Npc_Quest/509156',Text='奥斯卡~你这么紧张，是因为害怕失控，对不对？',Speaker=813982,}",
  [509157] = "{id=509157,Voice='Npc_Quest/509157',Text='绝对的控制，才会阻止生命自由生长呢！吾知道自从诸神黄昏，时间线出现错误后，为了维持这条时间线不崩溃，你一直一直都非常非常努力！',Speaker=813982,}",
  [509158] = "{id=509158,Voice='Npc_Quest/509158',Text='但吾相信，从深渊里开出的花，比温室里的更坚强！好啦，时间的管理者——奥斯卡，放松一点好吗！？',Speaker=813982,}",
  [509159] = "{id=509159,Voice='Npc_Quest/509159',Text='好吧！但我会紧紧盯着你们的！记住——但凡有一点出格的迹象，我的修正协议可不会留情！',Speaker=813966,}",
  [509160] = "{id=509160,Voice='Npc_Quest/509160',Text='还有你，早点交出生命之星，回到你的遮阳伞下睡觉，长时间的降临对你而言没有好处。',Speaker=813966,}",
  [509161] = "{id=509161,Voice='Npc_Quest/509161',Text='好的好的！吾知道啦！那现在，请和吾一起去安慰天地树吧！',Speaker=813982,}",
  [509162] = "{id=509162,Voice='Npc_Quest/509162',Text='它因为太害怕，把自己关起来了呢~吾要亲口告诉它，已经没事啦~',Speaker=813982,}",
  [509163] = "{id=509163,Voice='Npc_Quest/509163',Text='天地树啊，收起您的悲鸣。',Speaker=813982,}",
  [509164] = "{id=509164,Voice='Npc_Quest/509164',Text='恐惧的荆棘或许能构筑屏障，但真正的守护，从来不是拒绝，而是勇敢地拥抱它~',Speaker=813982,}",
  [509165] = "{id=509165,Voice='Npc_Quest/509165',Text='试试，好吗？',Speaker=813982,}",
  [509166] = "{id=509166,Voice='Npc_Quest/509166',Text='太好啦！你接纳了它！',Speaker=813982,}",
  [509167] = "{id=509167,Voice='Npc_Quest/509167',Text='我该走了，别担心我，风会带来吾对你们的赐福。',Speaker=813982,}",
  [509168] = "{id=509168,Voice='Npc_Quest/509168',Text='记住，回到你的黄金树下后，把自己掩藏起来，我可不想你……再出事。',Speaker=813966,}",
  [509169] = "{id=509169,Voice='Npc_Quest/509169',Text='尼德霍格大人再见，再见……',}",
  [509170] = "{id=509170,Voice='Npc_Quest/509170',Text='尼德霍格大人，我们会想你的~~',}",
  [509171] = "{id=509171,Voice='Npc_Quest/509171',Text='谢谢您…永远谢谢您！',}",
  [509172] = "{id=509172,Voice='Npc_Quest/509172',Text='吾以智慧与诡计之名起誓——自此，行于天地树与黄金树之间，维系两条时间线的平衡。',Speaker=813983,}",
  [509173] = "{id=509173,Voice='Npc_Quest/509173',Text='孩子们抬起你们的头颅，看向吾，你们不再背负错误之名。',Speaker=813983,}",
  [509174] = "{id=509174,Voice='Npc_Quest/509174',Text='跟随吾，成为时空的旅人，时空乱流回收站，因为黄金树的依托，将成为你们的新的家园。',Speaker=813983,}",
  [509175] = "{id=509175,Voice='Npc_Quest/509175',Text='永远追随大人！！',Speaker=813973,}",
  [509176] = "{id=509176,Voice='Npc_Quest/509176',Text='以吾洛基之名，深渊之湖的千年枷锁，于此刻终结！',Speaker=813983,}",
  [509177] = "{id=509177,Voice='Npc_Quest/509177',Text='龙族，你们的守护之责结束了。这片天地，再无边界能束缚你们的双翼。',Speaker=813983,}",
  [509178] = "{id=509178,Voice='Npc_Quest/509178',Text='去吧，属于你们的时代开始了。',Speaker=813983,}",
  [509179] = "{id=509179,Voice='Npc_Quest/509179',Text='我们自由了！自由了！',}",
  [509180] = "{id=509180,Voice='Npc_Quest/509180',Text='爷爷，自由的意思是我可以飞向任何地方吗！？',Speaker=813995,}",
  [509181] = "{id=509181,Voice='Npc_Quest/509181',Text='是的，自由就是可以在天空中俯瞰每一个角落。',Speaker=813996,}",
  [509182] = "{id=509182,Voice='Npc_Quest/509182',Text='哼！虽然麻烦得要死，但这份敢于颠覆规则的气概，我暂且记下了。',Speaker=813966,}",
  [509183] = "{id=509183,Voice='Npc_Quest/509183',Text='也许真该给时空乱流回收站改个名字了，“时空交汇所”，听起来是不是顺耳多了！？',Speaker=813966,}",
  [509184] = "{id=509184,Voice='Npc_Quest/509184',Text='等等，这能量波动！！！果然，麻烦永远在下一站等着我！',Speaker=813966,}",
  [509185] = "{id=509185,Voice='Npc_Quest/509185',Text='又有出逃者了！！！',Speaker=813966,}",
  [509198] = "{id=509198,Text='在赐福密林深处，原初之龙尼德霍格的躯体沉眠于黄金树下。这棵作为天地树投影的黄金树，承载着本源之力的余韵，亦蕴藏着未知潜能。时空龙奥斯卡委托冒险团前往请示尼德霍格的灵体，以获取生命之星。然而抵达后，发现密林已陷入时空乱流，光阴错乱。守护者三头龙诺顿因时间之力被剥夺，陷入狂暴。为寻回三头龙的时间之力，冒险团至时空乱流回收站。\n无名者亲眼目睹时空垃圾被乱流侵蚀的痛苦。他意识到：所谓“清除错误存在”的秩序，实则是以无数无辜者的流放为代价。这份残酷，正是昔日他所信奉的“正确”。时间之力回归，三头龙诺顿恢复清醒后，以守护者资格请示尼德霍格的灵体降临，但尼德霍格并未降临，众人发现尼德霍格力量已被窃取。\n为寻回尼德霍格的力量，诺顿以生命为代价，窥见尼德霍格的时间轨迹：她的力量被出逃者分裂，分别注入——时空矩阵和赫格尼剑冢。冒险团前往两地，夺回尼德霍格的力量。但即使尼德霍格的力量全部回归，灵体却仍未显现。\n黄金树疯狂生长，枝干结出大量奇异果实，果实中充斥着时空垃圾的集体意志与出逃者的诡计。无名者推断：出逃者已关闭古木之门，切断天地树对黄金树的本源牵引。唯有如此，黄金树才能摆脱投影身份，孕育独立意识，成为新世界的本源。\n在古木之门处，冒险团发现尼德霍格将自己囚禁于对自己的失望中，而这样的力量就是关闭古木之门的力量来源。最后，冒险者引导尼德霍格忆起她就是生命的起点和归途后，尼德霍格灵体现身，古木之门也再次开启。此时，无名者提出新构想：将黄金树之泪融入天地树根脉，使黄金树成为天地树的延伸，托起时空乱流回收站。然而此时的出逃者却因为自己的计划再次失败而向无名者挑起战争。\n在古木之门前，无名者恢复——无名者原为神族洛基的“智慧”，而出逃者正是其“诡计”，二者本为一体，因洛基的终极抉择而分离。无名者试图说服出逃者合作，但对方因长久被“智慧”审判而本能抗拒。就在此时，时空垃圾们表达对家渴望。出逃者终被触动，同意合作。他亲自执起黄金树之泪，欲将其融入天地树——却遭黄金树反噬！原来黄金树在诡计之力滋养下已生出独立意志，竟借机吞噬出逃者的力量，催生出大量树魂，反向侵蚀天地树，意图取而代之！天地树因本源受胁，本能启动自保机制，封闭所有能量通道，陷入沉眠。世界动摇，万物凋零，时空不稳。\n无名者决定解救出逃者，切断树魂力量来源。然而，时空龙奥斯卡降临，出手阻止。他坚持时间秩序铁律——时间只有一条，绝不容分割。但无名者却认为秩序，不该建立在无辜者的牺牲之上。二人激战，无名者意识到面对强敌，无名者和出逃者必须合二为一。于是，智慧与诡计重聚——神族洛基归来。\n双洛基与奥斯卡展开激战，难分胜负。直至尼德霍格平息争端。她认可洛基的尝试，但奥斯卡仍有疑虑，他更关心谁来维系第二根时间线的平衡。而洛基宣告自己将穿梭于两条时间线之间维系平衡。\n最终，尼德霍格交出生命之星，并将黄金树之泪融入其中，由冒险团浇灌天地树之根。金光绽放，两树共鸣——黄金树不再为投影，天地树不再为孤主，二者互为半身，共承世界之重。\n洛基带领所有时空垃圾，迈向新家园；龙族挣脱千年枷锁，重获自由。\n尘埃落定之际，黄金树裂隙再现——一只身姿修长的白色猫族生灵浮现，低语：“黄金树背后的世界，需要你们。”奥斯卡凝望裂隙，心知其后，正是被封印的耶梦加得。两树融合之力，已动摇最后封印。\n命运的齿轮，再次转动。',}",
  [509204] = "{id=509204,Text='[c][ffff00][PlayerName][-][/c]，是我……赛尼亚~黄金树背后的世界有我们必须阻止的灾难……',Speaker=814008,Option='{赛尼亚？,0},{你在瞎说什么！？,0}',}",
  [509205] = "{id=509205,Text='我的时间不多了，快跟我来！',Speaker=814008,}",
  [509206] = "{id=509206,Text='赛尼亚变成猫了？这……这不合理啊！',Speaker=814007,Option='{我要去找赛尼亚！,0},{它真的是赛尼亚吗？,0}',}",
  [509207] = "{id=509207,Text='在确定这只猫与赛尼亚的关系之前，都不要贸然行动。不过，它以赛尼亚的身份来找你，肯定有重要原因。',Speaker=814007,}",
  [509208] = "{id=509208,Text='我要先去查查这猫什么来头……你等着我的消息！我会在合适的时机出现！',Speaker=814007,}",
  [509209] = "{id=509209,Text='黄金树裂隙异变，竟化作多重时空的交汇之门；一只自称“赛尼亚”的神秘白猫现身示警，却在奥斯卡质疑其身份时匆匆消失——它究竟是故人归来，还是灾厄的诱饵？',}",
  [509236] = "{id=509236,Voice='Npc_Quest/509236',Text='我一直在等你！外面给不了你们要的答案。',Speaker=814008,}",
  [509251] = "{id=509251,Voice='Npc_Quest/509251',Text='记住！冰雪之下往往隐藏着最灼热的真相。愿时空指引你前行。 ',Speaker=814015,}",
  [509252] = "{id=509252,Voice='Npc_Quest/509252',Text='伊斯加尔特在排斥你，但[c][ffff00]雪花之冠[-][/c]会为你开路。',Speaker=814016,}",
  [509260] = "{id=509260,Voice='Npc_Quest/509260',Text='雪花之冠出现了！快与它共鸣！',Speaker=814016,}",
  [509261] = "{id=509261,Voice='Npc_Quest/509261',Text='戴上这顶[c][ffff00]雪花之冠[-][/c]，与我缔结盟约，你才能获得可以拯救[c][ffff00]赛尼亚[-][/c]的力量。',Speaker=814017,}",
  [509262] = "{id=509262,Voice='Npc_Quest/509262',Text='雪花之冠，已经成为你在此地通行的凭证。现在去雪霜银堡找[c][ffff00]呼嘟嘟[-][/c]，他会告诉你觉醒雪花之冠的办法。',Speaker=814017,}",
  [509263] = "{id=509263,Voice='Npc_Quest/509263',Text='作为与我并肩之人，你必须足够强大。只有完全掌握这份力量，你才能穿越前方的危机，找到巴格！',Speaker=814017,}",
  [509264] = "{id=509264,Voice='Npc_Quest/509264',Text='去那里带回你的朋友赛尼亚。至于我的身躯，那是我自己的战场，我会亲手夺回。我无法久留，接下来的路，仍由那白猫代我同行。尽管它聒噪又不稳重……',Speaker=814017,}",
  [509299] = "{id=509299,Voice='Npc_Quest/509299',Text='看，这就是巴格向我许诺的进化。',Speaker=814017,}",
  [509300] = "{id=509300,Voice='Npc_Quest/509300',Text='他用卢甘族的数据，制作了大量这样的蛇蛋，再通过孵化池源源不断地制造出那些卢甘族的试验体。',Speaker=814017,}",
  [509301] = "{id=509301,Voice='Npc_Quest/509301',Text='而我，则被他选为原料，并不断把赛尼亚的力量作为燃料来炼化我，直到我彻底消失，成为仿伊米尔之心！',Speaker=814017,}",
  [509302] = "{id=509302,Voice='Npc_Quest/509302',Text='现在，把我们带回来的、真正的卢甘族蛇蛋放进去。',Speaker=814017,}",
  [509305] = "{id=509305,Voice='Npc_Quest/509305',Text='巴格为封锁这里，在雪崩边界派出它的秘密武器天鹰座！',Speaker=814016,}",
  [509306] = "{id=509306,Voice='Npc_Quest/509306',Text='赛尼亚！看看他！你要等的人来了！醒来！',Speaker=814016,}",
  [509307] = "{id=509307,Voice='Npc_Quest/509307',Text='冒险者……我……',Speaker=814027,}",
  [509308] = "{id=509308,Voice='Npc_Quest/509308',Text='无用的残次品。看来巴格大人还是没能彻底抹除你的意志……',Speaker=814029,}",
  [509309] = "{id=509309,Voice='Npc_Quest/509309',Text='那么，就在我的身体中，看着我清理他们吧！',Speaker=814029,}",
  [509310] = "{id=509310,Voice='Npc_Quest/509310',Text='那是天鹰座——原本是伊斯加尔特虹吸能量的装置，如今被巴格控制。别把它当成普通的对手。',Speaker=814016,}",
  [509311] = "{id=509311,Voice='Npc_Quest/509311',Text='追上它！赛尼亚还在它的手中！',Speaker=814016,}",
  [509312] = "{id=509312,Voice='Npc_Quest/509312',Text='听着。你的雪花之冠能切换三种模式：[c][ffff00]物理模式、防御模式、魔法模式[-][/c]。',Speaker=814016,}",
  [509313] = "{id=509313,Voice='Npc_Quest/509313',Text='选择与你职业最契合的模式再迎战！ 这是我们救出赛尼亚的唯一方法。',Speaker=814016,Option='{记住了 ,0},{我会小心,0}',}",
  [509333] = "{id=509333,Voice='Npc_Quest/509333',Text='那具白猫之躯，承载着我的意识，却因久离本体，染上了太多猫的习性……它竟忘了自己曾是卢甘族，才会被这湖中负面情绪轻易动摇。拍下我的真容。让它亲眼看看，它的灵魂究竟属于谁。',Speaker=814031,}",
  [509334] = "{id=509334,Voice='Npc_Quest/509334',Text='很好。我这张脸，足以刺穿迷雾，唤醒那只笨猫。让它记住——我即是它，它并非是我。',Speaker=814031,}",
  [509335] = "{id=509335,Voice='Npc_Quest/509335',Text='不，我绝不会……伤害冒险者……',Speaker=814032,}",
  [509336] = "{id=509336,Voice='Npc_Quest/509336',Text='你还记得吗…我们在南门一起被波利追得满街跑的日子？',Speaker=814032,}",
  [509337] = "{id=509337,Voice='Npc_Quest/509337',Text='还有在你通过转职试炼时，那份照亮我们的勇气？',Speaker=814032,Option='{当然记得 ,0},{从未忘却,0}',}",
  [509338] = "{id=509338,Voice='Npc_Quest/509338',Text='太好了，冒险者你都记得，我们说好要一起走遍世界的每一个角落……',Speaker=814032,}",
  [509339] = "{id=509339,Voice='Npc_Quest/509339',Text='等着我...我一定会兑现我们的约定。',Speaker=814032,}",
  [509340] = "{id=509340,Voice='Npc_Quest/509340',Text='（他们快被黑色能量吃掉啦！呜……好难受！本喵来挡住它！你快去救剩下的卢甘族！）',Speaker=814016,}",
  [509341] = "{id=509341,Voice='Npc_Quest/509341',Text='（原来……当拉斯甘德就是这种感觉啊——在大家倒下前，先冲上去挡着！哼，累死本喵了，可别指望我天天这么英勇喵~）',Speaker=814016,}",
  [509356] = "{id=509356,Voice='Npc_Quest/509356',Text='┗|｀O′|┛ 嗷~~',Speaker=814016,}",
  [509357] = "{id=509357,Voice='Npc_Quest/509357',Text='风语为引，雪心为基，初心为念，星尘为证！以卢甘族的意志，扫清障碍！',Speaker=814016,}",
  [509358] = "{id=509358,Voice='Npc_Quest/509358',Text='冒险者，这是伊斯加尔特在考验我们的耐心。现在我以卢甘之王名义，赋予你磨砺自我的权利——继续收集散落在这片土地上的力量，让雪花之冠继续觉醒，你才有资格直面更深处的严寒。',Speaker=814016,}",
  [509363] = "{id=509363,Text='时空龙奥斯卡在黄金树的背后，捕捉到伊米尔之心的信号。\n与此同时，一只承载拉斯甘德意识的白猫，带着赛尼亚的委托穿过裂隙求助，奥斯卡判断雪花之地伊斯加尔特发生剧变，委托冒险者前往调查。\n冒险者穿越裂隙抵达伊斯加尔特，极端暴风雪遮蔽前路，白猫现身，道出真相——他的身躯正被前雷根贝勒研究员巴格炼化为仿制的伊米尔之心，而赛尼亚的意识与力量，正被当作燃料，一点点燃尽。\n在击败暴风眼取得大地初雪后，拉斯甘德为其铸成雪花之冠，授予冒险者通行资格与盟约。\n跟随拉斯甘德的指引，冒险者抵达白鹰族据点雪霜银堡。在这里，雪花之冠的力量通过历练逐渐苏醒。\n然而平静很快被打破——巴格控制被污染的低级卢甘族发动突袭，意图切断白鹰护卫队的赴前线支援。一场激战后，被污染的低级卢甘族并未死亡，而是化为一枚枚缠绕黑暗能量的蛇蛋。\n拉斯甘德短暂恢复人形，将其净化，托付冒险者护送它们返回蛇族的温床。沿途，巴格制造的卢甘族试验体不断阻挠，战斗之中，雪花之冠与冒险者的共鸣愈发深沉，最终唤醒了沉睡的雪花之钻。重返温床的那一刻，拉斯甘德回忆起自己曾目睹了族人被巴格改造的惨状，同时也通过意识连接，感受到赛尼亚越来越微弱的呼唤——她正在雪崩边界，作为被操控的武器投入战场。\n赶往雪崩边界的路上，风暴如刃。巴格控制的天鹰座降临，而在那庞然大物身前，站着被操控的赛尼亚。她的攻击在最后一刻停滞，眼中掠过挣扎的光。但下一刻，她被天鹰座强行回收，消失在风雪之中。天鹰号紧随而至，带走了一切，也引发了雪崩，前路阻断。\n为继续前进，拉斯甘德指引冒险者前往雪月镜湖，寻找能净化黑暗的不化之冰。湖心深处，耶梦加得的残留的负面情绪如潮水般吞噬而来，拉斯甘德的意识几乎崩溃。冒险者沉入他的意识之海，将徘徊在崩溃边缘的三个意识核心带回。而在那片混沌中，赛尼亚的残存意识如星火闪烁，为他们指引方向。\n带着不化之冰，众人前往古老的雪落圣坛。风语冰晶、不融雪心、初心之泪、极光星尘——四件圣物汇聚光芒，启动了破障仪式。圣光芒冲破雪崩的封锁，通往巴格腹地的道路终于敞开。\n白鹰族大军整装待发，战旗在风中猎猎作响……',}",
  [509367] = "{id=509367,Voice='Npc_Quest/509367',Text='报告报告！那块大黑石头已经被轰飞啦~但是白鹰护卫队探测到前方依旧存在隐患，所以还不能前行噢！',Speaker=814036,}",
  [509368] = "{id=509368,Voice='Npc_Quest/509368',Text='冒险者不要着急嘛~等白鹰先遣军扫清障碍后，我们再一起冲向霜雪之原吧！',Speaker=814036,}",
  [509377] = "{id=509377,Voice='Npc_Quest/509377',Text='我身旁的呼噜噜还在等你噢~',Speaker=851079,}",
  [509391] = "{id=509391,Voice='Npc_Quest/509391',Text='信任它，如同我信任你。',Speaker=814061,}",
  [509392] = "{id=509392,Voice='Npc_Quest/509392',Text='看准移动轨迹的间隙，穿过去！',Speaker=814061,}",
  [509393] = "{id=509393,Voice='Npc_Quest/509393',Text='（喵！这些雷电云竟然认出我们了！快换颜色伪装，跟本喵一样！喵~）',Speaker=814061,}",
  [509394] = "{id=509394,Voice='Npc_Quest/509394',Text='（伊斯加尔特的天空，属于敢于翱翔的人和会飞的猫！喵~）',Speaker=814061,}",
  [509431] = "{id=509431,Voice='Npc_Quest/509431',Text='别白费力气了，我听到了它的呼唤……它告诉我，要我帮你承担它的重量！',Speaker=814063,}",
  [509432] = "{id=509432,Voice='Npc_Quest/509432',Text='我说过，我会帮助你的。就让我来戴上它吧！雪花之冠的力量会属于我……我会带你离开这里。',Speaker=814063,}",
  [509433] = "{id=509433,Voice='Npc_Quest/509433',Text='冒险者，这是幻觉！巴格利用你对赛尼亚的羁绊设下陷阱——眼前的她，是假的！',Speaker=814062,}",
  [509434] = "{id=509434,Voice='Npc_Quest/509434',Text='真正的赛尼亚，她的意志在我的意识之海中受过千锤百炼。那是连我都认可的灵魂——高洁且坚韧！不会做出如此卑劣行为。',Speaker=814062,}",
  [509435] = "{id=509435,Voice='Npc_Quest/509435',Text='拿出你的勇气！击败她，只有亲手撕碎幻雪松林中的幻象，你的王冠才能真正进阶为深寒王冠！',Speaker=814062,}",
  [509442] = "{id=509442,Voice='Npc_Quest/509442',Text='愿深寒见证不灭的意志。',Speaker=814062,Option='愿深寒见证不灭的意志',}",
  [509443] = "{id=509443,Voice='Npc_Quest/509443',Text='现在，雪花之冠已从初雪进阶为深寒。从现在起，严寒听你号令，幻惑不再笼罩你。',Speaker=814062,}",
  [509455] = "{id=509455,Voice='Npc_Quest/509455',Text='即便寄宿在这具白猫的躯壳里，我依然可以踏上圣座，阻止巴格的阴谋！',Speaker=814061,}",
  [509456] = "{id=509456,Voice='Npc_Quest/509456',Text='呵——我们和巴格的博弈终于要进阶到最后阶段了。接下来，夺回我那完美的身躯、救出赛尼亚，就是头等大事。',Speaker=814061,}",
  [509457] = "{id=509457,Voice='Npc_Quest/509457',Text='（喵~红光终于消失了，感觉毛发都顺滑了不少呢~不过话说回来，那个坏蛋巴格连个影子都没露，真是一只缩头乌龟！）',Speaker=814061,}",
  [509458] = "{id=509458,Voice='Npc_Quest/509458',Text='哟，瞧瞧这顺滑的毛发，咱们的卢甘族领袖挺滋润呐？既然您这么气定神闲，怎么不直接扑进冰封之城把巴格挠死呢？',Speaker=814064,Option='{我们正准备过去,0},{马上抵达战场！,0}',}",
  [509459] = "{id=509459,Voice='Npc_Quest/509459',Text='急什么急~我知道您急着去找您那具完美的身躯，但您先别急。',Speaker=814064,}",
  [509460] = "{id=509460,Voice='Npc_Quest/509460',Text='巴格堆的防御层，比您赐给白鹰护卫队的战略冻肉还要硬。您这口小猫牙真要咬上去，也就是给巴格助助兴。',Speaker=814064,}",
  [509461] = "{id=509461,Voice='Npc_Quest/509461',Text='先遣队那些倒霉蛋正悄悄往里部署呢。等他们把命拼没了，信号一亮，您再穿着皮草华丽登场——到时候可别被自己的尾巴绊倒了哟，啾！',Speaker=814064,}",
  [509462] = "{id=509462,Voice='Npc_Quest/509462',Text='显然，语言的艺术对你来说过于深奥了。但这不重要，只要先遣军按照我的计划执行，我也能忍受这种刺耳的吹捧。能与我合作，这是白鹰族偿还那份陈年债务最体面的方式。',Speaker=814061,}",
  [509463] = "{id=509463,Voice='Npc_Quest/509463',Text='是是是，白鹰族当年乘东风来到这里，确实是卢甘族给了我们扎根的地方。总之，在先遣军信号出现前，您就在这儿安分地舔毛吧。啾！',Speaker=814064,}",
  [509464] = "{id=509464,Voice='Npc_Quest/509464',Text='冒险者，我们不能空等。还记得我提过的“视界”吗？那是蓉可儿的研究课题。她是巴格的研究助手，巴格就是通过它们在监视整个伊斯加尔特和吸收能量。',Speaker=814061,}",
  [509465] = "{id=509465,Voice='Npc_Quest/509465',Text='我再次赐予你抉择的权力。',Speaker=814061,}",
  [509466] = "{id=509466,Voice='Npc_Quest/509466',Text='继续在雪花之地磨练。搜集足够的素材，直到你的王冠进化为终极姿态——[c][ffff00]雪花之冠·永寂[-][/c]。',Speaker=814061,}",
  [509467] = "{id=509467,Voice='Npc_Quest/509467',Text='或者跟我去极光之地，拆掉蓉可儿在那布置的“视界之眼”，阻止巴格变强。当你完成这次挑战，我会再次授予你“特权”，它能让你的王冠展现出更契合这片土地的色彩。这不仅是荣誉，也是力量的共鸣。',Speaker=814061,}",
  [509468] = "{id=509468,Voice='Npc_Quest/509468',Text='（是去变强呢？还是去戳瞎巴格削弱他换不同颜色的王冠？本喵都听你的~喵~）',Speaker=814061,Option='{寻找材料磨砺王冠,0},{前往极光之地,0}',}",
  [509486] = "{id=509486,Voice='Npc_Quest/509486',Text='（上吧！别担心，如果你不小心滑出了轨道，记得在半空大声呼唤本喵的名字。本喵会捞你一把。喵~）',Speaker=814061,}",
  [509487] = "{id=509487,Voice='Npc_Quest/509487',Text='（一号线出发，目的地——极光之地！喵~）',Speaker=814061,}",
  [509488] = "{id=509488,Voice='Npc_Quest/509488',Text='（喵哈哈！这种风把胡须往后梳的感觉太棒了！）',Speaker=814061,}",
  [509489] = "{id=509489,Voice='Npc_Quest/509489',Text='（目的地到啦~接下来交给白发老头！喵~）',Speaker=814061,}",
  [509554] = "{id=509554,Text='抵挡',}",
  [509555] = "{id=509555,Text='共鸣',}",
  [509556] = "{id=509556,Voice='Npc_Quest/509556',Text='深寒的力量出现了，快与它共鸣！',Speaker=814062,}",
  [509588] = "{id=509588,Voice='Npc_Quest/509588',Text='那只笨猫……连告别都要绕这么大一圈。不过，作为我的载体，这份谢幕，还算合格。',Speaker=814102,Option='{白猫去哪儿了,0},{白猫换了你？,0}',}",
  [509589] = "{id=509589,Voice='Npc_Quest/509589',Text='在你离开后，它就钻进了我的身体里……用它那点可怜又固执的意志，稳住了我这副无心之躯。明明怕得要死，却还是选择了最麻烦的方式来陪我……真是个笨猫。',Speaker=814102,Option='{我会想它的,0},{笨猫……,0}',}",
  [509609] = "{id=509609,Voice='Npc_Quest/509609',Text='拉斯甘德，你现在一定很愤怒，因为是我让你变成了无心之躯，但愤怒会影响你的判断。这正是生物永远无法摆脱的瑕疵。',Speaker=814103,}",
  [509610] = "{id=509610,Voice='Npc_Quest/509610',Text='愤怒？巴格，你太高看你自己了。你玷污了我卢甘一族，玷污了我完美的心脏，更囚禁了我的朋友。现在，该物归原主了。',Speaker=814102,Option='{他没有心没有情绪,0},{还我赛尼亚！,0}',}",
  [509611] = "{id=509611,Voice='Npc_Quest/509611',Text='拉斯甘德，你仍然以为那只是一颗属于你的心脏。错误，这是我倾尽全部精力完成的最高实验成果。',Speaker=814103,}",
  [509612] = "{id=509612,Voice='Npc_Quest/509612',Text='伊米尔之心碎片让无数人觊觎，却也让他们最终因贪婪而被反噬。',Speaker=814103,Option='{你也会被反噬,0},{知道就好,0}',}",
  [509613] = "{id=509613,Voice='Npc_Quest/509613',Text='所以，真正的崇拜从不是占有，而是解析、复现，然后超越。',Speaker=814103,}",
  [509614] = "{id=509614,Voice='Npc_Quest/509614',Text='而用你的心脏炼成的仿伊米尔之心不同，它稳定、纯粹、拥有近乎完美的生命流转结构。',Speaker=814103,}",
  [509615] = "{id=509615,Voice='Npc_Quest/509615',Text='只要完成最后炼化，它将成为超越伊米尔之心碎片的存在——它可以让能量永续循环，可以让失败的样本重新进入下一次迭代。',Speaker=814103,}",
  [509616] = "{id=509616,Voice='Npc_Quest/509616',Text='从永寂到新生，不该是神话里的奇迹，而应该是可以被复现的实验结果。这，才是这颗心脏真正的意义。凡人只能仰望神明，而我，将亲手创造神明。',Speaker=814103,}",
  [509617] = "{id=509617,Voice='Npc_Quest/509617',Text='很好。听起来更值得拿回来了。',Speaker=814102,}",
  [509618] = "{id=509618,Voice='Npc_Quest/509618',Text='呵，想要夺走它，就解开这道防护壁，否则你没有资格成为我的对手。',Speaker=814103,}",
  [509619] = "{id=509619,Voice='Npc_Quest/509619',Text='你还是老样子，巴格。把简单的东西包得像天才造物。',Speaker=814102,}",
  [509620] = "{id=509620,Voice='Npc_Quest/509620',Text='冒险者，摧毁三台传输器就行~',Speaker=814102,}",
  [509625] = "{id=509625,Voice='Npc_Quest/509625',Text='继续正面对抗，只是在浪费时间。',Speaker=814102,}",
  [509626] = "{id=509626,Voice='Npc_Quest/509626',Text='我失去了心脏，力量无法完整流转。但我的心脏，仍会回应我。',Speaker=814102,}",
  [509627] = "{id=509627,Voice='Npc_Quest/509627',Text='我那颗无可挑剔的心脏已经不再适合回到我的身体里。',Speaker=814102,}",
  [509628] = "{id=509628,Voice='Npc_Quest/509628',Text='如果它注定要离开我，至少要离开得有价值。',Speaker=814102,}",
  [509629] = "{id=509629,Voice='Npc_Quest/509629',Text='协助我引导共振！让那颗心击穿巴格！',Speaker=814102,}",
  [509630] = "{id=509630,Voice='Npc_Quest/509630',Text='沉眠的心，永寂为证，回应——拉斯甘德！巴格，看来你所谓的超越，也只能停在半成品的形状里了。',Speaker=814102,}",
  [509631] = "{id=509631,Voice='Npc_Quest/509631',Text='呃……不对？！它在抗拒我……',Speaker=814102,}",
  [509632] = "{id=509632,Voice='Npc_Quest/509632',Text='炼化火种被剥离。样本暂停炼化进程。但变量并不代表实验失败。',Speaker=814103,}",
  [509633] = "{id=509633,Voice='Npc_Quest/509633',Text='仿伊米尔之心已经与我融为一体！拉斯甘德，你永远也别想夺回它了！',Speaker=814103,}",
  [509634] = "{id=509634,Voice='Npc_Quest/509634',Text='这个疯子，居然吞了半成品的仿伊米尔之心！',Speaker=814102,}",
  [509711] = "{id=509711,Voice='Npc_Quest/509711',Text='你们终于抵达终点了。很好，所有的不稳定干扰项，现在都已经主动进入了同一块实验场中，这也省去了我逐一清理数据的成本。',Speaker=814103,}",
  [509712] = "{id=509712,Voice='Npc_Quest/509712',Text='无论是卢甘族、多管闲事的冒险者，还是那些聒噪的白鹰护卫队……在绝对的数据面前，你们都只是无法改变最终结果的变量罢了。',Speaker=814103,}",
  [509713] = "{id=509713,Voice='Npc_Quest/509713',Text='收起你那令人作呕的傲慢，巴格。我不允许你在伊斯加尔特玷污我的卢甘族，我的土地。',Speaker=814102,}",
  [509714] = "{id=509714,Voice='Npc_Quest/509714',Text='拉斯甘德，你失去了心脏，却仍坚持以这具无心之躯站在这里，作为样本，你的执念值得记录。',Speaker=814103,}",
  [509715] = "{id=509715,Voice='Npc_Quest/509715',Text='作为叛徒，你的废话也一如既往地冗长。对了，我那无懈可击的心脏呢？',Speaker=814102,}",
  [509716] = "{id=509716,Voice='Npc_Quest/509716',Text='我说过，它早已不再属于你。它正在成为超越一切的仿伊米尔之心。而此刻，我正以自身为容器，收集它最后的核心数据。',Speaker=814103,}",
  [509717] = "{id=509717,Voice='Npc_Quest/509717',Text='用你那肮脏的身体继续炼化我的心脏，确实令人不悦。不过，这恰好也是我想看到的结果。',Speaker=814102,}",
  [509718] = "{id=509718,Voice='Npc_Quest/509718',Text='那就亲自感受这颗心脏的力量吧。第一层测试现在开始。让我看看，失去心脏的王者与这些杂乱的变量，究竟能撑过几轮数据迭代。',Speaker=814103,}",
  [509719] = "{id=509719,Voice='Npc_Quest/509719',Text='启动冰铸复制程序。样本一、样本二，开始清除眼前的干扰项，收集他们的数据。',Speaker=814103,}",
  [509720] = "{id=509720,Voice='Npc_Quest/509720',Text='样本损毁，但战斗数据回收完成。',Speaker=814103,}",
  [509721] = "{id=509721,Voice='Npc_Quest/509721',Text='接下来，我会亲自验证你们是否还有继续存在的价值。',Speaker=814103,}",
  [509722] = "{id=509722,Voice='Npc_Quest/509722',Text='别靠近。巴格吞噬了半成品仿伊米尔之心，绝不可能如此轻易结束。',Speaker=814102,}",
  [509723] = "{id=509723,Voice='Npc_Quest/509723',Text='失败不是污点，而是尚未处理的冗余记录。现在，我会把过去那个不完美的自己，也一并优化。',Speaker=814104,}",
  [509724] = "{id=509724,Voice='Npc_Quest/509724',Text='我不再只是实验者。我的血肉、神经、骨骼，都会成为仿伊米尔之心的炼化器。',Speaker=814104,}",
  [509725] = "{id=509725,Voice='Npc_Quest/509725',Text='果然是连试验搭子死了，都要做成仿真体的疯子。巴格，你才是真正的无心之躯。',Speaker=814102,}",
  [509726] = "{id=509726,Voice='Npc_Quest/509726',Text='蓉可儿？她已经进化成我数据库中一组完美的常量。而现在，仿伊米尔之心也将在我的体内完成最终循环。',Speaker=814104,}",
  [509727] = "{id=509727,Voice='Npc_Quest/509727',Text='所谓神明，不过是凡人无法复现的结果。现在，这个结果即将在我的身体中诞生。',Speaker=814104,}",
  [509728] = "{id=509728,Voice='Npc_Quest/509728',Text='我何曾没有祈求过神明？但耶梦加得什么也没有回应。伊斯加尔特等来的，只有漫长的风雪和退化的恐惧。',Speaker=814102,}",
  [509730] = "{id=509730,Voice='Npc_Quest/509730',Text='适配率继续上升，炼化仍在进行。',Speaker=814103,}",
  [509731] = "{id=509731,Voice='Npc_Quest/509731',Text='最终炼化完成，载体崩解。',Speaker=814103,}",
  [509734] = "{id=509734,Voice='Npc_Quest/509734',Text='去吧。你不再是我的心脏，而是属于伊斯加尔特的初雪——用你的力量，去净化这片土地。',Speaker=814102,}",
  [509735] = "{id=509735,Voice='Npc_Quest/509735',Text='本喵回来了~',Speaker=814109,}",
  [509736] = "{id=509736,Voice='Npc_Quest/509736',Text='从今日起，卢甘族不再等待神明、不再依赖实验。',Speaker=814102,}",
  [509737] = "{id=509737,Voice='Npc_Quest/509737',Text='心之所向，就是伊斯加尔特……不灭的意志。',Speaker=814102,}",
  [509738] = "{id=509738,Voice='Npc_Quest/509738',Text='看来，我来得正是时候。',Speaker=814108,Option='{你也可以不来的,0},{打架的时候人呢,0}',}",
  [509739] = "{id=509739,Voice='Npc_Quest/509739',Text='别急着抱怨。这点麻烦有你在这里就够了。',Speaker=814108,}",
  [509740] = "{id=509740,Voice='Npc_Quest/509740',Text='还记得吗，最初指引你踏入伊斯加尔特，只是为了寻找那道疑似伊米尔之心的信号。',Speaker=814108,}",
  [509741] = "{id=509741,Voice='Npc_Quest/509741',Text='现在，答案已经在这场初雪里了。他那颗仿伊米尔之心没有成为新的灾厄，而是被拉斯甘德献给了伊斯加尔特，阻止了卢甘族陷入退化的命运。',Speaker=814108,}",
  [509742] = "{id=509742,Voice='Npc_Quest/509742',Text='拉斯甘德选择放开自己的心，赛尼亚始终守住自己的心。他们因此为伊斯加尔特的命运开辟了另一条路。而伊斯加尔特，也回应了他们——',Speaker=814108,}",
  [509743] = "{id=509743,Voice='Npc_Quest/509743',Text='所以拉斯甘德才能以无心之躯，开启属于他，也属于这片土地的新篇章。',Speaker=814108,}",
  [509744] = "{id=509744,Voice='Npc_Quest/509744',Text='但真正的故事，往往是在既定结局之后才开始。',Speaker=814108,}",
  [509745] = "{id=509745,Voice='Npc_Quest/509745',Text='当命运之风再次吹起时，想见的人，终究会如约出现。',Speaker=814108,}",
  [509746] = "{id=509746,Voice='Npc_Quest/509746',Text='冒险者……',Speaker=814106,}",
  [509747] = "{id=509747,Voice='Npc_Quest/509747',Text='冒险者，属于我们的冒险，才真正开始。',Speaker=814106,}",
  [509748] = "{id=509748,Text='白猫·拉斯甘德在冰封鳞桥等待冒险者，白鹰先遣军已潜入冰封城堡，只待内外合击。然而，拉斯甘德的意识迟迟没有出现。桥边散落的炼化试验记录、沾满蓝金色血迹的长袍，以及嗜血而生的寒冰草，共同指向一个残酷事实——拉斯甘德本体已被巴格剥离心源，仿伊米尔之心的炼化进入最后阶段。\n循着血迹与气息，冒险者抵达冰封鳞片。在凌乱的实验器皿深处，拉斯甘德的身躯被禁锢于寒冰草中，力量不断从胸口的空洞中流失。白猫明白本体即将崩解，故作轻松地让冒险者前往永寂树下收集雪花，以自己为原型堆一座白猫雪雕作为告别。实际上，在冒险者离开后，它已回到拉斯甘德的身体里，用自身承载的意志稳住这具无心之躯。\n冒险者带回永寂雪花后，拉斯甘德苏醒，并在白猫雪雕完成时见证雪花之冠·永寂显现。永寂并非终结，而是在一切声音都消失之后，依然选择向前。白猫用自己的方式，将最后的权柄交到冒险者手中。戴上永寂王冠后，冒险者击退被污染的卢甘族，与拉斯甘德一同前往冰封城堡，夺回心脏、救出赛尼亚。\n冰封城堡中，拉斯甘德的心脏已被炼成仿伊米尔之心的雏形，赛尼亚则被禁锢在提取器中，力量化作紫色炼化之火，持续灼烧着心脏。巴格宣称自己并非单纯夺取心脏，而是在解析、复现并超越伊米尔之心。拉斯甘德看穿防护壁的传输规律，指引冒险者破解屏障。正面对抗中，失去心脏的拉斯甘德无法压制巴格，于是引导心源共振，让那颗仍记得自己的心脏回应呼唤，击穿巴格，也震散了赛尼亚身上的炼化束缚。\n赛尼亚苏醒后，因拉斯甘德没能夺回心脏而痛惜。拉斯甘德却判断，巴格带走半成品仿伊米尔之心后，必定还会继续疯狂炼化；若炼化真能完成，或许反而会成为终局的破口。于是，他让冒险者释放信号，召来气阳阳，并命白鹰护卫队追踪巴格的行踪、护送虚弱的赛尼亚前往安全之处。\n在最终情报传回前，拉斯甘德带领冒险者前往三处纯净之地，寻找稳定无心之躯的方法。祈愿雪花降下祝福，让他在剧痛中保持清醒；冰封花园凝出雪之心，暂时维持生命流动；他们又从冰雪乐园取回拉斯甘德幼年时留下的蛇蜕，使他重新想起自己最初为何想要守护这片土地。心从来不只是一块跳动的肉，童真、信念与守护之愿，同样能让无心之躯继续前行。\n气阳阳带回情报后，冒险者与拉斯甘德踏入冰封之心。巴格先以冰铸样本测试众人，随后亲自出手，最终借半成品仿伊米尔之心化作巨大的异化巴格，宣称要以自身为炼化器，让凡人仰望的神明之力在体内完成循环。终战中，异化巴格完成最终炼化，却也在冒险者与拉斯甘德的合力攻击下湮灭。炼成的仿伊米尔之心悬浮于空中，拉斯甘德没有让它回到自己的胸口，而是让它化作属于伊斯加尔特的初雪。\n仿伊米尔之心化作漫天雪花落向大地，净化了被污染的卢甘族，终止了这场噩梦，也让白猫从冰封鳞片的雪中重新归来。原本，当心脏归于天地，拉斯甘德这具无心之躯也应随之消散；但伊斯加尔特回应了那个愿意将一切归还给土地的人。大地涌出的金光笼罩拉斯甘德，他以无心之躯继续站在初雪之中，开启属于自己、卢甘族与伊斯加尔特的新篇章。\n奥斯卡降临，确认命运之书中疑问最多的那一页终于有了答案。当命运之风再次吹起，初雪中传来熟悉的声音：“我们说好要一起走遍世界的每一个角落……你还记得吗？”',}",
  [509750] = "{id=509750,Voice='Npc_Quest/509750',Text='凡人的极限到了……那么，真正的神性……降临吧！',Speaker=814103,}",
  [632769] = "{id=632769,Voice='Npc_Quest/632769',Text='达纳托斯，你再坚持一下！我一定会救你的！',Speaker=826576,}",
  [632770] = "{id=632770,Voice='Npc_Quest/632770',Text='看，要小心避开这些冥狱犬，它们都是加尔姆的分身。',Speaker=826576,}",
  [632771] = "{id=632771,Voice='Npc_Quest/632771',Text='它们的鼻子灵的很，靠近的话变身法术就会被发现。',Speaker=826576,}",
  [632772] = "{id=632772,Voice='Npc_Quest/632772',Text='哎呀！被发现了！这次可要多加小心！',Speaker=826576,}",
  [632773] = "{id=632773,Voice='Npc_Quest/632773',Text='这样下去可不行，更何况吾等是来寻求帮助的，不能结仇。',Speaker=826576,}",
  [632774] = "{id=632774,Voice='Npc_Quest/632774',Text='还记得赫尔饼吗？快用它把加尔姆引开！这里交给吾！',Speaker=826576,}",
  [632775] = "{id=632775,Voice='Npc_Quest/632775',Text='加尔姆这条蠢狗，连门都看不好，成天只知道吃。',Speaker=826599,}",
  [632776] = "{id=632776,Voice='Npc_Quest/632776',Text='你们几个，既然都到这了，那就进来吧。',Speaker=826599,}",
  [632777] = "{id=632777,Voice='Npc_Quest/632777',Text='我说过，除了哥哥和送南瓜的，谁都不可以进入宫殿里。',Speaker=826599,}",
  [632778] = "{id=632778,Voice='Npc_Quest/632778',Text='在尼夫海姆破坏我制定的规则——你们胆子真大。',Speaker=826599,}",
  [632779] = "{id=632779,Voice='Npc_Quest/632779',Text='是你？可你的气息……呵，华莱士那家伙给的死灵之酒吧。',Speaker=826599,Option='{好久不见 ,0},{是我是我,0}',}",
  [632780] = "{id=632780,Voice='Npc_Quest/632780',Text='你旁边带的这个东西有点意思，在生死边缘的游魂，但既不属于生也不属于死。',Speaker=826599,}",
  [632781] = "{id=632781,Voice='Npc_Quest/632781',Text='海拉殿下……吾等冒昧闯入非常抱歉，但是……只有殿下最了解灵魂了……',Speaker=826576,}",
  [632782] = "{id=632782,Voice='Npc_Quest/632782',Text='他这样的状态已经坚持不了多久了！请殿下救治他！',Speaker=826576,}",
  [632783] = "{id=632783,Voice='Npc_Quest/632783',Text='好啊，很久没有见到这么有趣的灵魂了，让他留下来做我的玩具。',Speaker=826599,}",
  [632784] = "{id=632784,Voice='Npc_Quest/632784',Text='……玩具……这怎么能！不可以！',Speaker=826576,}",
  [632785] = "{id=632785,Voice='Npc_Quest/632785',Text='我说，你们潜入我的宫殿，欺负我的蠢狗，破坏我的规则……',Speaker=826599,}",
  [632786] = "{id=632786,Voice='Npc_Quest/632786',Text='现在还要我不计代价的帮助你们？',Speaker=826599,}",
  [632787] = "{id=632787,Voice='Npc_Quest/632787',Text='你们给我好好看看，谁才是尼夫海姆的主人！',Speaker=826599,}",
  [632788] = "{id=632788,Voice='Npc_Quest/632788',Text='吾会保护好达纳托斯！吾也会帮助你的！',Speaker=826576,}",
  [632789] = "{id=632789,Voice='Npc_Quest/632789',Text='啧，浓郁的、令人作呕的生机……',Speaker=826599,}",
  [632790] = "{id=632790,Voice='Npc_Quest/632790',Text='你是龙族首领……黑龙尼德霍格！',Speaker=826599,}",
  [632791] = "{id=632791,Voice='Npc_Quest/632791',Text='传说中的黑龙，力量不过如此！',Speaker=826599,}",
  [632792] = "{id=632792,Voice='Npc_Quest/632792',Text='嘁，不过是个破败到快要消亡的游魂，能有什么用！',Speaker=826599,}",
  [632793] = "{id=632793,Voice='Npc_Quest/632793',Text='达纳托斯，快躲开！你承受不了她的力量！',Speaker=826576,}",
  [632794] = "{id=632794,Voice='Npc_Quest/632794',Text='你……帮过……不要……我……欠你！',Speaker=826575,}",
  [632795] = "{id=632795,Voice='Npc_Quest/632795',Text='无谓的挣扎！',Speaker=826599,}",
  [632796] = "{id=632796,Voice='Npc_Quest/632796',Text='嗯？这气息……',Speaker=826599,}",
  [632797] = "{id=632797,Voice='Npc_Quest/632797',Text='你的身上有那家伙的记忆……',Speaker=826599,}",
  [632798] = "{id=632798,Voice='Npc_Quest/632798',Text='……站那么远做什么？我又不会吃了你。',Speaker=826599,Option='{我怕你惩罚我 ,0},{你刚才超凶,0}',}",
  [632799] = "{id=632799,Voice='Npc_Quest/632799',Text='哼，那是你们扰乱冥界秩序在先，不给点教训，如何捍卫死亡的威严？',Speaker=826599,}",
  [632800] = "{id=632800,Voice='Npc_Quest/632800',Text='更何况，人家已经两天没有吃到好吃的南瓜派了……',Speaker=826599,}",
  [632801] = "{id=632801,Voice='Npc_Quest/632801',Text='是约姆家的南瓜！不！比约姆家的南瓜更香甜！',Speaker=826599,}",
  [632802] = "{id=632802,Voice='Npc_Quest/632802',Text='好吧……看在南瓜的份上……就赦免你们一次。',Speaker=826599,}",
  [632803] = "{id=632803,Voice='Npc_Quest/632803',Text='抱歉，吾等并不想和你敌对……只是，吾有些心急……',Speaker=826576,}",
  [632804] = "{id=632804,Voice='Npc_Quest/632804',Text='……你们是想要修复他的灵魂？带上他，跟我来。',Speaker=826599,}",
  [632805] = "{id=632805,Voice='Npc_Quest/632805',Text='别磨磨蹭蹭，他的身体可撑不了多久。',Speaker=826599,}",
  [632806] = "{id=632806,Voice='Npc_Quest/632806',Text='在这个家伙的记忆碎片里，我看到了他……',Speaker=826599,}",
  [632807] = "{id=632807,Voice='Npc_Quest/632807',Text='我早就感知到他的离去，灵魂也不会来这里……',Speaker=826599,}",
  [632808] = "{id=632808,Voice='Npc_Quest/632808',Text='一个个的，都和哥哥们一样离开我……',Speaker=826599,}",
  [632809] = "{id=632809,Voice='Npc_Quest/632809',Text='塞壬……我们说好的，我们是朋友啊……',Speaker=826599,}",
  [632810] = "{id=632810,Voice='Npc_Quest/632810',Text='这个偏殿里存放了一些凝魂液，去把它们找出来。',Speaker=826599,}",
  [632811] = "{id=632811,Voice='Npc_Quest/632811',Text='你们都后退一些，我要帮他修补灵魂。',Speaker=826599,}",
  [632812] = "{id=632812,Voice='Npc_Quest/632812',Text='……冒险者，还有……尼德霍格？我们这是在……尼夫海姆？',Speaker=826600,}",
  [632813] = "{id=632813,Voice='Npc_Quest/632813',Text='达、达纳托斯，你，你清醒过来了？！',Speaker=826576,}",
  [632814] = "{id=632814,Voice='Npc_Quest/632814',Text='别高兴得太早，我其实并没有彻底修复他的灵魂。',Speaker=826599,}",
  [632815] = "{id=632815,Voice='Npc_Quest/632815',Text='这家伙的灵魂破损得太严重，我只能梳理混乱的碎片，却无法补全缺失的部分。',Speaker=826599,}",
  [632816] = "{id=632816,Voice='Npc_Quest/632816',Text='……喂，我说，你是叫达纳托斯对吧？你的记忆，还剩下多少？',Speaker=826599,}",
  [632817] = "{id=632817,Voice='Npc_Quest/632817',Text='……我不知道。我只记得一个叫希尔斯的人。',Speaker=826600,}",
  [632818] = "{id=632818,Voice='Npc_Quest/632818',Text='[c][ffff00]我想再见到她[-][/c]，无论付出什么代价。但我不知道她在哪里，甚至想不起她的面容。',Speaker=826600,}",
  [632819] = "{id=632819,Voice='Npc_Quest/632819',Text='看到了吗？他是个没有记忆的灵魂，而记忆恰恰是构成灵魂的关键。',Speaker=826599,}",
  [632820] = "{id=632820,Voice='Npc_Quest/632820',Text='没有记忆，他迟早会在时光中迷失自我，再度变成游魂。',Speaker=826599,}",
  [632821] = "{id=632821,Voice='Npc_Quest/632821',Text='而游魂只能存活在梦境中，是无法在世间存活也无法转世。',Speaker=826599,}",
  [632822] = "{id=632822,Voice='Npc_Quest/632822',Text='怎么会这样……那，该如何找回他的记忆？',Speaker=826576,}",
  [632823] = "{id=632823,Voice='Npc_Quest/632823',Text='谁知道呢？我能做到的事情，已经全做完了。不过……',Speaker=826599,}",
  [632824] = "{id=632824,Voice='Npc_Quest/632824',Text='如果他和[c][ffff00]塞壬那家伙一样[-][/c]，作为一个英雄，那里或许能找回他的记忆。',Speaker=826599,Option='{原来是那里！ ,0},{到底是哪里？,0}',}",
  [632825] = "{id=632825,Voice='Npc_Quest/632825',Text='英雄……你是说——[c][ffff00]伊米尔之书[-][/c]？',Speaker=826576,}",
  [632826] = "{id=632826,Voice='Npc_Quest/632826',Text='我可什么都没说。现在，离开我的宫殿，我受够你身上恶心人的生命气息了！',Speaker=826599,}",
  [632827] = "{id=632827,Voice='Npc_Quest/632827',Text='谢谢，海拉殿下，吾代表龙族，永远铭记你救治吾之血亲的情谊！',Speaker=826576,}",
  [632828] = "{id=632828,Voice='Npc_Quest/632828',Text='[c][ffff00]血亲[-][/c]……？这……算了，关我什么事，你们赶紧离开！',Speaker=826599,}",
  [632829] = "{id=632829,Voice='Npc_Quest/632829',Text='抓紧吾的手，吾送你等回赫瓦格密尔。',Speaker=826576,}",
  [632840] = "{id=632840,Voice='Npc_Quest/632840',Text='什么啊……我都说了多少遍了，我不是她的妹妹啊！',Speaker=826575,Option='{前世的事情,0},{也说不定呢,0}',}",
  [632841] = "{id=632841,Voice='Npc_Quest/632841',Text='啧，怎么连你也这么认为。不过算了，如果能让她安心的话，我不介意暂时扮演这个角色。',Speaker=826575,}",
  [632842] = "{id=632842,Voice='Npc_Quest/632842',Text='毕竟这家伙帮了我很多，如果没有她的话，我应该还在梦境中无意识地徘徊',Speaker=826575,}",
  [632843] = "{id=632843,Voice='Npc_Quest/632843',Text='我也不会想起对我如此重要的希尔斯，更没有机会实现回去见她的诺言。',Speaker=826575,}",
  [632844] = "{id=632844,Voice='Npc_Quest/632844',Text='你也去休息吧，放心，这家伙我会照看。',Speaker=826575,}",
  [632845] = "{id=632845,Voice='Npc_Quest/632845',Text='之前的那段时间，她一直守着我。现在，也该轮到我来守护她了。',Speaker=826575,}",
  [632850] = "{id=632850,Text='长按线索查看详细信息',}",
  [632851] = "{id=632851,Text='选择需要提交的线索',}",
  [632852] = "{id=632852,Text='将水带给尼德霍格',}",
  [632855] = "{id=632855,Voice='Npc/Nidhogg_sigh_02',Text='挚友……吾真的找不到永恒之花了吗？想到维德伤心的样子，吾也很难过。',Speaker=826849,Option='{别放弃,0},{别难过,0}',}",
  [632856] = "{id=632856,Voice='Npc/Nidhogg_agree_01',Text='嗯，吾会继续寻找的。你有什么新的线索吗？',Speaker=826849,Option='{大祭司邀请我们,0},{前往艾卡拉奇,0}',}",
  [632857] = "{id=632857,Voice='Npc/Nidhogg_doubt_01',Text='浮空精灵的大祭司怎么会邀请吾等？晨曦祭典又和吾等有何关系？',Speaker=826849,}",
  [632858] = "{id=632858,Text='无论如何，他诚心邀请吾，吾不妨走一趟。挚友，你准备好了吗？',Speaker=826849,Option='{立刻出发,7},{再等一下,6}',}",
  [632893] = "{id=632893,Voice='Npc/Nidhogg_agree_01',Text='这里土壤丰沃，魔力充沛，是个适合种植花朵的地方。',Speaker=826849,}",
  [632894] = "{id=632894,Text='我为你们准备了花的种子，还有种植花朵所需要的素材。挑选你们心中的永恒之花吧。',Speaker=826843,}",
  [632895] = "{id=632895,Text='我还有些事要处理，就先告辞了。',Speaker=826843,}",
  [632896] = "{id=632896,Text='对了，仪式的那天，你们可以直接前往[c][ffff00]蔚云之海[-][/c]。',Speaker=826843,}",
  [632897] = "{id=632897,Text='挚友，吾等来玩个小游戏可好？吾等分开选择种子，然后互相猜一下对方的选择。',Speaker=826849,}",
  [632898] = "{id=632898,Voice='Npc/Nidhogg_laugh_01',Text='猜错的人~！哼哼~就惩罚变成小龙崽吧！',Speaker=826849,}",
  [632903] = "{id=632903,Text='挚友~你看起来已经做出了选择。',Speaker=826849,}",
  [632904] = "{id=632904,Voice='Npc/Nidhogg_laugh_01',Text='快猜猜吾选择了哪一个？~',Speaker=826849,Option='{百合,3},{星空之眼,2},{苍夜花,2},{奥斯塔拉花,2}',}",
  [632905] = "{id=632905,Voice='Npc/Nidhogg_sing_01',Text='哼哼哼~猜错啦！~吾选择的可是百合哦！',Speaker=826849,}",
  [632906] = "{id=632906,Voice='Npc/Nidhogg_laugh_01',Text='嘿嘿~接受惩罚吧！挚友！',Speaker=826849,}",
  [632907] = "{id=632907,Text='真可爱！现在你也成了吾的族人了~吾会保护好你的！',Speaker=826849,}",
  [632908] = "{id=632908,Voice='Npc/Nidhogg_agree_01',Text='唔——不愧是吾的挚友，一下子就知道吾的选择。',Speaker=826849,}",
  [632909] = "{id=632909,Text='当时吾一心想培育出永恒之花，百合也是其中的未成品之一。',Speaker=826849,}",
  [632910] = "{id=632910,Text='没想到，百合虽不是吾所追寻的永恒之花，但却在艾卡拉奇这个地方扎根。',Speaker=826849,}",
  [632911] = "{id=632911,Text='现在这样的形式冠以了永恒之花的称号，吾想吾当时培育它时所倾注的情感也得到了回应吧。',Speaker=826849,}",
  [632912] = "{id=632912,Text='现在，让吾来猜猜挚友的选择吧~吾认为是苍夜花！快说说~你的选择是什么~',Speaker=826849,Option='{百合,5},{星空之眼,5},{苍夜花,6},{奥斯塔拉花,5}',}",
  [632913] = "{id=632913,Voice='Npc/Nidhogg_laugh_01',Text='哼哼~吾猜对了呢！~吾多了解挚友啊！',Speaker=826849,}",
  [632914] = "{id=632914,Text='苍夜花给吾的感觉和挚友很像呢，在岩石中破土而出，坚毅而又勇敢。',Speaker=826849,}",
  [632915] = "{id=632915,Voice='Npc/Nidhogg_sing_01',Text='嘿嘿~挚友，你输了~放心吧！你就保持现在这样，种花的事有吾在！别担心！',Speaker=826849,}",
  [632916] = "{id=632916,Text='吾等没有受到惩罚。虽然有些遗憾，看不到你变成小龙崽的样子，但这证明了吾等对彼此的了解！',Speaker=826849,}",
  [632917] = "{id=632917,Voice='Npc/Nidhogg_sigh_02',Text='诶~！吾……吾居然猜错了……',Speaker=826849,Option='{惩罚惩罚！,0},{变身变身！,0}',}",
  [632918] = "{id=632918,Voice='Npc/Nidhogg_think_02',Text='唔……吾……好吧……变就变！吾很久没有以龙的形态现身了。',Speaker=826849,}",
  [632919] = "{id=632919,Voice='Npc/Nidhogg_angry_02',Text='哼！明明苍夜花给吾的感觉和挚友很像呢，在岩石中破土而出，坚毅而又勇敢。',Speaker=826848,}",
  [632920] = "{id=632920,Voice='Npc/Nidhogg_angry_01',Text='你怎么会没选这个呢？',Speaker=826848,}",
  [632921] = "{id=632921,Voice='Npc/Nidhogg_laugh_01',Text='这下好了！吾等都变成了四肢短小的小龙崽。不过，倒是有趣。',Speaker=826848,}",
  [632922] = "{id=632922,Voice='Npc/Nidhogg_angry_01',Text='啊啊啊！！居然只有吾接受了惩罚！哼！四肢短小的小龙崽一点都不威风！',Speaker=826848,}",
  [632923] = "{id=632923,Voice='Npc/Nidhogg_agree_01',Text='种子选好了，吾等就将它们埋进土里吧！',Speaker=826849,}",
  [632924] = "{id=632924,Voice='Npc/Nidhogg_laugh_01',Text='记住哦！先用铲子将土壤松开，将种子埋下，然后再浇水！',Speaker=826849,}",
  [632925] = "{id=632925,Voice='Npc/Nidhogg_scared_01',Text='啊！不要让这些害虫靠近花朵！',Speaker=826849,}",
  [632926] = "{id=632926,Voice='Npc/Nidhogg_sigh_01',Text='呼~总算把它们都消灭完了~接下来~就让时间带给它们成长吧。',Speaker=826849,}",
  [632927] = "{id=632927,Voice='Npc/Nidhogg_laugh_01',Text='吾也有些累了……下次再见了，挚友。',Speaker=826849,}",
  [632928] = "{id=632928,Text='挚友，是晨曦祭典的时间到了吗？',Speaker=826849,}",
  [632929] = "{id=632929,Voice='Npc/Nidhogg_think_01',Text='吾有些期待，毕竟……这是第一次有吾族之外的人邀请吾参加如此重要的仪式。',Speaker=826849,}",
  [632930] = "{id=632930,Voice='Npc/Nidhogg_think_02',Text='吾种下的花也不知道如何了……是否顺利的绽放了……',Speaker=826849,Option='{一起去看看,0},{一定很顺利,0}',}",
  [632931] = "{id=632931,Voice='Npc/Nidhogg_agree_01',Text='你说的对，那么吾等现在就出发前往蔚云之海吗？',Speaker=826849,Option='{现在出发！,4},{再等一下！,3}',}",
  [632942] = "{id=632942,Text='尼德霍格大人，冒险者，又见面了。',Speaker=826843,}",
  [632943] = "{id=632943,Text='仪式马上就要开始，一会尼德霍格大人手捧永恒之花到祭坛的水晶前即可。',Speaker=826843,}",
  [632944] = "{id=632944,Voice='Npc/Nidhogg_agree_01',Text='吾记住了。',Speaker=826849,}",
  [632945] = "{id=632945,Text='冒险者，你的永恒之花在仪式后，我会带你去它[c][ffff00]该去的地方[-][/c]。',Speaker=826843,Option='好的',}",
  [632946] = "{id=632946,Text='这是二位亲手种植的永恒之花，请收好。',Speaker=826843,}",
  [632947] = "{id=632947,Text='那么，尼德霍格大人，拜托了。',Speaker=826843,}",
  [632948] = "{id=632948,Text='永恒之花，纯洁的永恒之花，',Speaker=826843,}",
  [632949] = "{id=632949,Text='晨曦的气息滋养着你，辉煌地绽放。',Speaker=826843,}",
  [632950] = "{id=632950,Text='你从古老的土壤中而来，去到崭新纪年，在伊始之地开花。',Speaker=826843,}",
  [632951] = "{id=632951,Text='奥丝塔拉，请收下永恒之花……',Speaker=826849,}",
  [632952] = "{id=632952,Text='愿辉煌领域的土地永恒辉煌，愿浮空精灵的意志永恒不灭。',Speaker=826843,}",
  [632959] = "{id=632959,Text='这里才是晨曦祭典真正的主场，花开伊始之地。',Speaker=826843,}",
  [632960] = "{id=632960,Voice='Npc/Nidhogg_agree_01',Text='花开伊始之地……这个名字很美。',Speaker=826849,}",
  [632961] = "{id=632961,Text='毕竟，有一种说法是，天地树世界的所有的花都起源于此。虽然，事实并不是。',Speaker=826843,}",
  [632962] = "{id=632962,Text='但这个名字蕴含着浮空精灵们对这片土地的愿望，一切美好开始的地方。',Speaker=826843,}",
  [632963] = "{id=632963,Text='真要说起来，所有花的起源或许是黑龙大人您的花园哦！',Speaker=826843,}",
  [632964] = "{id=632964,Voice='Npc/Nidhogg_laugh_01',Text='吾当时也并没有想这么多，种花只是吾打发时间的一种方式。',Speaker=826849,}",
  [632965] = "{id=632965,Text='嗯~不过，这种说法还是说对了一半的。',Speaker=826843,}",
  [632966] = "{id=632966,Text='在微风吹来的种子开出了花朵后，在千万年的时间里，在这片土地上孕育出了更多的花种。',Speaker=826843,}",
  [632967] = "{id=632967,Text='现在天地树世界的很多花种，确实源于这里。',Speaker=826843,}",
  [632968] = "{id=632968,Voice='Npc/Nidhogg_agree_01',Text='嗯，确实，这里的很多花吾也从未见过。',Speaker=826849,}",
  [632969] = "{id=632969,Text='老师总说没有任何生命会是永恒的，但是我认为，[c][ffff00]生命会以自己的方式永恒[-][/c]。',Speaker=826843,}",
  [632970] = "{id=632970,Text='比如，您花园里的那颗种子，至今都与眼前的这片花海共存着。',Speaker=826843,}",
  [632971] = "{id=632971,Text='看到这片花海，我们就会想到那颗种子，没有那颗种子，就没有现在世界上多种多样的美丽的花。',Speaker=826843,}",
  [632972] = "{id=632972,Text='……',Speaker=826849,}",
  [632973] = "{id=632973,Text='晨曦祭典中，浮空精灵们会将自己选择的永恒之花移植到这里，',Speaker=826843,}",
  [632974] = "{id=632974,Text='他们也是希望自己的情感与愿望可以和这片花海一起永存吧。',Speaker=826843,}",
  [632975] = "{id=632975,Text='好啦，虽然很不情愿，但我还有些收尾工作要做，你们继续享受晨曦祭典吧。',Speaker=826843,Option='{好的,0},{再见,0}',}",
  [632976] = "{id=632976,Voice='Npc/Nidhogg_laugh_01',Text='挚友，我们四处逛逛吧。',Speaker=826849,}",
  [632977] = "{id=632977,Text='这里的花海生命力是如此的旺盛……',Speaker=826849,}",
  [632978] = "{id=632978,Text='谁也不会想到，在当年那片满是杂草的土地上……',Speaker=826849,}",
  [632979] = "{id=632979,Voice='Npc/Nidhogg_think_01',Text='竟能开出这样一片无边无际的花海。',Speaker=826849,}",
  [632980] = "{id=632980,Voice='Npc/Nidhogg_doubt_01',Text='……那边的精灵好像之前见过，和她们说说话吧。',Speaker=826849,}",
  [632981] = "{id=632981,Text='异乡人，是你们呀！看，这是我种下的星空之眼！',Speaker=826864,}",
  [632982] = "{id=632982,Text='它虽然会凋谢，但会有更多的星空之眼在这片土地上生长而出，直到如星辰一般，遍布这片土地。',Speaker=826864,}",
  [632983] = "{id=632983,Text='嗯？你们也来参加晨曦祭典了呀？多亏当时你们的帮忙，我总算在这里种下了苍夜花。',Speaker=826865,}",
  [632984] = "{id=632984,Text='希望苍夜花能在这片土地上永远绽放，这样苍夜公主的意志就不会遗失在时间长河之中。',Speaker=826865,}",
  [632985] = "{id=632985,Text='哦？是你们。来看看这朵奥斯塔拉花，它盛开的是不是很灿烂？',Speaker=826866,}",
  [632986] = "{id=632986,Text='希望它能和晨曦之光一样，能永远庇佑着艾卡拉奇。',Speaker=826866,}",
  [632987] = "{id=632987,Text='或许，吾已经不需要再寻找永恒之花了。',Speaker=826849,Option='{为什么？,0},{……嗯。,0}',}",
  [632988] = "{id=632988,Voice='Npc/Nidhogg_think_01',Text='吾眼前的这片花海，应该就是吾一直在寻找的东西了。',Speaker=826849,}",
  [632989] = "{id=632989,Text='没有生命是永恒的，所以生命之力再旺盛的花朵，也会凋谢。',Speaker=826849,}",
  [632990] = "{id=632990,Text='但是凋谢了，会有更多的花朵盛开，这是[c][ffff00]生命的法则[-][/c]。',Speaker=826849,}",
  [632991] = "{id=632991,Text='生命之力与凋谢之力总是相辅相成的，就如同吾和维德一般。',Speaker=826849,}",
  [632992] = "{id=632992,Text='梦罗克那个混蛋虽然诱骗吾触摸了本源之石，但也正因如此分裂出了维德来到了吾的身边。',Speaker=826849,}",
  [632993] = "{id=632993,Voice='Npc/Nidhogg_sigh_01',Text='所有人都畏惧着维德，但是[c][ffff00]没有凋零之力，又哪里来的生命之力[-][/c]。',Speaker=826849,}",
  [632994] = "{id=632994,Text='挚友，吾有一个请求。吾的花园，早就在战火中毁于一旦。',Speaker=826849,}",
  [632995] = "{id=632995,Text='能否将你的永恒之花，带到生命之泉，种植在吾的身边？吾是指真正的吾……',Speaker=826849,Option='{当然可以,0},{非常乐意,0}',}",
  [632996] = "{id=632996,Voice='Npc/Nidhogg_laugh_01',Text='谢谢你，吾的挚友。下一次，下一次若是吾能再见到维德……',Speaker=826849,}",
  [632997] = "{id=632997,Text='希望你的这朵生命之花会变成一大片花海，而吾会带着维德去到这片花海中。',Speaker=826849,}",
  [632998] = "{id=632998,Text='告诉她，不要害怕，一朵花会凋谢，但是正是因为它的凋谢，成就了这一片[c][ffff00]永恒的花海[-][/c]。',Speaker=826849,}",
  [632999] = "{id=632999,Text='而，吾会一直，在她的身边……',Speaker=826849,}",
  [633017] = "{id=633017,Text='有一个东西可以让尼德霍格的气息变得和死灵一样，这个东西是……',}",
  [633019] = "{id=633019,Text='花朵摇曳，时间会证明永恒的意义。',}",
  [633020] = "{id=633020,Text='奥斯塔拉……',}",
  [633028] = "{id=633028,Text='确定选择百合的种子吗？',Speaker=826844,Option='{确定,3},{再考虑一下,2}',}",
  [633029] = "{id=633029,Text='确定选择星空之眼的种子吗？',Speaker=826845,Option='{确定,3},{再考虑一下,2}',}",
  [633030] = "{id=633030,Text='确定选择苍夜花的种子吗？',Speaker=826846,Option='{确定,3},{再考虑一下,2}',}",
  [633031] = "{id=633031,Text='确定选择奥斯塔拉花的种子吗？',Speaker=826847,Option='{确定,3},{再考虑一下,2}',}",
  [633032] = "{id=633032,Text='现在，让吾来猜猜挚友的选择吧~吾认为是苍夜花！快说说~你的选择是什么~',Speaker=826849,Option='百合',}",
  [633033] = "{id=633033,Text='现在，让吾来猜猜挚友的选择吧~吾认为是苍夜花！快说说~你的选择是什么~',Speaker=826849,Option='星空之眼',}",
  [633034] = "{id=633034,Text='现在，让吾来猜猜挚友的选择吧~吾认为是苍夜花！快说说~你的选择是什么~',Speaker=826849,Option='苍夜花',}",
  [633035] = "{id=633035,Text='现在，让吾来猜猜挚友的选择吧~吾认为是苍夜花！快说说~你的选择是什么~',Speaker=826849,Option='奥斯塔拉花',}",
  [633036] = "{id=633036,Voice='Npc/Nidhogg_agree_01',Text='种子选好了，吾等就将它们埋进土里吧！',Speaker=826848,}",
  [633037] = "{id=633037,Voice='Npc/Nidhogg_laugh_01',Text='记住哦！先用铲子将土壤松开，将种子埋下，然后再浇水！',Speaker=826848,}",
  [633038] = "{id=633038,Voice='Npc/Nidhogg_sigh_02',Text='呼~总算把它们都消灭完了~接下来~就让时间带给它们成长吧。',Speaker=826848,}",
  [633039] = "{id=633039,Voice='Npc/Nidhogg_laugh_01',Text='吾也有些累了……下次再见了，挚友。',Speaker=826848,}",
  [633040] = "{id=633040,Text='啊……是你啊……',Speaker=827129,}",
  [633041] = "{id=633041,Text='啊，我怎么会在这里？我记得……我应该在去超市特卖的路上。',Speaker=827129,Option='说明情况',}",
  [633042] = "{id=633042,Text='啊……所以说，现在的我不是我，是个投影……好奇怪的感觉。',Speaker=827129,Option='关注点是这个吗！',}",
  [633043] = "{id=633043,Text='你们的世界里也会有怪人吗。我想和强的对手进行一场激动人心的战斗…',Speaker=827129,}",
  [633044] = "{id=633044,Text='嗯……所以你是来实现我的愿望的吧……那……给我100000000W！',Speaker=827129,Option='{严肃点！,0},{做不到！,0}',}",
  [633045] = "{id=633045,Text='我想进行一场激动人心的战斗。',Speaker=827129,}",
  [633046] = "{id=633046,Text='你们这的魔法挺有意思的，或许在这能让我找回当初做英雄的感觉。',Speaker=827129,Option='{那就试试吧,4},{这可不好说,3}',}",
  [633047] = "{id=633047,Text='冒险者！今天怎么有空过来？',Speaker=2627,Option='说明情况',}",
  [633051] = "{id=633051,Text='海底真是被搞的乱七八糟呢…前面的漩涡越来越密集，怪人应该就在那里吧。',Speaker=827129,}",
  [633052] = "{id=633052,Text='那就出发吧。',Speaker=827129,}",
  [633053] = "{id=633053,Text='你这看起来弱不禁风的样子，还胆敢来挑战我！',Speaker=827135,}",
  [633054] = "{id=633054,Text='你们这群人类！可恨！',Speaker=827135,}",
  [633055] = "{id=633055,Text='现在居然还闯进别人的地盘！也不看看自己才多少能耐！',Speaker=827135,}",
  [633056] = "{id=633056,Text='旁边那个小秃头，怎么？害怕地一言不发？',Speaker=827135,}",
  [633057] = "{id=633057,Text='……',Speaker=827129,}",
  [633058] = "{id=633058,Text='就你们这样，还敢来……',Speaker=827135,}",
  [633059] = "{id=633059,Text='啊……结束了……',Speaker=827129,}",
  [633060] = "{id=633060,Text='又是一拳就解决了，哎……',Speaker=827129,}",
  [633061] = "{id=633061,Text='啊……有点困……',Speaker=827129,}",
  [633062] = "{id=633062,Text='英雄之影的力量耗尽了。',}",
  [633063] = "{id=633063,Text='不愧是你！',Speaker=2627,Option='{不是我,0},{多亏了埼玉,0}',}",
  [633064] = "{id=633064,Text='诶~别谦虚！',Speaker=2627,Option='{……真的不是我,0},{听我解释啊！,0}',}",
  [633065] = "{id=633065,Text='我可要替你好好宣传一番！',Speaker=2627,Option='{……,0},{完全不听人解释,0}',}",
  [633066] = "{id=633066,Text='我代表所有人感谢您~',Speaker=2627,Option='{……不客气,0},{……算了,0}',}",
  [633072] = "{id=633072,Text='好久不见……不会又发生什么事了吧？',Speaker=827129,Option='梦罗克之影',}",
  [633073] = "{id=633073,Text='啊……可惜了，明明很新鲜……',Speaker=827129,Option='{转移话题,0},{梦罗克之影,0}',}",
  [633074] = "{id=633074,Text='很厉害吗？',Speaker=827129,Option='{异世界大魔王,0},{差点毁灭世界,0}',}",
  [633075] = "{id=633075,Text='是吗？那我们赶紧出发吧。',Speaker=827129,}",
  [633079] = "{id=633079,Text='有人来了！快放了我们！',Speaker=827150,}",
  [633080] = "{id=633080,Text='钥匙就在散落在周围的地上！',Speaker=827150,}",
  [633081] = "{id=633081,Text='快打开牢笼的门！',Speaker=827150,}",
  [633082] = "{id=633082,Text='啊……魔王好像不在这里呢……',Speaker=827129,}",
  [633083] = "{id=633083,Text='你们是谁！？怎么会出现在我的地盘里！？',Speaker=827149,Option='为什么假扮梦罗克？',}",
  [633084] = "{id=633084,Text='啊……难怪没有那么强。',Speaker=827129,}",
  [633085] = "{id=633085,Text='呵，如果不伪装成梦罗克，这些愚蠢的魔物们怎么会为我献上食物！？',Speaker=827149,}",
  [633086] = "{id=633086,Text='你们……你们倒好！把我的食物都放走了！！！',Speaker=827149,}",
  [633087] = "{id=633087,Text='好生气！！！啊啊啊啊啊啊！！！！',Speaker=827149,}",
  [633088] = "{id=633088,Text='啊……这次也不堪一击呀。',Speaker=827129,}",
  [633089] = "{id=633089,Text='好困……哈~欠~……',Speaker=827129,}",
  [633092] = "{id=633092,Text='又有什么委托了吗？',Speaker=827129,Option='邀请前往庆功宴',}",
  [633093] = "{id=633093,Text='庆功宴？……听着好麻烦。',Speaker=827129,Option='{有美食！,0},{随便吃！,0}',}",
  [633094] = "{id=633094,Text='可以随便吃？不要钱？那还等什么，赶紧出发吧。',Speaker=827129,}",
  [633095] = "{id=633095,Text='你快一些，我饿了。',Speaker=827129,}",
  [633121] = "{id=633121,Text='可恶的人类！给我的孩子们偿命吧！',Speaker=827169,}",
  [633126] = "{id=633126,Text='虽然敌人挺弱的，但是吃到了美食。还想再来一次烧烤宴呢。',Speaker=827129,}",
  [633129] = "{id=633129,Text='......',Speaker=827136,}",
  [633130] = "{id=633130,Text='......',Speaker=827137,}",
  [633131] = "{id=633131,Text='......',Speaker=827138,}",
  [633138] = "{id=633138,Text='谢谢你们！',}",
  [633144] = "{id=633144,Text='好大的乌贼！',}",
  [633150] = "{id=633150,Text='太好了！请务必注意自己的安全！',Speaker=2627,}",
  [633151] = "{id=633151,Text='啊，又见面了。',Speaker=827129,Option='说明情况',}",
  [633152] = "{id=633152,Text='哦？逃脱的怪人很强？真的吗？走吧，反正怪人是要打败的！',Speaker=827129,}",
  [633153] = "{id=633153,Text='啊……地上好像有脚印，应该是怪人们留下的。',Speaker=827129,}",
  [633154] = "{id=633154,Text='跟着脚印走，应该就能找到它们了吧。',Speaker=827129,}",
  [633155] = "{id=633155,Text='让开——蠢货们！',Speaker=827176,}",
  [633156] = "{id=633156,Text='今天绝不会让你们踏入吉芬一步！',Speaker=827167,}",
  [633157] = "{id=633157,Text='哦！魔法师！他一定是你们这里的强者吧！',Speaker=827129,}",
  [633158] = "{id=633158,Text='让你们看看什么是力量！',Speaker=827176,}",
  [633159] = "{id=633159,Text='……防线……必须……守住——咳咳——',Speaker=827167,}",
  [633160] = "{id=633160,Text='防御罩吗？看起来像魔法。',Speaker=827129,Option='我去帮忙',}",
  [633161] = "{id=633161,Text='冒险者！！……咳咳！！！——',Speaker=827167,}",
  [633162] = "{id=633162,Text='是你——哼，给我去死吧！',Speaker=827176,}",
  [633163] = "{id=633163,Text='这些魔法师怎么回事……这魔物明明很弱嘛……',Speaker=827177,}",
  [633164] = "{id=633164,Text='你看，刚刚那个光头小子，一拳就解决了。',Speaker=827177,}",
  [633165] = "{id=633165,Text='咳咳——原来我这么弱小……',Speaker=827189,}",
  [633166] = "{id=633166,Text='一拳就被击败黑暗之王，我们却无法阻挡……',Speaker=827189,}",
  [633167] = "{id=633167,Text='无碍，多亏了你们相助……不然今天黑暗之王就要突破防线，进入吉芬了。',Speaker=827167,}",
  [633168] = "{id=633168,Text='我也老了……现在的年轻人越来越厉害了……尤其是你的那位朋友……',Speaker=827167,}",
  [633169] = "{id=633169,Text='（大声）啊！——啊！——好幸运啊！——（大声）',Speaker=827129,Option='{嘘——,0},{小声点,0}',}",
  [633170] = "{id=633170,Text='（大声）这下大家应该都会很感激很崇拜我吧！我可是击败了黑暗之王了诶！',Speaker=827129,}",
  [633171] = "{id=633171,Text='（大声）也多亏了这些你和这些傻傻的魔法师们如此努力，消耗了黑暗之王的力量。',Speaker=827129,Option='{等等——！,0},{你该不会——？,0}',}",
  [633172] = "{id=633172,Text='（大声）我才能一拳就击倒了他，捡了个漏呢！',Speaker=827129,}",
  [633173] = "{id=633173,Text='（大声）这回，我的名字也该传遍米德加尔特大陆了吧！',Speaker=827129,}",
  [633174] = "{id=633174,Text='（大声）太好了呢！你们——都记住了！我叫埼玉！是击败黑暗之王的男人！',Speaker=827129,}",
  [633175] = "{id=633175,Text='呼——最近怎么了，稍微打一拳就会觉得困呢……',Speaker=827129,Option='{英雄之影的力量,0},{快耗尽了,0}',}",
  [633176] = "{id=633176,Text='呼……原来是这样……你这个像被打了一拳的表情是怎么回事？',Speaker=827129,Option='{你刚刚的话,0},{明明不是真的,0}',}",
  [633177] = "{id=633177,Text='我又不在意这些……无论别人怎么说我，我做英雄都是因为出于兴趣。',Speaker=827129,}",
  [633178] = "{id=633178,Text='更何况刚刚那群魔法师，用尽了全力想要保护大家，他们也是英雄，怎么能因为我而被大家误解为无能。',Speaker=827129,}",
  [633179] = "{id=633179,Text='哈~欠~这些事都不重要，我困了……先睡一会……',Speaker=827129,}",
  [633184] = "{id=633184,Text='啊……冒险者……还有魔法大叔和另外一个大叔？……',Speaker=827129,}",
  [633185] = "{id=633185,Text='初次见面，我是贤者学院的院长西芙。',Speaker=827180,}",
  [633186] = "{id=633186,Text='我是埼玉。你们……三个来堵我是有什么事？',Speaker=827129,}",
  [633187] = "{id=633187,Text='你那天说想要找个旗鼓相当的对手，我们可以帮你找到。',Speaker=827167,}",
  [633188] = "{id=633188,Text='哦？谁？',Speaker=827129,}",
  [633189] = "{id=633189,Text='[c][ffff00][PlayerName][-][/c]。',Speaker=827167,Option='{什么？！我？,0},{开……开玩笑吧？,0}',}",
  [633190] = "{id=633190,Text='对，是你。你是这个世界强者的一员。',Speaker=827180,}",
  [633191] = "{id=633191,Text='没开玩笑，你可是这个世界上的强者之一啊。',Speaker=827180,}",
  [633192] = "{id=633192,Text='我知道你在担心自己的实力和埼玉勇士之间还有一定的差距，不过别担心，西芙已经有办法了。',Speaker=827167,}",
  [633193] = "{id=633193,Text='冒险者，伊米尔之书不是可以让你和埼玉的力量发生共鸣吗？',Speaker=827180,}",
  [633194] = "{id=633194,Text='听着好像很有趣的样子。',Speaker=827129,}",
  [633195] = "{id=633195,Text='不过唯一麻烦的是，埼玉勇士的力量过于强大，我们需要建造一片魔法空间才能避免周遭受到影响。',Speaker=827167,}",
  [633196] = "{id=633196,Text='怎么样？为了埼玉的愿望，要不要试一试？',Speaker=827180,}",
  [633197] = "{id=633197,Text='哈哈哈哈，别担心，我们两个也会帮助你们的。',Speaker=827167,}",
  [633198] = "{id=633198,Text='一切准备就绪后，就可以进入这个空间。',Speaker=827180,}",
  [633199] = "{id=633199,Text='冒险者，进入空间后，你就可以使用命运宝石，与埼玉的力量共鸣。',Speaker=827180,}",
  [633200] = "{id=633200,Text='埼玉勇士，希望这一次，你可以实现你的愿望。',Speaker=827167,}",
  [633201] = "{id=633201,Text='啊……我也希望可以吧……',Speaker=827129,}",
  [633202] = "{id=633202,Text='魔法好厉害呀……这里面的一切都看着很真实……',Speaker=827129,}",
  [633203] = "{id=633203,Text='没想过有一天还会和你打一架。',Speaker=827129,}",
  [633204] = "{id=633204,Text='准备好了的话可以开始了。',Speaker=827129,}",
  [633205] = "{id=633205,Text='那么，开始了。',Speaker=827129,}",
  [633206] = "{id=633206,Text='久违地进行了一次充分的运动。',Speaker=827129,Option='最强对手是你自己',}",
  [633207] = "{id=633207,Text='这倒是个新奇的想法……最强的对手我是自己吗？……',Speaker=827129,}",
  [633208] = "{id=633208,Text='怎么说呢，我在获得了强大的战斗力后失去了很多，丧失了恐惧、激情、紧张，头发也在变强后掉光了。',Speaker=827129,}",
  [633209] = "{id=633209,Text='太过于强大，让我无法从对手身上学习到什么，无法享受成长的快乐。',Speaker=827129,}",
  [633210] = "{id=633210,Text='我的内心变得越来越空虚了，对任何事都感到非常无聊。',Speaker=827129,}",
  [633211] = "{id=633211,Text='有人建议我去交点朋友或者来一场旅行，我原本没有心情做这些，但是没想到这次居然都做了。',Speaker=827129,}",
  [633212] = "{id=633212,Text='最近虽然很无聊，但是认识了你和魔法大叔，见识过了真的魔法， 看过了异世界的风景，吃到了美味的料理。',Speaker=827129,}",
  [633213] = "{id=633213,Text='感觉，这也都挺有趣的。',Speaker=827129,}",
  [633214] = "{id=633214,Text='埼玉的力量融进了体内，带着他的力量继续前行吧。',}",
  [633215] = "{id=633215,Text='原来是捡漏！',}",
  [633216] = "{id=633216,Text='不要脸！',}",
  [633217] = "{id=633217,Text='多亏了魔法师们呢！',}",
  [633218] = "{id=633218,Text='原来是这样……',}",
  [633219] = "{id=633219,Text='魔法师们在干什么啊？',}",
  [633220] = "{id=633220,Text='他们好没用啊……',}",
  [633221] = "{id=633221,Text='魔物明明很弱嘛……',}",
  [633222] = "{id=633222,Text='啊……有机会的话，再一起做感兴趣的事吧。',}",
  [633224] = "{id=633224,Text='多亏了你们……不然今天黑暗之王就要进入吉芬了。',Speaker=827167,}",
  [633225] = "{id=633225,Text='咳咳……能否再采集一些草药，救治受伤的民众？',Speaker=827167,Option='{交给我吧,0},{乐意之至,0}',}",
  [633226] = "{id=633226,Text='多谢……咳咳……多加小心……森林中应该还残留了一些黑暗之王的手下。',Speaker=827167,}",
  [633227] = "{id=633227,Text='我来对付剩下的怪人，草药就交给你了。',Speaker=827129,}",
  [633228] = "{id=633228,Text='虽然这次的敌人也好弱，但是解决了一件事。',Speaker=827129,}",
  [633229] = "{id=633229,Text='哈~欠~我先睡一会……',Speaker=827129,}",
  [633230] = "{id=633230,Text='他们也是真正的英雄……哈~欠~我困了……先睡一会……',Speaker=827129,}",
  [633231] = "{id=633231,Text='冒险者们！欢迎来到第一实验区！',Speaker=6887,}",
  [633232] = "{id=633232,Text='冒险者们！欢迎来到第二实验区！',Speaker=6887,}",
  [633233] = "{id=633233,Text='冒险者们！欢迎来到第三实验区！',Speaker=6887,}",
  [633234] = "{id=633234,Text='冒险者们！欢迎来到第四实验区！',Speaker=6887,}",
  [633235] = "{id=633235,Text='冒险者们！欢迎来到第五实验区！',Speaker=6887,}",
  [633236] = "{id=633236,Text='冒险者们！欢迎来到第六实验区！',Speaker=6887,}",
  [633237] = "{id=633237,Text='冒险者们！欢迎来到第七实验区！',Speaker=6887,}",
  [633238] = "{id=633238,Text='快过来！一切都已经准备就绪~！',Speaker=6887,}",
  [633239] = "{id=633239,Text='环境调试完成。',}",
  [633240] = "{id=633240,Text='调试的很不错。',}",
  [633241] = "{id=633241,Text='希望能有新进展。',}",
  [633242] = "{id=633242,Text='确认实验体状况了吗？',}",
  [633243] = "{id=633243,Text='状况良好，可以开启实验。',}",
  [633244] = "{id=633244,Text='不会出岔子吧？',}",
  [633245] = "{id=633245,Text='那是谁？',}",
  [633246] = "{id=633246,Text='那位传说中的冒险者。',}",
  [633247] = "{id=633247,Text='研究所这次可下了血本了。',}",
  [633248] = "{id=633248,Text='是啊，究竟引进了多少魔物？',}",
  [633249] = "{id=633249,Text='好几天没睡觉了。',}",
  [633250] = "{id=633250,Text='我也是。',}",
  [633251] = "{id=633251,Text='呼，实验赶紧结束吧。',}",
  [633252] = "{id=633252,Text='大家用热烈的掌声欢迎我们的志愿者！',Speaker=6887,}",
  [633253] = "{id=633253,Text='冒险者，在实验开启前，请容许我再次向你确认。',Speaker=6887,}",
  [633254] = "{id=633254,Text='这里是危险系数1星的第一实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633255] = "{id=633255,Text='这里是危险系数2星的第二实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633256] = "{id=633256,Text='这里是危险系数3星的第三实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633257] = "{id=633257,Text='这里是危险系数4星的第四实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633258] = "{id=633258,Text='这里是危险系数5星的第五实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633259] = "{id=633259,Text='这里是危险系数6星的第六实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633260] = "{id=633260,Text='这里是危险系数7星的第七实验室，你是否准备好开启实验，面对严酷的战斗？',Speaker=6887,Option='{立即开始,2},{稍等一下,3}',}",
  [633261] = "{id=633261,Text='没关系，这种事情确实需要好好思考，好好准备。',Speaker=6887,}",
  [633262] = "{id=633262,Text='那么，勇敢的冒险者！伟大的志愿者！现在，开启我们的实验！',Speaker=6887,}",
  [633263] = "{id=633263,Text='真厉害啊！',}",
  [633264] = "{id=633264,Text='赶紧记录下来！',}",
  [633265] = "{id=633265,Text='精彩的战斗！',}",
  [633266] = "{id=633266,Text='原来如此……',}",
  [633267] = "{id=633267,Text='现在我宣布！实验成功！！',Speaker=6887,}",
  [633268] = "{id=633268,Text='这是研究所为你们准备的小小心意，请你收下。',Speaker=6887,}",
  [633269] = "{id=633269,Text='我们随时欢迎你的再次到来！',Speaker=6887,}",
  [633270] = "{id=633270,Text='天哪！',}",
  [633271] = "{id=633271,Text='没事吧？',}",
  [633272] = "{id=633272,Text='看上去很疼。',}",
  [633273] = "{id=633273,Text='实验失败了……',}",
  [633274] = "{id=633274,Text='……没关系！休息一下！重新来过！',Speaker=6887,}",
  [633275] = "{id=633275,Text='现在要出场的是曾经的天才魔法少女！凯特莉娜！',Speaker=6887,}",
  [633276] = "{id=633276,Text='不亏是魔法天才！多种属性轮番输出！流畅至极！',Speaker=6887,}",
  [633277] = "{id=633277,Text='风！水！火！暗！让我们看看还有什么惊喜！',Speaker=6887,}",
  [633278] = "{id=633278,Text='哎，冒险者真是高危职业，看看这女孩……哎。',Speaker=6887,}",
  [633279] = "{id=633279,Text='锐利的箭矢，矫健的身姿——是神射手迪文！',Speaker=6887,}",
  [633280] = "{id=633280,Text='看看着陷阱！布置的是如此完美！',Speaker=6887,}",
  [633281] = "{id=633281,Text='嗯？哈沃德？他怎么出现的？他……在保护迪文！',Speaker=6887,}",
  [633282] = "{id=633282,Text='流畅的手臂线条，出色的观察力，不愧是神射手。',Speaker=6887,}",
  [633283] = "{id=633283,Text='是谁的视线在暗处锁定了你，哦！是艾勒梅斯！',Speaker=6887,}",
  [633284] = "{id=633284,Text='小心毒雾！艾勒梅斯调制的毒可不是开玩笑的。',Speaker=6887,}",
  [633285] = "{id=633285,Text='眼睛要花了！到底哪个才是他的本体！',Speaker=6887,}",
  [633286] = "{id=633286,Text='太帅了！这就是刺客中的王者，男人中的男人！',Speaker=6887,}",
  [633287] = "{id=633287,Text='来自拉赫的幽暗梦魇，你准备好面对它了吗？',Speaker=6887,}",
  [633288] = "{id=633288,Text='稀有念属性就是这无比强大的防御能力的由来？',Speaker=6887,}",
  [633289] = "{id=633289,Text='不要被迷惑而陷入恐惧！这都是它的小伎俩！',Speaker=6887,}",
  [633290] = "{id=633290,Text='天哪！它居然还能召唤拉赫的信徒来强化自己！',Speaker=6887,}",
  [633291] = "{id=633291,Text='快看！地面都在震动！巨牛欧德姆布拉出现了！',Speaker=6887,}",
  [633292] = "{id=633292,Text='不愧是经历了无尽悠长岁月的生物，十分抗揍。',Speaker=6887,}",
  [633293] = "{id=633293,Text='它！它！它！还会分身！你们可要小心了！',Speaker=6887,}",
  [633294] = "{id=633294,Text='它的寿命为何如此长久？人类也可以做到吗？',Speaker=6887,}",
  [633295] = "{id=633295,Text='这是未来将诞生出一整个世界的天地树之种！',Speaker=6887,}",
  [633296] = "{id=633296,Text='天地树种子的诞生是天地树自我保护的一种方式。',Speaker=6887,}",
  [633297] = "{id=633297,Text='原来如此，这些守护之花是用来自卫的。',Speaker=6887,}",
  [633298] = "{id=633298,Text='如果把天地树之种种在大陆上，是不是……',Speaker=6887,}",
  [633299] = "{id=633299,Text='听……着美妙的音乐……哦~是灵魂奏者！',Speaker=6887,}",
  [633300] = "{id=633300,Text='哦~这音乐~只有精灵才能写出这样的旋律吧~',Speaker=6887,}",
  [633301] = "{id=633301,Text='可不要被她的分身迷惑了！只有一个是真的她！',Speaker=6887,}",
  [633302] = "{id=633302,Text='我听闻她原本也是一个精灵，怎么会变成这样呢？',Speaker=6887,}",
  [633303] = "{id=633303,Text='天哪！是魔鬼大乌贼！今晚的夜宵有着落了！',Speaker=6887,}",
  [633304] = "{id=633304,Text='可要当心它的触手，可攻可守，别被打到了。',Speaker=6887,}",
  [633305] = "{id=633305,Text='一般来说越好吃的东西越灵活。',Speaker=6887,}",
  [633306] = "{id=633306,Text='冒险者们，加油啊！今晚的夜宵全看你们的了！',Speaker=6887,}",
  [633307] = "{id=633307,Text='即将出场的是塔奥群卡，来自克魔岛的艺术品。',Speaker=6887,}",
  [633308] = "{id=633308,Text='根据研究，它原本是一块极其坚硬的石块雕成的。',Speaker=6887,}",
  [633309] = "{id=633309,Text='石头这种材质嘛，你们懂得，防御能力极高。',Speaker=6887,}",
  [633310] = "{id=633310,Text='我的天哪！它居然会遁地！它拥有智慧！',Speaker=6887,}",
  [633311] = "{id=633311,Text='我感受了死者的怨气……迷梦猫妖！它来了！',Speaker=6887,}",
  [633312] = "{id=633312,Text='在怨气中诞生的生物，有意思……好想解剖了它！',Speaker=6887,}",
  [633313] = "{id=633313,Text='这极高的防御能力是哪里来的？真是奇妙。',Speaker=6887,}",
  [633314] = "{id=633314,Text='它用自己的力量链接了异次元！梦幻般的魔物啊！',Speaker=6887,}",
  [633315] = "{id=633315,Text='这威压——贞奴比亚！是贞奴比亚！她太美了！',Speaker=6887,}",
  [633316] = "{id=633316,Text='堕落的精灵，女神的使者，务必小心她的利爪。',Speaker=6887,}",
  [633317] = "{id=633317,Text='她的战斗方式很像人类。',Speaker=6887,}",
  [633318] = "{id=633318,Text='信仰会是她强大之力的来源吗？',Speaker=6887,}",
  [633319] = "{id=633319,Text='嘘——这位巴尔特大人，我们可是惹不起的啊。',Speaker=6887,}",
  [633320] = "{id=633320,Text='哦~不愧是巴尔特家族！看看这机甲！昂贵！',Speaker=6887,}",
  [633321] = "{id=633321,Text='这机甲太厉害了——等等我们研究的不是魔物吗？',Speaker=6887,}",
  [633322] = "{id=633322,Text='燃烧弹！喷火！冲击波！还有什么！想看！',Speaker=6887,}",
  [633323] = "{id=633323,Text='久别重逢，冒险者，你可不要下不去手啊。',Speaker=6887,}",
  [633324] = "{id=633324,Text='不错的剑法，虽然还有些稚嫩。',Speaker=6887,}",
  [633325] = "{id=633325,Text='剑阵！厉害啊！哎……太可惜了。',Speaker=6887,}",
  [633326] = "{id=633326,Text='若是通过研究帮助她恢复的话，该有多好。',Speaker=6887,}",
  [633327] = "{id=633327,Text='听到ZENY叮叮当当的声音了吗？是娣洁来了。',Speaker=6887,}",
  [633328] = "{id=633328,Text='真是一位不折不扣的商人，手推车不离身。',Speaker=6887,}",
  [633329] = "{id=633329,Text='可不要小看一个商人的手推车，能赚钱也能打架。',Speaker=6887,}",
  [633330] = "{id=633330,Text='看到了吗？！她的手推车爆炸了！',Speaker=6887,}",
  [633331] = "{id=633331,Text='锁链的声音……是莉姆露，抓它可是不容易啊。',Speaker=6887,}",
  [633332] = "{id=633332,Text='可爱的小兔子，是谁把你用锁链捆起来的？',Speaker=6887,}",
  [633333] = "{id=633333,Text='它的身上有诅咒的气息……',Speaker=6887,}",
  [633334] = "{id=633334,Text='果然是只小兔子，冒险者们，小心它的连续撞击。',Speaker=6887,}",
  [633335] = "{id=633335,Text='这光芒——宝石灵兽！可恶它吃了我们不少家当！',Speaker=6887,}",
  [633336] = "{id=633336,Text='绿色的光芒让它拥有了远远不断的生命力！',Speaker=6887,}",
  [633337] = "{id=633337,Text='蓝色的光芒……冒险者！小心眩晕！',Speaker=6887,}",
  [633338] = "{id=633338,Text='不妙，红色光芒该不会是……果然，攻击力暴增。',Speaker=6887,}",
  [633339] = "{id=633339,Text='我们的晚餐——大脚龙虾举着两个大钳子出现了！',Speaker=6887,}",
  [633340] = "{id=633340,Text='为什么要叫大脚龙虾，而不是大钳子龙虾？',Speaker=6887,}",
  [633341] = "{id=633341,Text='就和普通龙虾一样，它唯一的武器就是两只钳子。',Speaker=6887,}",
  [633342] = "{id=633342,Text='哦！还是挺厉害的嘛！这钳子居然能夹碎大石块！',Speaker=6887,}",
  [633343] = "{id=633343,Text='是谁？嗯？小不点矿石精？打败它可能会发财哦！',Speaker=6887,}",
  [633344] = "{id=633344,Text='好多矿石啊……研究所是不是不用为资金犯愁了。',Speaker=6887,}",
  [633345] = "{id=633345,Text='它躲进矿石中了！它在恢复自己的生命！',Speaker=6887,}",
  [633346] = "{id=633346,Text='通过仔细观察，我发现了——它害怕火！',Speaker=6887,}",
  [633347] = "{id=633347,Text='风向变了，力量与美的化身——白鹭女王降临！',Speaker=6887,}",
  [633348] = "{id=633348,Text='活跃在猎场中的顶级捕食者，现在成为了笼中鸟。',Speaker=6887,}",
  [633349] = "{id=633349,Text='它的移动速度可以说在这些魔物中首屈一指。',Speaker=6887,}",
  [633350] = "{id=633350,Text='小心，别被她连续打到，会越来越疼的……',Speaker=6887,}",
  [633355] = "{id=633355,Text='时空正在被加速撕裂，梦罗克将这些混沌魔物大量投放至大陆。冒险者，你是否愿意祝我们一臂之力？',Speaker=827519,}",
  [633356] = "{id=633356,Text='此事关于整个米德加尔特大陆的安全，卢恩王国与修发兹共和国联手展开调查与应对。',Speaker=827519,}",
  [633357] = "{id=633357,Text='魔物研究所联合雷根贝勒公司研制出了“[c][ffff00]净化之水[-][/c]”，可以驱散魔物们体内的混沌之力，让它们恢复正常。',Speaker=827519,}",
  [633358] = "{id=633358,Text='根据监测，时空正在被加速撕裂，梦罗克将这些混沌魔物大量投放至大陆。',Speaker=827519,}",
  [633359] = "{id=633359,Text='我们急需招募冒险者们帮助我们，净化这些混沌魔物。',Speaker=827519,}",
  [633371] = "{id=633371,Text='他试图用混沌之力来控制所有的生物，让他们都成为他的信徒，从而彻底主宰天地树世界。',Speaker=827519,}",
  [633372] = "{id=633372,Text='此事刻不容缓，若是让这些携带混沌之力的魔物侵入米德加尔特，后果不堪设想。',Speaker=827519,}",
  [633373] = "{id=633373,Text='只有彻底净化这些混沌之力，我们才能阻止梦罗克的计划！',Speaker=827519,}",
  [633377] = "{id=633377,Text='冒险者们！裂隙在这！一切都已准备就绪！',Speaker=827519,}",
  [633378] = "{id=633378,Text='我们已将周围区域封锁，以免造成伤害。',Speaker=827519,}",
  [633379] = "{id=633379,Text='魔王究竟想干什么？',}",
  [633380] = "{id=633380,Text='毁灭世界。',}",
  [633381] = "{id=633381,Text='希望不会出岔子。',}",
  [633382] = "{id=633382,Text='这些人是谁？',}",
  [633383] = "{id=633383,Text='传说中的冒险者。',}",
  [633384] = "{id=633384,Text='第一次合作愉快。',}",
  [633385] = "{id=633385,Text='互相学习。',}",
  [633386] = "{id=633386,Text='好几天没睡觉了。',}",
  [633387] = "{id=633387,Text='我也是。',}",
  [633388] = "{id=633388,Text='净化之水也已经涂抹在各位的武器上了。',Speaker=827519,}",
  [633389] = "{id=633389,Text='做好准备的话，就请靠近裂隙吧！',Speaker=827519,}",
  [633390] = "{id=633390,Text='充满着次元之力与混沌之力。是否已经做好了战斗的准备？',Speaker=827521,Option='{准备好了,11},{再等一下,12}',}",
  [633391] = "{id=633391,Text='滋——滋——命运之风……又是你……感受混沌吧——桀桀桀！！',Speaker=827520,}",
  [633392] = "{id=633392,Text='这只是第一步……',Speaker=827520,}",
  [633393] = "{id=633393,Text='混沌……将重新笼罩天地树！',Speaker=827520,}",
  [633394] = "{id=633394,Text='桀桀桀，这就是混沌的力量！',Speaker=827520,}",
  [633395] = "{id=633395,Text='成为我的追随者，你将获得全新的力量！',Speaker=827520,}",
  [633396] = "{id=633396,Text='去撕咬，去侵蚀，去毁灭！',Speaker=827520,}",
  [633397] = "{id=633397,Text='我——将再次成为主宰！',Speaker=827520,}",
  [633398] = "{id=633398,Text='真厉害啊！',}",
  [633399] = "{id=633399,Text='净化成功！',}",
  [633400] = "{id=633400,Text='精彩的战斗！',}",
  [633401] = "{id=633401,Text='恢复了！',}",
  [633402] = "{id=633402,Text='可恶！……等着，我终究会回来的！',Speaker=827520,}",
  [633403] = "{id=633403,Text='我宣布！净化成功！！',Speaker=827519,}",
  [633404] = "{id=633404,Text='这是我们准备的小小心意，请你收下。',Speaker=827519,}",
  [633405] = "{id=633405,Text='希望下一次还能得到你们的协助！',Speaker=827519,}",
  [633406] = "{id=633406,Text='天哪！',}",
  [633407] = "{id=633407,Text='没事吧？',}",
  [633408] = "{id=633408,Text='大陆要完蛋了！',}",
  [633409] = "{id=633409,Text='失败了……',}",
  [633410] = "{id=633410,Text='还不到放弃的时候！为了人类！为了荣耀！',Speaker=827519,}",
  [633411] = "{id=633411,Text='是曾经的天才魔法少女！凯特莉娜！',Speaker=827519,}",
  [633412] = "{id=633412,Text='不亏是魔法天才！多种属性轮番输出！流畅至极！',Speaker=827519,}",
  [633413] = "{id=633413,Text='锐利的箭矢，矫健的身姿——是神射手迪文！',Speaker=827519,}",
  [633414] = "{id=633414,Text='布置如此完美的陷阱，你们要小心啊！',Speaker=827519,}",
  [633415] = "{id=633415,Text='危险！艾勒梅斯调制的毒可不是闹着玩的。',Speaker=827519,}",
  [633416] = "{id=633416,Text='眼睛要花了！到底哪个才是他的本体！',Speaker=827519,}",
  [633417] = "{id=633417,Text='连幽暗梦魇都……冒险者们，注意安全。',Speaker=827519,}",
  [633418] = "{id=633418,Text='不要被迷惑而陷入恐惧！这都是它的小伎俩！',Speaker=827519,}",
  [633419] = "{id=633419,Text='这是巨牛欧德姆布拉！魔王竟然连它都抓到了！',Speaker=827519,}",
  [633420] = "{id=633420,Text='不愧是经历了无尽悠长岁月的生物……',Speaker=827519,}",
  [633421] = "{id=633421,Text='避开那些守护之花，不要被美丽的外表迷惑。',Speaker=827519,}",
  [633422] = "{id=633422,Text='天地树种子一定要抢回来啊！这可是希望之种。',Speaker=827519,}",
  [633423] = "{id=633423,Text='哦~这音乐~只有精灵才能写出这样的旋律吧~',Speaker=827519,}",
  [633424] = "{id=633424,Text='不要被她的分身迷惑！找出她的真身！',Speaker=827519,}",
  [633425] = "{id=633425,Text='注意它的触手，别被打到了。',Speaker=827519,}",
  [633426] = "{id=633426,Text='灵活的触手，兼顾防御和攻击。',Speaker=827519,}",
  [633427] = "{id=633427,Text='危险！这种石料极其坚硬，防御力极高。',Speaker=827519,}",
  [633428] = "{id=633428,Text='它要遁地了，小心警戒。',Speaker=827519,}",
  [633429] = "{id=633429,Text='在怨气中诞生的生物……不要被吞噬了！',Speaker=827519,}",
  [633430] = "{id=633430,Text='它用自己的力量链接的次元！',Speaker=827519,}",
  [633431] = "{id=633431,Text='堕落的精灵，女神的使者。',Speaker=827519,}",
  [633432] = "{id=633432,Text='务必小心她的利爪。',Speaker=827519,}",
  [633433] = "{id=633433,Text='巴……巴尔特大人！快！快救下他！',Speaker=827519,}",
  [633434] = "{id=633434,Text='这机甲……太厉害了……小心冲击波！',Speaker=827519,}",
  [633435] = "{id=633435,Text='可恶！赛尼亚居然也被……',Speaker=827519,}",
  [633436] = "{id=633436,Text='冒险者们，小心！是剑阵！',Speaker=827519,}",
  [633437] = "{id=633437,Text='ZENY叮叮当当的声音，是娣洁。',Speaker=827519,}",
  [633438] = "{id=633438,Text='警惕她的小推车，会爆炸。',Speaker=827519,}",
  [633439] = "{id=633439,Text='可怜的小兔子，先被人诅咒，又被混沌侵染。',Speaker=827519,}",
  [633440] = "{id=633440,Text='别被可爱的外表迷惑，小心它的连续撞击！',Speaker=827519,}",
  [633441] = "{id=633441,Text='注意它发出的光芒，不同的颜色代表不同的效果！',Speaker=827519,}",
  [633442] = "{id=633442,Text='红色，蓝色，绿色……眼睛都要花了。',Speaker=827519,}",
  [633443] = "{id=633443,Text='就和普通龙虾一样，它唯一的武器就是两只钳子。',Speaker=827519,}",
  [633444] = "{id=633444,Text='嘶……这钳子能夹碎大石块！小心了！',Speaker=827519,}",
  [633445] = "{id=633445,Text='它会躲进矿石中恢复自己的生命！',Speaker=827519,}",
  [633446] = "{id=633446,Text='通过仔细观察，我发现了——它害怕火！',Speaker=827519,}",
  [633447] = "{id=633447,Text='力量与美的化身，速度王者——白鹫女王！',Speaker=827519,}",
  [633448] = "{id=633448,Text='小心，别被她连续打到，会越来越疼的……',Speaker=827519,}",
  [652180] = "{id=652180,Text='小捣蛋和小顽皮哭得稀里哗啦的……',}",
  [652197] = "{id=652197,Text='白素贞走进房间里。',}",
  [652198] = "{id=652198,Text='不可能！',Speaker=811506,}",
  [652199] = "{id=652199,Text='（模糊）…拥有伊米尔之心的碎片。',Speaker=811506,}",
  [652200] = "{id=652200,Text='都是欺骗和假象！',Speaker=811506,}",
  [652201] = "{id=652201,Text='我不想再……（模糊）',Speaker=811369,}",
  [652202] = "{id=652202,Text='不小心听到白素贞和客人交谈，似乎不太礼貌。',}",
  [652203] = "{id=652203,Text='踩到松动的地板，发出吱呀的响声！',}",
  [652204] = "{id=652204,Text='是谁？',Speaker=811369,}",
  [652205] = "{id=652205,Text='你，在我的房间做什么？',Speaker=811369,Option='慰问',}",
  [652206] = "{id=652206,Text='多谢你的好意，但是我现在有些事情要处理。',Speaker=811369,}",
  [652207] = "{id=652207,Text='请你在门外稍等我一会……',Speaker=811369,}",
  [652208] = "{id=652208,Text='你怎么在这里？',Speaker=811371,}",
  [652216] = "{id=652216,Text='但是请相信我，我会全力补救我的过错。',Speaker=811369,}",
  [652218] = "{id=652218,Text='你连刚刚陌生的女人是谁都不肯说，我怎么才能相信你？',Speaker=811371,}",
  [652248] = "{id=652248,Text='[c][ffff00][PlayerName][-][/c]，给你一盏莲花灯。',Speaker=811372,}",
  [652249] = "{id=652249,Text='这是为古恩大人祈福的灯，请把它送到古恩大人面前吧。',Speaker=811372,}",
  [652250] = "{id=652250,Text='准备取走地上的莲花灯？',Speaker=811558,Option='{是的,3},{放弃,2}',}",
  [652251] = "{id=652251,Text='愿古恩大人的灵魂，在沉睡中，永远注视着你。',Speaker=811372,}",
  [652252] = "{id=652252,Text='（沉重）今天是悲伤的一天。',Speaker=811368,}",
  [652253] = "{id=652253,Text='我们失去了洛阳的守护者古恩。',Speaker=811368,}",
  [652254] = "{id=652254,Text='千年之前，他带领法纳族与毒牙族战胜入侵的魔族。',Speaker=811368,}",
  [652255] = "{id=652255,Text='而现在，他为了修复时空结界，消耗了最后一点力量。',Speaker=811368,}",
  [652256] = "{id=652256,Text='我们将铭记古恩对洛阳的贡献。',Speaker=811368,}",
  [652257] = "{id=652257,Text='带着他的希冀，面对未来的生活。',Speaker=811368,}",
  [652258] = "{id=652258,Text='我也将继承古恩的意志，担负保护洛阳的责任。',Speaker=811368,}",
  [652259] = "{id=652259,Text='现在我们请[c][ffff00][PlayerName][-][/c]，为古恩献上鲜花。',Speaker=811368,}",
  [652260] = "{id=652260,Text='放开我们手中的灯，让它带着我们的愿望。',Speaker=811368,}",
  [652261] = "{id=652261,Text='飞向灵魂栖息的地方。',Speaker=811368,}",
  [652262] = "{id=652262,Text='（高声）也许，我们可以唤醒龙神古恩。',Speaker=811369,}",
  [652263] = "{id=652263,Text='白素贞？！',Speaker=811370,}",
  [652264] = "{id=652264,Text='你又想做些什么？',Speaker=811370,}",
  [652265] = "{id=652265,Text='（无视法海的问题）古恩大人是因为力量消耗过多，陷入沉睡。',Speaker=811369,Emoji=5,}",
  [652266] = "{id=652266,Text='只要我们能补充古恩消耗的力量。',Speaker=811369,}",
  [652267] = "{id=652267,Text='就能唤醒他。',Speaker=811369,}",
  [652268] = "{id=652268,Text='古恩缺失的力量，我们无法——',Speaker=811370,}",
  [652269] = "{id=652269,Text='我可以！',Speaker=811369,}",
  [652270] = "{id=652270,Text='只要有伊米尔之心碎片。',Speaker=811369,}",
  [652271] = "{id=652271,Text='就可以补充古恩消耗的力量，让他苏醒。',Speaker=811369,}",
  [652272] = "{id=652272,Text='伊米尔之心的碎片？',Speaker=811369,}",
  [652273] = "{id=652273,Text='那是什么？',Speaker=811369,}",
  [652274] = "{id=652274,Text='不知道是什么？',Speaker=811369,}",
  [652275] = "{id=652275,Text='怎么才能唤醒古恩大人？',Speaker=811369,}",
  [652276] = "{id=652276,Text='你怎么知道伊米尔之心的碎片？',Speaker=811370,}",
  [652277] = "{id=652277,Text='我不仅知道伊米尔之心碎片。',Speaker=811369,}",
  [652278] = "{id=652278,Text='我还有一枚碎片。',Speaker=811369,}",
  [652279] = "{id=652279,Text='这枚碎片的力量比较微弱。',Speaker=811369,}",
  [652280] = "{id=652280,Text='也足够唤醒古恩了。',Speaker=811369,}",
  [652281] = "{id=652281,Text='真的可以吗？',Speaker=811369,}",
  [652282] = "{id=652282,Text='为什么白素贞能唤醒古恩？',Speaker=811369,}",
  [652283] = "{id=652283,Text='如果古恩大人能醒过来就好了。',Speaker=811369,}",
  [652284] = "{id=652284,Text='所有居民，纪念仪式暂停。',Speaker=811370,}",
  [652285] = "{id=652285,Text='请大家离开流之云边。',Speaker=811370,}",
  [652300] = "{id=652300,Text='我也一直在调查这件事情。',Speaker=811369,}",
  [652301] = "{id=652301,Text='我发现了更多的疑点。',Speaker=811369,}",
  [652302] = "{id=652302,Text='父亲中的毒，是神域流出的[c][ffff00]咒毒[-][/c]！',Speaker=811369,}",
  [652303] = "{id=652303,Text='我的朋友，从神域带来了[c][ffff00]咒毒[-][/c]的样本。',Speaker=811369,}",
  [652304] = "{id=652304,Text='这种咒毒，需要强大的神器作为载体，才能使用。',Speaker=811369,}",
  [652305] = "{id=652305,Text='千年前，我父亲的死亡，也许是神域的一个阴谋！',Speaker=811369,}",
  [652306] = "{id=652306,Text='敌人在暗处，洛阳必须团结起来。',Speaker=811369,}",
  [652307] = "{id=652307,Text='你房间里的陌生女人，就是你的朋友吗？',Speaker=811369,}",
  [652308] = "{id=652308,Text='是的，她是[c][ffff00]女神的神使[-][/c]。',Speaker=811369,}",
  [652309] = "{id=652309,Text='这次进入洛阳，是为了调查[c][ffff00]咒毒[-][/c]外泄的事。',Speaker=811369,}",
  [652314] = "{id=652314,Text='白素贞的态度太诡异了……',Speaker=811370,}",
  [652315] = "{id=652315,Text='也许，她是真的想要帮助我们？',Speaker=811368,}",
  [652316] = "{id=652316,Text='平安呢？',Speaker=811370,}",
  [652317] = "{id=652317,Text='他应该一直跟着白素贞。',Speaker=811370,}",
  [652318] = "{id=652318,Text='好像很久没见到平安了。',Speaker=811370,Option='陈述',Emoji=8,}",
  [652319] = "{id=652319,Text='落日浅滩有像平安的人？',Speaker=811370,}",
  [652320] = "{id=652320,Text='去找到平安，问问他白素贞那个所谓的朋友。',Speaker=811370,}",
  [652321] = "{id=652321,Text='到底是什么人。',Speaker=811370,}",
  [652322] = "{id=652322,Text='是',Speaker=811426,}",
  [652323] = "{id=652323,Text='[c][ffff00][PlayerName][-][/c]，你也去帮忙吧。',Speaker=811370,}",
  [652324] = "{id=652324,Text='我始终有些不安。',Speaker=811370,}",
  [652330] = "{id=652330,Text='那个锦衣卫，到底是什么情况？',Speaker=811613,}",
  [652331] = "{id=652331,Text='谁知道呢？太吓人了！',Speaker=811612,}",
  [652332] = "{id=652332,Text='他好像情况很糟糕……',Speaker=811611,}",
  [652333] = "{id=652333,Text='（警戒）你是谁，站在我们旁边做什么？',Speaker=811612,}",
  [652334] = "{id=652334,Text='我们正在讨论今天天气不错呢，哈哈哈哈。',Speaker=811613,}",
  [652335] = "{id=652335,Text='对对，绝对没有做什么暗地里的生意！',Speaker=811611,}",
  [652336] = "{id=652336,Text='你走远点，别偷听我们说话。',Speaker=811612,Option='解释',}",
  [652337] = "{id=652337,Text='寻找锦衣卫？',Speaker=811612,}",
  [652338] = "{id=652338,Text='落日浅滩到处都是锦衣卫， 你去找他们吧。',Speaker=811613,Option='平安',}",
  [652339] = "{id=652339,Text='（小声）是不是那个古怪的锦衣卫？',Speaker=811611,}",
  [652340] = "{id=652340,Text='（小声）你别说话，会被听见的！',Speaker=811612,}",
  [652341] = "{id=652341,Text='黑市商人警戒心很强，问问索杰有什么办法吧。',}",
  [652342] = "{id=652342,Text='他们有消息吗？',Speaker=811494,Option='陈述',}",
  [652343] = "{id=652343,Text='这些黑市商人，就是看你长了副善良的样子。',Speaker=811494,}",
  [652344] = "{id=652344,Text='让我去解决他们！',Speaker=811494,}",
  [652345] = "{id=652345,Text='你们到底看见了什么？听见了什么？',Speaker=811494,}",
  [652346] = "{id=652346,Text='快说出来！',Speaker=811494,}",
  [652347] = "{id=652347,Text='要不然，我的力道可控制不住了！',Speaker=811494,Emoji=5,}",
  [652348] = "{id=652348,Text='我们在落日浅滩的海边，看见一个锦衣卫。',Speaker=811611,}",
  [652349] = "{id=652349,Text='他好像很痛苦的样子，在伤害自己！',Speaker=811611,}",
  [652350] = "{id=652350,Text='还发出了野兽一样的吼叫声！',Speaker=811611,Emoji=24,}",
  [652351] = "{id=652351,Text='对对，其他的我们什么都不知道了。',Speaker=811613,}",
  [652352] = "{id=652352,Text='你、你不要嚣张，我们都很厉害！',Speaker=811612,}",
  [652353] = "{id=652353,Text='我们去海边看看…',Speaker=811494,}",
  [652354] = "{id=652354,Text='找找那个[c][ffff00]发狂的锦衣卫[-][/c]。',Speaker=811494,}",
  [652364] = "{id=652364,Text='平安！',Speaker=811494,}",
  [652365] = "{id=652365,Text='你没事吧？',Speaker=811494,}",
  [652366] = "{id=652366,Text='我没事！刚刚还击败了几个魔物！',Speaker=811371,}",
  [652367] = "{id=652367,Text='我听黑市商人说，有锦衣卫在海滩遇见困难。',Speaker=811494,}",
  [652368] = "{id=652368,Text='又好几天没见到你，所以有些担心。',Speaker=811494,}",
  [652369] = "{id=652369,Text='我这么厉害，当然没事。',Speaker=811371,Option='神秘女人？',}",
  [652370] = "{id=652370,Text='啊！跟踪那个神秘女人的事情，我正要向法海大人复命。',Speaker=811371,}",
  [652371] = "{id=652371,Text='我先回影枫司了！',Speaker=811371,}",
  [652372] = "{id=652372,Text='哎！先别走！',Speaker=811494,}",
  [652373] = "{id=652373,Text='我话都还没说完，这小子就跑了。',Speaker=811494,}",
  [652374] = "{id=652374,Text='索杰跟随平安离去，去影枫司看看平安的情况。',}",
  [652376] = "{id=652376,Text='我跟着白素贞房间里的神秘女人。',Speaker=811371,}",
  [652377] = "{id=652377,Text='发现，她一直在荒境里调查。',Speaker=811371,}",
  [652378] = "{id=652378,Text='我跟着她，看她到处在搜寻着什么。',Speaker=811371,}",
  [652379] = "{id=652379,Text='（皱眉）她在做些什么？',Speaker=811370,}",
  [652380] = "{id=652380,Text='她好像在调查，当年给乌洛下毒的凶手到底是谁。',Speaker=811371,}",
  [652381] = "{id=652381,Text='结果？',Speaker=811370,}",
  [652382] = "{id=652382,Text='不清楚，落日浅滩时空很不稳定，后来出现了很多古怪的玩偶魔物。',Speaker=811371,}",
  [652383] = "{id=652383,Text='不过，我还看见，那个女人打败了那些魔物，保护了洛阳。',Speaker=811371,}",
  [652384] = "{id=652384,Text='我猜测，她不是我们的敌人。',Speaker=811371,}",
  [652385] = "{id=652385,Text='我明白了。',Speaker=811370,}",
  [652386] = "{id=652386,Text='你先回家休息吧，这几天辛苦了。',Speaker=811370,}",
  [652387] = "{id=652387,Text='是！',Speaker=811371,}",
  [652388] = "{id=652388,Text='（思忖）如果白素贞说得是真的，平安的情报也是真实的。',Speaker=811370,}",
  [652389] = "{id=652389,Text='我们有机会能唤醒古恩……',Speaker=811370,}",
  [652390] = "{id=652390,Text='我始终感觉不会顺利。',Speaker=811370,Option='劝慰',}",
  [652391] = "{id=652391,Text='（坚定）但是，有任何能帮助古恩的事情。',Speaker=811370,}",
  [652392] = "{id=652392,Text='我都愿意尝试！',Speaker=811370,}",
  [652393] = "{id=652393,Text='不惜任何代价！',Speaker=811370,}",
  [652394] = "{id=652394,Text='准备去流之云边唤醒古恩。',Speaker=811370,}",
  [652397] = "{id=652397,Text='这是我的朋友，优比。',Speaker=811369,}",
  [652398] = "{id=652398,Text='她是来自神域的女武神，拥有强大的力量。',Speaker=811369,}",
  [652399] = "{id=652399,Text='她可以使用伊米尔之心的碎片，唤醒古恩。',Speaker=811369,}",
  [652400] = "{id=652400,Text='优比小姐，我陪你去古恩身边。',Speaker=811370,}",
  [652401] = "{id=652401,Text='这么不信任我吗？',Speaker=811624,}",
  [652402] = "{id=652402,Text='我只是来执行我的任务，那个叫做平安的锦衣卫，一直跟着我发现我的“阴谋”了吗？',Speaker=811624,}",
  [652403] = "{id=652403,Text='古恩是我的父亲，我不希望有任何闪失。',Speaker=811370,}",
  [652404] = "{id=652404,Text='如你所愿，跟我来吧。',Speaker=811624,}",
  [652405] = "{id=652405,Text='伟大的巨人伊米尔，借用您的力量本源。',Speaker=811624,}",
  [652406] = "{id=652406,Text='父亲',Speaker=811370,}",
  [652407] = "{id=652407,Text='用以召唤龙神古恩的灵魂。',Speaker=811624,}",
  [652408] = "{id=652408,Text='赐予他苏醒的力量！',Speaker=811624,}",
  [652409] = "{id=652409,Text='怎么了？',Speaker=811370,}",
  [652410] = "{id=652410,Text='古恩拒绝了我的力量！',Speaker=811624,}",
  [652411] = "{id=652411,Text='他不愿意苏醒，咳咳。',Speaker=811624,}",
  [652412] = "{id=652412,Text='（虚弱）我…我的心脏……啊！',Speaker=811624,}",
  [652413] = "{id=652413,Text='优比！',Speaker=811369,}",
  [652414] = "{id=652414,Text='请留步，我会护送优比小姐离开……',Speaker=811370,}",
  [652415] = "{id=652415,Text='白素贞，不要轻举妄动！',Speaker=811370,}",
  [652416] = "{id=652416,Text='优比的身体发烫，看上去非常痛苦。',}",
  [652417] = "{id=652417,Text='啊啊！',Speaker=811624,}",
  [652418] = "{id=652418,Text='让我过去，要不然我不客气了！',Speaker=811369,}",
  [652419] = "{id=652419,Text='我只想确认优比的伤势！',Speaker=811369,}",
  [652420] = "{id=652420,Text='你让平安看着我，做什么都可以！',Speaker=811369,}",
  [652421] = "{id=652421,Text='我只想看看我的朋友！',Speaker=811369,}",
  [652422] = "{id=652422,Text='平安，跟着白素贞姑娘，让她过来看看她的朋友。',Speaker=811368,}",
  [652423] = "{id=652423,Text='你没事吧？优比？',Speaker=811369,}",
  [652424] = "{id=652424,Text='我没事。',Speaker=811624,}",
  [652425] = "{id=652425,Text='那我们……',Speaker=811369,}",
  [652426] = "{id=652426,Text='动手！',Speaker=811369,}",
  [652427] = "{id=652427,Text='啊啊！啊……吼吼吼！',Speaker=811371,}",
  [652428] = "{id=652428,Text='白素贞！你在做什么？',Speaker=811368,}",
  [652429] = "{id=652429,Text='许仙城主，别关心白素贞了~',Speaker=811627,}",
  [652430] = "{id=652430,Text='古恩，一千年了……',Speaker=811369,}",
  [652431] = "{id=652431,Text='（凶狠）把你的碎片，给我交出来！',Speaker=811369,}",
  [652432] = "{id=652432,Text='不能，伤害，古恩……',Speaker=811368,}",
  [652433] = "{id=652433,Text='伊米尔之心的碎片？？！',Speaker=811369,}",
  [652434] = "{id=652434,Text='不在古恩身上？在许仙身上？？！',Speaker=811369,}",
  [652435] = "{id=652435,Text='毕尤！拦着他们！',Speaker=811369,}",
  [652436] = "{id=652436,Text='啊！可恶！',Speaker=811627,}",
  [652437] = "{id=652437,Text='啊！啊！啊！',Speaker=811628,}",
  [652438] = "{id=652438,Text='……许仙大人……',Speaker=811628,}",
  [652439] = "{id=652439,Text='啊！',Speaker=811628,}",
  [652440] = "{id=652440,Text='平安的身体看上去很痛苦，似乎想挣脱束缚！',}",
  [652441] = "{id=652441,Text='主、主人……我快控制不住这个龙骸了！',Speaker=811627,}",
  [652442] = "{id=652442,Text='先撤…我们走！',Speaker=811369,}",
  [652443] = "{id=652443,Text='我去追捕她们，你看着许仙！',Speaker=811370,}",
  [652444] = "{id=652444,Text='白素贞带着毕尤和平安逃离了流之云边……',}",
  [652445] = "{id=652445,Text='许仙…',}",
  [652448] = "{id=652448,Text='真是没用，荒境和枫叶彼岸交代你做的事情都没有完成！',Speaker=811369,}",
  [653148] = "{id=653148,Text='好久不见了，芬里尔。',Speaker=811714,}",
  [653178] = "{id=653178,Text='嗷—————！',Speaker=811830,}",
  [653219] = "{id=653219,Text='喂——醒醒——喂——！',Speaker=811829,}",
  [653224] = "{id=653224,Text='你终于回想起来了？',Speaker=811714,}",
  [653225] = "{id=653225,Text='人类可真是脆弱。',Speaker=811714,}",
  [653283] = "{id=653283,Text='啧……诗寇蒂也真是的……',Speaker=811714,}",
  [653284] = "{id=653284,Text='偏偏在这种时候消失了。',Speaker=811714,Option='她怎么了？',}",
  [653285] = "{id=653285,Text='她不见了。',Speaker=811714,}",
  [653286] = "{id=653286,Text='彩虹桥的断裂会导致英灵殿与外界失去联系。',Speaker=811714,}",
  [653287] = "{id=653287,Text='诗寇蒂可能也受到了影响，分身回到了英灵殿之中。',Speaker=811714,Option='{彩虹桥碎片？,0},{奥丁苏醒了？,0}',}",
  [653288] = "{id=653288,Text='唷~后辈！你来啦~~',Speaker=811839,Option='你认识我？',Emoji=7,}",
  [653289] = "{id=653289,Text='当然，[c][ffff00][PlayerName][-][/c]。最近你的表现很活跃，很多人都在关注你哦！',Speaker=811839,Emoji=14,}",
  [653290] = "{id=653290,Text='看上去确实有模有样，不过还需要更多的磨练啊！这样吧——',Speaker=811839,Option='诶？',}",
  [653291] = "{id=653291,Text='就让我把这么多年来的冒险经验传授给你！这样应该会让你少走一些弯路吧！',Speaker=811839,}",
  [653292] = "{id=653292,Text='要不要听听我的冒险经历？[c][ffff00]【任务完成后将自动完成未完成的头饰解锁任务、吟游诗人任务并获得任务奖励。】[-][/c]',Speaker=811839,Option='{好的,3},{下次吧,2}',}",
  [653293] = "{id=653293,Text='那么……就从忽克连的故事开始说起好了……',Speaker=811839,Emoji=11,}",
  [653294] = "{id=653294,Text='（欧德尔将自己的冒险经历，旅途中听到的吟游诗人的诗篇转述给你……）',}",
  [653295] = "{id=653295,Text='（你感觉自己充实了很多……）',}",
  [653296] = "{id=653296,Text='嗯——就讲这么多吧！你应该有不少收获吧！',Speaker=811839,}",
  [653297] = "{id=653297,Text='以后的冒险旅途，要更努力哦！',Speaker=811839,}",
  [653298] = "{id=653298,Text='这附近没有耶梦加得等人的身影，去远处找找吧。',}",
  [653299] = "{id=653299,Text='经历了如此巨大的动荡后，月之湖依旧静谧如初。',}",
  [653300] = "{id=653300,Text='湖面闪烁的粼粼波光，就仿佛刚刚发生的一切都是假象。',}",
  [653301] = "{id=653301,Text='断裂的彩虹桥，苏醒的奥丁……太多的谜题没有解开。',}",
  [653319] = "{id=653319,Text='你们要的未来，是什么模样……？',Speaker=811825,}",
  [653320] = "{id=653320,Text='瑞德，停下。',Speaker=811826,}",
  [653321] = "{id=653321,Text='不要再前进了……不要破坏未来……',Speaker=811826,}",
  [653322] = "{id=653322,Text='诺曼……',Speaker=811714,}",
  [653323] = "{id=653323,Text='诺曼……',Speaker=811714,Option='{耶梦加得！,0},{这是幻象！,0}',}",
  [653324] = "{id=653324,Text='就在这里，和我一起，守护未来……',Speaker=811826,}",
  [653325] = "{id=653325,Text='……',Speaker=811714,Option='耶梦加得！',}",
  [653326] = "{id=653326,Text='不……未来……只有自己……才能创造！',Speaker=811714,}",
  [653327] = "{id=653327,Text='过去的已经过去……我不再是瑞德……',Speaker=811714,}",
  [653328] = "{id=653328,Text='而你，',Speaker=811714,}",
  [653329] = "{id=653329,Text='不是诺曼！',Speaker=811714,}",
  [653330] = "{id=653330,Text='这种东西，也敢变成瑞德的样子，找死！',Speaker=811714,}",
  [653331] = "{id=653331,Text='你很不一样……',Speaker=811825,}",
  [653332] = "{id=653332,Text='不受过去的约束，感知现在的存在……',Speaker=811825,}",
  [653333] = "{id=653333,Text='去吧……带着希望，去往未来……',Speaker=811825,}",
  [653334] = "{id=653334,Text='这种低级的迷幻心神的咒法，你不会以为我中招了吧？',Speaker=811714,}",
  [653335] = "{id=653335,Text='现在要做的事，只有一个。',Speaker=811714,}",
  [653337] = "{id=653337,Text='走吧，前往封印之门。',Speaker=811714,}",
  [653338] = "{id=653338,Text='耶梦加得没有反应。',}",
  [653339] = "{id=653339,Text='白费力气！',Speaker=811826,}",
  [653340] = "{id=653340,Text='不……',Speaker=811714,}",
  [653341] = "{id=653341,Text='未来……只有自己……才能创造！',Speaker=811714,}",
  [653342] = "{id=653342,Text='上前来吧，命运选召的勇士。',Speaker=811857,}",
  [653343] = "{id=653343,Text='向留存于神话和史诗的英魂们祈祷。',Speaker=811858,}",
  [653344] = "{id=653344,Text='接受他们意志的洗礼。',Speaker=811859,}",
  [653345] = "{id=653345,Text='继承他们的力量吧。',Speaker=811860,}",
  [653346] = "{id=653346,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811853,}",
  [653347] = "{id=653347,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811853,}",
  [653348] = "{id=653348,Text='唤灵者一共有两种流派：物理猫通过召唤动物之魂攻击敌人，造成远程物理伤害，生存能力较强。',Speaker=811853,}",
  [653349] = "{id=653349,Text='法猫通过召唤植物之魂攻击敌人，造成魔法伤害，辅助能力较强。',Speaker=811853,}",
  [653350] = "{id=653350,Text='你要选择哪一种流派加点呢？',Speaker=811853,Option='{物理猫,5},{法猫,6}',}",
  [653351] = "{id=653351,Text='好的，我现在就帮你完成加点。',Speaker=811853,}",
  [653352] = "{id=653352,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=811853,}",
  [653353] = "{id=653353,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=811853,}",
  [653354] = "{id=653354,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=811853,Option='{需要,8},{不需要,9}',}",
  [653355] = "{id=653355,Text='我知道了。',Speaker=811853,}",
  [653356] = "{id=653356,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=811853,}",
  [653357] = "{id=653357,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811853,}",
  [653358] = "{id=653358,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811841,}",
  [653359] = "{id=653359,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811841,}",
  [653360] = "{id=653360,Text='符文骑士一共有两种流派：龙息骑兼顾输出与防御，可以使用龙息进行远程魔法攻击。',Speaker=811841,}",
  [653361] = "{id=653361,Text='敏骑以普攻为主要输出手段，善于持续输出，续航能力强。',Speaker=811841,}",
  [653362] = "{id=653362,Text='你要选择哪一种流派加点呢？',Speaker=811841,Option='{龙息骑,5},{敏骑,6}',}",
  [653363] = "{id=653363,Text='好的，我现在就帮你完成加点。',Speaker=811841,}",
