  [653369] = "{id=653369,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811841,}",
  [653370] = "{id=653370,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811840,}",
  [653371] = "{id=653371,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811840,}",
  [653372] = "{id=653372,Text='皇家卫士被誉为“团队之盾”，作为主坦负责承担伤害，同时能够为队友减免伤害，提供庇护。',Speaker=811840,}",
