  [653380] = "{id=653380,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811840,}",
  [653381] = "{id=653381,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811847,}",
  [653382] = "{id=653382,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811847,}",
  [653383] = "{id=653383,Text='大法师是探寻魔法极致之人，使用各种强大的魔法轰击敌人，伤害范围大、爆发高。',Speaker=811847,}",
  [653384] = "{id=653384,Text='你是否已经了解了大法师的战斗方式？',Speaker=811847,Option='是的',}",
