  [653391] = "{id=653391,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811847,}",
  [653392] = "{id=653392,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811848,}",
  [653393] = "{id=653393,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811848,}",
  [653394] = "{id=653394,Text='元素使是全能的施法者，凭借对魔法的理解掌握多样的魔法。兼顾高爆发的魔法输出能力与团队辅助能力。',Speaker=811848,}",
  [653395] = "{id=653395,Text='你是否已经了解了元素使的战斗方式？',Speaker=811848,Option='是的',}",
  [653396] = "{id=653396,Text='好的，我现在就帮你完成加点。',Speaker=811848,}",
