  [653403] = "{id=653403,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811846,}",
  [653404] = "{id=653404,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811846,}",
  [653405] = "{id=653405,Text='十字切割者一共有两种流派：拳刃刺客追求高暴击、高爆发的物理输出。',Speaker=811846,}",
  [653406] = "{id=653406,Text='短剑刺客则更为灵活，擅长使用毒药造成持续伤害。',Speaker=811846,}",
  [653407] = "{id=653407,Text='你要选择哪一种流派加点呢？',Speaker=811846,Option='{拳刃刺客,5},{短刀刺客,6}',}",
  [653408] = "{id=653408,Text='好的，我现在就帮你完成加点。',Speaker=811846,}",
