  [653415] = "{id=653415,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811845,}",
  [653416] = "{id=653416,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811845,}",
  [653417] = "{id=653417,Text='逐影一共有两种流派：弓流擅长远程攻击、设置陷阱，能够在远处袭扰敌方。',Speaker=811845,}",
  [653418] = "{id=653418,Text='刀流则擅长近身作战，通过卸除敌人装备、隐身偷袭等多样的战术干扰敌方。',Speaker=811845,}",
  [653419] = "{id=653419,Text='你要选择哪一种流派加点呢？',Speaker=811845,Option='{弓流,5},{刀流,6}',}",
  [653420] = "{id=653420,Text='好的，我现在就帮你完成加点。',Speaker=811845,}",
