  [653426] = "{id=653426,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811845,}",
  [653427] = "{id=653427,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811844,}",
  [653428] = "{id=653428,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811844,}",
  [653429] = "{id=653429,Text='游侠一共有两种流派：ADL以普攻作为主要输出手段，射程远，持续输出能力强。',Speaker=811844,}",
