  [653439] = "{id=653439,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811843,}",
  [653440] = "{id=653440,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811843,}",
  [653441] = "{id=653441,Text='宫廷乐师同时具备辅助能力与输出能力，除了能够使用独奏技能辅助队友外，还能与舞娘合奏发挥更强大的团队功能。',Speaker=811843,}",
  [653442] = "{id=653442,Text='你是否已经了解了宫廷乐师的职业定位？',Speaker=811843,Option='是的',}",
  [653443] = "{id=653443,Text='好的，我现在就帮你完成加点。',Speaker=811843,}",
  [653444] = "{id=653444,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=811843,}",
  [653445] = "{id=653445,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=811843,}",
  [653446] = "{id=653446,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=811843,Option='{需要,8},{不需要,9}',}",
  [653447] = "{id=653447,Text='我知道了。',Speaker=811843,}",
  [653448] = "{id=653448,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=811843,}",
  [653449] = "{id=653449,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811843,}",
  [653450] = "{id=653450,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811842,}",
  [653451] = "{id=653451,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811842,}",
  [653452] = "{id=653452,Text='漫游舞者兼具辅助能力与输出能力，除了能够使用独奏技能辅助队友外，还能与诗人合奏发挥更强大的团队功能。',Speaker=811842,}",
  [653453] = "{id=653453,Text='你是否已经了解了漫游舞者的职业定位？',Speaker=811842,Option='是的',}",
  [653454] = "{id=653454,Text='好的，我现在就帮你完成加点。',Speaker=811842,}",
  [653455] = "{id=653455,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=811842,}",
  [653456] = "{id=653456,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=811842,}",
