  [653458] = "{id=653458,Text='我知道了。',Speaker=811842,}",
  [653459] = "{id=653459,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=811842,}",
  [653460] = "{id=653460,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811842,}",
  [653461] = "{id=653461,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811851,}",
  [653462] = "{id=653462,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811851,}",
  [653463] = "{id=653463,Text='大主教一共有两种流派：赞美牧是团队最坚实的后盾，最主要的治疗提供者，拥有超强的辅助与治疗能力。',Speaker=811851,}",
  [653464] = "{id=653464,Text='暴牧则牺牲了一部分治疗、辅助能力，换取了更强的输出能力。',Speaker=811851,}",
  [653465] = "{id=653465,Text='你要选择哪一种流派加点呢？',Speaker=811851,Option='{赞美牧,5},{暴牧,6}',}",
  [653466] = "{id=653466,Text='好的，我现在就帮你完成加点。',Speaker=811851,}",
