  [653470] = "{id=653470,Text='我知道了。',Speaker=811851,}",
  [653471] = "{id=653471,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=811851,}",
  [653472] = "{id=653472,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811851,}",
