  [653485] = "{id=653485,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811849,}",
  [653486] = "{id=653486,Text='机匠通过驾驶魔导机械进行作战，不但帅气还拥有很强的持续输出能力。机匠还能够修理被技能破坏的装备。',Speaker=811849,}",
  [653487] = "{id=653487,Text='你是否已经了解了机匠的战斗方式？',Speaker=811849,Option='是的',}",
