  [653495] = "{id=653495,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811850,}",
  [653496] = "{id=653496,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811850,}",
  [653497] = "{id=653497,Text='基因学者的战斗方式多样，可以召唤生命体助战、投掷各种药剂瓶，还能破坏敌人的装备。',Speaker=811850,}",
  [653498] = "{id=653498,Text='你是否已经了解了基因学者的战斗方式？',Speaker=811850,Option='是的',}",
  [653499] = "{id=653499,Text='好的，我现在就帮你完成加点。',Speaker=811850,}",
