  [653505] = "{id=653505,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811850,}",
  [653506] = "{id=653506,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=811854,}",
  [653507] = "{id=653507,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=811854,}",
  [653508] = "{id=653508,Text='超级初心者是自由度很高的职业，可以使用其他职业群的技能，机动性强、施法距离远、生存能力也很强。',Speaker=811854,}",
  [653509] = "{id=653509,Text='你是否已经了解了超级初心者的战斗方式？',Speaker=811854,Option='是的',}",
  [653510] = "{id=653510,Text='好的，我现在就帮你完成加点。',Speaker=811854,}",
  [653511] = "{id=653511,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=811854,}",
  [653512] = "{id=653512,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=811854,}",
  [653513] = "{id=653513,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=811854,Option='{需要,8},{不需要,9}',}",
  [653514] = "{id=653514,Text='我知道了。',Speaker=811854,}",
  [653515] = "{id=653515,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=811854,}",
  [653516] = "{id=653516,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=811854,}",
  [653517] = "{id=653517,Text='一口气传承到太多力量，你是不是感到有些混乱呢？',Speaker=816567,}",
  [653518] = "{id=653518,Text='我现在就帮你梳理力量、[c][ffff00]添加技能点[-][/c]。',Speaker=816567,}",
  [653519] = "{id=653519,Text='忍者一共有三种流派：刀忍擅长近战物理攻击，依靠连击与暴击造成高爆发伤害。',Speaker=816567,}",
  [653520] = "{id=653520,Text='镖忍擅长远程物理伤害，使用风魔手里剑作为武器，持续伤害能力较强。',Speaker=816567,}",
  [653521] = "{id=653521,Text='法忍精通忍术与通灵术，是攻击方式更为多样的法术输出者。',Speaker=816567,}",
  [653522] = "{id=653522,Text='你要选择哪一种流派加点呢？',Speaker=816567,Option='{刀忍,5},{镖忍,6},{法忍,7}',}",
  [653523] = "{id=653523,Text='好的，我现在就帮你完成加点。',Speaker=816567,}",
  [653524] = "{id=653524,Text='接下来你会面临一场艰难又危险的战斗。',Speaker=816567,}",
  [653525] = "{id=653525,Text='因为这是你初次应对强敌，我们想为你提供战斗提示。你是否需要呢？',Speaker=816567,}",
  [653526] = "{id=653526,Text='[c][ffff00]【选择“需要”将开启3转职业教学辅助战斗，推荐新人采用。】[-][/c]',Speaker=816567,Option='{需要,8},{不需要,9}',}",
  [653527] = "{id=653527,Text='我知道了。',Speaker=816567,}",
  [653528] = "{id=653528,Text='这些装备和道具你收下，务必在战斗中好好利用他们。',Speaker=816567,}",
  [653529] = "{id=653529,Text='做好准备的话，就告知我一声，我会将你传送到恶魔的老巢去。',Speaker=816567,}",
  [653543] = "{id=653543,Text='小猫咪~很高兴可以在这里见到你喵。',Speaker=811853,}",
  [653577] = "{id=653577,Voice='Npc/Sigrdrifa_01',Text='入学的新生们，请到我这里来！',Speaker=811888,}",
  [653578] = "{id=653578,Text='咦，你怎么还站在这里呀？是不是被学院的风景震撼到啦？',Speaker=811887,Action={actionid=34},}",
  [653579] = "{id=653579,Text='大家都向接引人报道过了，你也快去吧~',Speaker=811887,}",
  [653580] = "{id=653580,Text='欢迎来到王立克里图拉学院，被命运选召的勇者。',Speaker=811888,ModelFace=6,ModelAct=867,Emoji=17,}",
  [653581] = "{id=653581,Text='我是你的接引人希格德莉法，你可以叫我莉法。',Speaker=811888,Option='被选召的勇士？',ModelFace=6,ModelAct=868,}",
  [653582] = "{id=653582,Text='哦？原来你不知道吗？',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653583] = "{id=653583,Text='你的身体里有着「命运的加护」，它能使你具备与众不同的潜质。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653584] = "{id=653584,Text='看——',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653585] = "{id=653585,Text='这三只金鸟是命运女神的使者，它围绕着你飞翔，正是你被命运选召的证明。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653586] = "{id=653586,Text='你将获得常人没有的能力，也背负着旁人无法想象的使命。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653587] = "{id=653587,Text='不太明白也没关系。我会引导你在这所学院中找到答案的。',Speaker=811888,ModelFace=6,ModelAct=867,Emoji=30,}",
  [653588] = "{id=653588,Text='但在这之前，先让我给你简单介绍一下学院吧~',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653589] = "{id=653589,Text='王立克里图拉学院原本是仅向卢恩贵族开放的皇家勇者学院，后来经过第29任校长居伊·克里图拉的改革，才发展成如今面向整片大陆的冒险者学院。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653590] = "{id=653590,Text='在这里，你不仅能习得丰富的冒险知识，还能选择自己心仪的职业。学院还专门设有勇者试练塔，供新生挑战自我。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653591] = "{id=653591,Text='学院也很重视学生们的文化娱乐生活。圣咏礼堂会不定期安排小型音乐会或戏剧表演，盛大的校庆汇演就在这里举行。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653592] = "{id=653592,Text='现在，你对学院应该有所了解啦。我们就开始下一个步骤吧！',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653593] = "{id=653593,Text='对每一位没有冒险经验的新人来说，新手特训都是重要的入学课程。',Speaker=811888,ModelFace=4,ModelAct=868,Emoji=5,Action={actionid=868},}",
  [653594] = "{id=653594,Text='它能教会你最为基础的冒险技巧。',Speaker=811888,ModelFace=4,ModelAct=867,}",
  [653595] = "{id=653595,Text='赶快装备上这把武器，快去找阿历克塞教官报道吧。',Speaker=811888,ModelFace=4,ModelAct=867,Action={actionid=32},}",
  [653596] = "{id=653596,Text='[c][ffff00]【以下任务为基础战斗教学，任务过程中玩家可再次与希格德莉法对话，跳过教学步骤。】[-][/c]',Speaker=811888,Option='{好的,3},{我不想特训,2}',ModelFace=4,ModelAct=867,}",
  [653597] = "{id=653597,Text='阿历克塞在学院野外的新手训练场上，从学院西门出去，你就能看到他了。',Speaker=811888,ModelFace=4,ModelAct=867,}",
  [653598] = "{id=653598,Text='唔，好吧。作为被命运选召的勇者，应当不会被简单的战斗难倒。',Speaker=811888,ModelFace=4,ModelAct=867,}",
  [653599] = "{id=653599,Text='嚯！小新人，你也来参加训练吗？',Speaker=811892,Option='解释',ModelFace=6,ModelAct=868,}",
  [653600] = "{id=653600,Text='希格德莉法让你来的……原来你就是那位特殊的新生啊。',Speaker=811892,ModelFace=6,ModelAct=867,Emoji=11,}",
  [653601] = "{id=653601,Text='唔……瞧这紧实的肌肉、敏锐的目光，真让人有狠、狠、操、练的欲望啊！',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653602] = "{id=653602,Text='哈哈，别害怕啊。毕竟在下不是魔鬼，不过说说而已！',Speaker=811892,ModelFace=6,ModelAct=867,Emoji=17,Action={actionid=868},}",
  [653603] = "{id=653603,Text='基础招式的运用还是很简单的，你直接在实战中体悟技巧就好。',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653604] = "{id=653604,Text='必要时刻，我会从旁指导你的。',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653605] = "{id=653605,Text='不错，掌握得很快。',Speaker=811892,ModelFace=6,ModelAct=867,Action={actionid=27},}",
  [653606] = "{id=653606,Text='在刚才的战斗中，你一定收获了不少经验吧。',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653607] = "{id=653607,Text='接下来我将教你分配素质点，进一步提高你的战斗力。',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653608] = "{id=653608,Text='不愧是被命运选召的勇士，果然学什么都很快啊！',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653609] = "{id=653609,Text='我这里已经没有什么可指点你的了，请前往魔药园接受伊莱·雪耳博士的教学吧。',Speaker=811892,ModelFace=6,ModelAct=867,}",
  [653610] = "{id=653610,Text='请问……伊莱·雪耳博士在吗？',}",
  [653611] = "{id=653611,Text='喵~呜~',Speaker=811889,Action={actionid=31},}",
  [653612] = "{id=653612,Text='我就是伊莱·雪耳，有什么事吗？',Speaker=811889,}",
  [653613] = "{id=653613,Text='会、会说话的猫咪！',}",
  [653614] = "{id=653614,Text='不对哦~我是能够沟通自然的多兰族啦喵，和普通猫咪可不一样呢！',Speaker=811889,ModelFace=1,ModelAct=867,Emoji=7,Action={actionid=868},}",
  [653615] = "{id=653615,Text='你是来接受训练吧？',Speaker=811889,Option='是的',ModelFace=1,ModelAct=867,}",
  [653616] = "{id=653616,Text='阿历克塞传授你正面战斗的技巧，而我则要教授你辨识草药和采集的方法。',Speaker=811889,ModelFace=1,ModelAct=867,Emoji=25,}",
  [653617] = "{id=653617,Text='请从魔药田里采集两株薄荷草吧，注意它们会和辛辣草混合在一起生长，不要认错喵~',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653618] = "{id=653618,Text='请问……伊莱·雪耳博士在吗？',}",
  [653619] = "{id=653619,Text='喵~呜~我就是伊莱·雪耳！',Speaker=811889,Emoji=17,Action={actionid=869},}",
  [653620] = "{id=653620,Text='能在这里遇到多兰族同族，真是一件幸事呀！',Speaker=811889,Emoji=17,}",
  [653621] = "{id=653621,Text='[c][ffff00][PlayerName][-][/c]吗？真是个好名字呢喵。',Speaker=811889,}",
  [653622] = "{id=653622,Text='寒暄就到这里，我们继续特训吧。',Speaker=811889,}",
  [653623] = "{id=653623,Text='阿历克塞传授你正面战斗的技巧，而我则要教授你辨识草药和采集的方法。',Speaker=811889,}",
  [653624] = "{id=653624,Text='请从魔药田里采集两株薄荷草吧，注意它们会和辛辣草混合在一起生长，不要认错喵~',Speaker=811889,}",
  [653625] = "{id=653625,Text='地面有一顶无主的帽子，是谁遗失了它吗？',}",
  [653626] = "{id=653626,Text='你！动！帽子！哔啵！',Speaker=811903,Emoji=12,}",
  [653627] = "{id=653627,Text='欸！！！为什么突然就开始攻击我了啊！？',}",
  [653628] = "{id=653628,Text='小笨蛋，快停手，别再激怒它们了喵！',Speaker=811889,ModelFace=1,ModelAct=867,Action={actionid=868},}",
  [653629] = "{id=653629,Text='快使用装死躺到地上，直到我喊你再站起来。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653630] = "{id=653630,Text='尊敬的曼陀罗博士们，请听我一言：喵喵呜呜咪~',Speaker=811889,ModelFace=1,ModelAct=867,Action={actionid=87},}",
  [653631] = "{id=653631,Text='哔啵哔哔啵？',Speaker=811903,Emoji=19,}",
  [653632] = "{id=653632,Text='嗷呜嗷呜？',Speaker=811889,ModelFace=1,ModelAct=867,Emoji=8,Action={actionid=35},}",
  [653633] = "{id=653633,Text='哔啵！',Speaker=811903,Emoji=2,}",
  [653634] = "{id=653634,Text='没事了，[c][ffff00][PlayerName][-][/c]。你可以起来了喵。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653635] = "{id=653635,Text='真是个冒失的小家伙呀，竟然触动了学院曼陀罗的逆鳞。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653636] = "{id=653636,Text='学院帽是它们最宝贝的东西，任何擅动的人都会受到冷酷的攻击。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653637] = "{id=653637,Text='幸好我和它们有些交情，才能让你免于无穷无尽的追杀。',Speaker=811889,Option='这么恐怖嘛！',ModelFace=1,ModelAct=867,}",
  [653638] = "{id=653638,Text='当然啦，英雄的冒险之旅不止荣誉，还充斥着各种危险呢。',Speaker=811889,ModelFace=1,ModelAct=867,Emoji=30,Action={actionid=88},}",
  [653639] = "{id=653639,Text='这些素材就送给你压惊咯喵，以后你可得小心一些哦~',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653640] = "{id=653640,Text='你的新手特训已经结束了，向希格德莉法领取下一步指引吧。',Speaker=811889,ModelFace=1,ModelAct=867,}",
  [653664] = "{id=653664,Text='你回来啦！特训的过程还顺利吗？',Speaker=811888,Option='{很简单,3},{很刺激,4}',ModelFace=1,ModelAct=867,Emoji=7,}",
  [653665] = "{id=653665,Text='我就知道，作为被选中的勇士，你肯定能够轻松过关。',Speaker=811888,ModelFace=1,ModelAct=867,Emoji=20,}",
  [653666] = "{id=653666,Text='哦~居然惹到了曼陀罗博士啊。',Speaker=811888,ModelFace=1,ModelAct=867,Emoji=1,}",
  [653667] = "{id=653667,Text='还没毕业就经历了如此惊险的事件，不愧是被命运选中的勇者！',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653668] = "{id=653668,Text='在开始下一个阶段的引导前，我还有件小任务需要你完成。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653669] = "{id=653669,Text='那就是——制作个性头饰。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653670] = "{id=653670,Text='对每位实力与颜值并存的冒险者来说，头饰都是不可或缺的东西。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653671] = "{id=653671,Text='两位志愿者已经迫不及待地想为你推荐样式了，快来见见他们吧。',Speaker=811888,ModelFace=4,ModelAct=868,Action={actionid=868},}",
  [653672] = "{id=653672,Text='英俊潇洒的维托。',Speaker=811910,}",
  [653673] = "{id=653673,Text='人见人爱的希达。',Speaker=811911,}",
  [653674] = "{id=653674,Text='为你献上入学的礼物。',Speaker=811910,}",
  [653675] = "{id=653675,Text='为你献上入学的礼物。',Speaker=811911,}",
  [653676] = "{id=653676,Text='我头顶上的蛋壳帽是用大嘴鸟的蛋壳做的，坚实耐用。',Speaker=811910,}",
  [653677] = "{id=653677,Text='戴上它，你就会拥有整座学院最“铁”的头。',Speaker=811910,}",
  [653678] = "{id=653678,Text='选我选我。你看我的波利帽如此粉嫩Q弹、多可爱呀。',Speaker=811911,}",
  [653679] = "{id=653679,Text='戴上它的人都会受到波利的祝福哦~',Speaker=811911,}",
  [653680] = "{id=653680,Text='[c][ffff00][PlayerName][-][/c]，你更喜欢哪一种头饰呢？',Speaker=811888,Option='{新手蛋壳帽 ,7},{粉嫩的波利,8},{我再想想,6}',ModelFace=1,ModelAct=867,}",
  [653681] = "{id=653681,Text='哈，和我一样有眼光！',Speaker=811910,Action={actionid=39},}",
  [653682] = "{id=653682,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=811910,}",
  [653683] = "{id=653683,Text='我就知道你会选我的！粉嫩波利万岁！',Speaker=811911,Action={actionid=39},}",
  [653684] = "{id=653684,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=811911,}",
  [653685] = "{id=653685,Text='好看，很适合你呢！',Speaker=811910,Emoji=20,}",
  [653686] = "{id=653686,Text='高光时刻，不如拍一张照片作为入学纪念吧。',Speaker=811911,Emoji=39,}",
  [653687] = "{id=653687,Text='在开始下一个阶段的引导前，我还有件小任务需要你完成。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653688] = "{id=653688,Text='那就是——制作个性头饰。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653689] = "{id=653689,Text='对每位实力与颜值并存的冒险者来说，头饰都是不可或缺的东西。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653690] = "{id=653690,Text='两位志愿者已经迫不及待地想为你推荐样式了，快来见见他们吧。',Speaker=811888,ModelFace=1,ModelAct=867,}",
  [653691] = "{id=653691,Text='英俊潇洒的维托。',Speaker=811910,}",
  [653692] = "{id=653692,Text='人见人爱的希达。',Speaker=811911,}",
  [653693] = "{id=653693,Text='为你献上入学的礼物。',Speaker=811910,}",
  [653694] = "{id=653694,Text='为你献上入学的礼物。',Speaker=811913,}",
  [653695] = "{id=653695,Text='我头顶上的蛋壳帽是用大嘴鸟的蛋壳做的，坚实耐用。',Speaker=811910,}",
  [653696] = "{id=653696,Text='戴上它，你就会拥有整座学院最“铁”的头。',Speaker=811910,}",
  [653697] = "{id=653697,Text='选我选我。你看我的波利帽如此粉嫩Q弹、多可爱呀。',Speaker=811911,}",
  [653698] = "{id=653698,Text='戴上它的人都会受到波利的祝福哦~',Speaker=811911,}",
  [653699] = "{id=653699,Text='[c][ffff00][PlayerName][-][/c]，你更喜欢哪一种头饰呢？',Speaker=811888,Option='{新手蛋壳帽 ,0},{粉嫩的波利,0}',ModelFace=1,ModelAct=867,}",
  [653700] = "{id=653700,Text='哈，和我一样有眼光！',Speaker=811910,ModelFace=1,ModelAct=867,}",
  [653701] = "{id=653701,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=811910,ModelFace=1,ModelAct=867,}",
  [653702] = "{id=653702,Text='我就知道你会选我的！粉嫩波利万岁！',Speaker=811911,ModelFace=1,ModelAct=867,}",
  [653703] = "{id=653703,Text='把这份图纸和所需的素材一起交给微笑小姐，就可以制作并获得头饰了。',Speaker=811911,ModelFace=1,ModelAct=867,}",
  [653704] = "{id=653704,Text='欢迎你，亲爱的冒险者。请问你有什么需求呢？',Speaker=811912,ModelFace=1,ModelAct=0,}",
  [653705] = "{id=653705,Text='好看，很适合你呢！',Speaker=811910,ModelFace=1,ModelAct=867,Emoji=20,}",
  [653706] = "{id=653706,Text='高光时刻，不如拍一张照片作为入学纪念吧。',Speaker=811911,ModelFace=1,ModelAct=867,Emoji=39,}",
  [653707] = "{id=653707,Text='是男人就戴蛋壳帽。',Speaker=811910,ModelFace=1,ModelAct=867,}",
  [653708] = "{id=653708,Text='软软的波利是世界上最可爱的生物！',Speaker=811911,ModelFace=1,ModelAct=867,}",
  [653709] = "{id=653709,Text='欢迎你，亲爱的冒险者。请问你有什么需求呢？',Speaker=811912,ModelFace=1,ModelAct=0,}",
  [653714] = "{id=653714,Text='接下来，你要前往初心殿堂选择冒险职业。至于具体过程……请允许我留作惊喜保密。',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653715] = "{id=653715,Text='毕竟有人已经在那里等你很久啦！更多的疑惑就留给TA来解答吧~',Speaker=811888,ModelFace=6,ModelAct=867,}",
  [653716] = "{id=653716,Text='咕咕，回神啦回神啦，傻乎乎的冒险者！',Speaker=811914,ModelFace=1,ModelAct=8,Emoji=5,BlackMask=1,Action={actionid=202},}",
  [653717] = "{id=653717,Text='重新自我介绍一下：我是克里图拉的学院精灵，奥尔加·古埃·咕，负责指导初心者们选择自己的冒险职业。',Speaker=811914,ModelFace=1,ModelAct=8,BlackMask=1,}",
  [653718] = "{id=653718,Text='我手里的这份卷轴，是由普隆德拉冒险者协会与吉芬魔法塔联合出品的魔法问卷。',Speaker=811914,ModelFace=1,ModelAct=8,BlackMask=1,Action={actionid=202},}",
  [653719] = "{id=653719,Text='用心做完之后，你就能了解自己最适合什么职业啦。快来试试看吧~',Speaker=811914,Option='{好,4},{再等一会儿,3}',ModelFace=1,ModelAct=8,BlackMask=1,}",
  [653720] = "{id=653720,Text='好吧。反正我已经等你那么久啦，也不多这么一会儿咕。',Speaker=811914,ModelFace=1,ModelAct=8,BlackMask=1,Action={actionid=204},}",
  [653721] = "{id=653721,Text='咕咕，那我们就开始咯~',Speaker=811915,ModelFace=1,ModelAct=8,BlackMask=1,}",
  [653722] = "{id=653722,Text='咕咕……你居然是这么想的吗？',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653723] = "{id=653723,Text='让我康康你选了什么~',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653724] = "{id=653724,Text='哦~你选了这一个选项啊。',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653725] = "{id=653725,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的符文骑士的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653726] = "{id=653726,Text='不过凡事还得一步一步来。想成为符文骑士，首先要转职成剑士。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653727] = "{id=653727,Text='你去寻找符文骑士的导师：龙炎魔剑达尔克吧，他会带你去传承之间、接受女武神的指引哒！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653728] = "{id=653728,Text='还有还有，如果你想选择其他职业也没有问题。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=213},}",
  [653729] = "{id=653729,Text='学院鼓励每一位冒险者自由发展，只要和对应的职业导师沟通，同样可以进行转职哦。',Speaker=811915,Option='知道了',ModelFace=1,ModelAct=8,}",
  [653730] = "{id=653730,Text='去吧去吧，进阶成为职业的冒险家吧 ！',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=82},}",
  [653731] = "{id=653731,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的皇家卫士的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653732] = "{id=653732,Text='不过凡事还得一步一步来。想成为皇家卫士，首先要转职成十字军。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653733] = "{id=653733,Text='你去寻找皇家卫士的导师：坚毅之盾法拉昂吧，他会带你去传承之间、接受女武神的指引哒！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653734] = "{id=653734,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的漫游舞者的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653735] = "{id=653735,Text='不过凡事还得一步一步来。想成为漫游舞者，首先要转职成舞娘。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653736] = "{id=653736,Text='你去寻找漫游舞者的导师：月华蝴蝶奥拉尼娅吧，她会带你去传承之间、接受女武神的指引哒！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653737] = "{id=653737,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的宫廷乐师的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653738] = "{id=653738,Text='不过凡事还得一步一步来。想成为宫廷乐师，首先要转职成诗人。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653739] = "{id=653739,Text='你去寻找宫廷乐师的导师：史诗唱述者奥尔修斯吧，他会带你去传承之间、接受女武神的指引哒！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653740] = "{id=653740,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的游侠的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653741] = "{id=653741,Text='不过凡事还得一步一步来。想成为游侠，首先要转职成猎人。',Speaker=811915,ModelFace=1,ModelAct=8,Action={actionid=202},}",
  [653742] = "{id=653742,Text='你去寻找游侠的导师：星之旅人特兰斯凯吧，他会带你去传承之间、接受女武神的指引哒！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [653743] = "{id=653743,Text='咕咕咕咕，原来你适合这个职业啊。拥有「命运的加护」的你，一定可以成为了不起的逐影的！',Speaker=811915,ModelFace=1,ModelAct=8,}",
  [662778] = "{id=662778,Text='头饰，我都愿意给你… 不过得拿乐园币来换哦！',Speaker=829352,}",
  [662779] = "{id=662779,Text='头饰，我都愿意给你… 不过得拿乐园币来换哦！',Speaker=829353,}",
  [662780] = "{id=662780,Text='头饰，我都愿意给你… 不过得拿乐园币来换哦！',Speaker=829354,}",
  [662781] = "{id=662781,Text='移动',}",
  [662782] = "{id=662782,Text='立典拉德：（痛苦呻吟）呃……',}",
  [662783] = "{id=662783,Text='【背景音】海因利斯：立典拉德！',}",
  [662784] = "{id=662784,Text='【背景音】海因利斯：立典拉德！\n立典拉德：……求你……代替我！',}",
  [662785] = "{id=662785,Text='维西：……抱歉',}",
  [662786] = "{id=662786,Text='【背景音】伦司：维西！！！',}",
  [662787] = "{id=662787,Text='巴特蒙德：命运的轨迹无法改变吗……',}",
  [662788] = "{id=662788,Text='施密特：老师！',}",
  [662789] = "{id=662789,Text='施密特：我就知道你一定会来帮我！',}",
  [662790] = "{id=662790,Text='施密特：（惊愕）老师……？',}",
  [662791] = "{id=662791,Text='施密特：为、为什么……',}",
  [662792] = "{id=662792,Text='巴特蒙德：抱歉，但这是通往未来的唯一方式……',}",
  [662793] = "{id=662793,Text='【背景音】\n斯特汀：巴特蒙德，你在干什么!\n海因里希：施密特！\n沙利:施密特哥哥……\n立典拉德：陛下！',}",
  [662794] = "{id=662794,Text='【背景音】希默梅斯：啊哈哈哈，哈哈哈哈哈~!\n',}",
  [662795] = "{id=662795,Text='维西与立典拉德为了帝国牺牲，国王陛下生死未卜，希默梅斯应该仍在门的背后。',Speaker=829378,}",
  [662796] = "{id=662796,Text='门开了，但一切又回到了原点，这就是……未来？该死的未来！',Speaker=829378,Option='{巴特蒙德……,0},{到底怎么回事？,0}',}",
  [662797] = "{id=662797,Text='还不知道大贤者的目的，被贵族收买？与黑暗军团勾结？但我不认为他会这么做。',Speaker=829378,}",
  [662798] = "{id=662798,Text='冒险者你还记得吗？巴特蒙德的研究室中时空咒符遭窃，但却没有任何入侵的痕迹。',Speaker=829378,}",
  [662799] = "{id=662799,Text='有一种可能我们一直没有去猜测……如今巴特蒙德出现在了克雷斯特汉姆……',Speaker=829378,Option='是他拿走了咒符！',}",
  [662800] = "{id=662800,Text='没错，现在我可以确信，阅兵仪式上将施密特送去亚空间的人，正是巴特蒙德！',Speaker=829378,Option='{真没想到……,0},{这太荒谬了,0}',}",
  [662801] = "{id=662801,Text='他真正的目的我们不得而知……眼下我们能做的就是继续追查。',Speaker=829378,}",
  [662802] = "{id=662802,Text='荣誉骑士，请你帮我看看陛下的情况。',Speaker=829378,Option='为什么不自己看看？',}",
  [662803] = "{id=662803,Text='或许是我太过胆怯，甚至不敢靠近……',Speaker=829378,}",
  [662804] = "{id=662804,Text='（发出痛苦呻吟）呃……老师……',Speaker=829380,}",
  [662805] = "{id=662805,Text='呜呜，施密特哥哥，你要快点好起来……',Speaker=829386,Option='施密特怎么样了？ ',}",
  [662806] = "{id=662806,Text='好在那一刀并没有捅入致命部位，施密特哥哥的情况已经在好转了。',Speaker=829386,}",
  [662807] = "{id=662807,Text='呜呜，可我不明白，大贤者为什么会做出这种事？他肯定不是本人！是希默梅斯的傀儡！',Speaker=829386,}",
  [662808] = "{id=662808,Text='不……那是老师的气息……嘶……我不会认错……',Speaker=829380,Option='{难以相信,0},{竟然真的是他,0}',}",
  [662809] = "{id=662809,Text='快别说话了，虽然脱离了危险，但你的身体还是很虚弱。',Speaker=829386,}",
  [662810] = "{id=662810,Text='我相信老师，他这么做一定有原因，他绝不会倒向黑暗……咳咳……',Speaker=829380,}",
  [662811] = "{id=662811,Text='别说话了，施密特哥哥，现在的你最需要的是好好休息！',Speaker=829386,}",
  [662812] = "{id=662812,Text='老师……',Speaker=829380,}",
  [662813] = "{id=662813,Text='眼泪，快缩回去！',Speaker=829386,}",
  [662814] = "{id=662814,Text='陛下的情况如何了？',Speaker=829378,Option='{脱离危险,0},{在好转中,0}',}",
  [662815] = "{id=662815,Text='（凝视着施密特方向）那就好……陛下的安危胜过其余万千。',Speaker=829378,}",
  [662816] = "{id=662816,Text='好了，我们来说说眼下的情况。',Speaker=829378,}",
  [662817] = "{id=662817,Text='王座之门的背后古代文明尤佩雷斯的遗迹，那里一直以来由卡利斯格骑士团负责守卫。',Speaker=829378,Option='卡利斯格？',}",
  [662818] = "{id=662818,Text='但自从在白骑士团驻地我收到她们中断的讯息后，我一直尝试用通讯器联系她们，但一直没有得到回音。',Speaker=829378,}",
  [662819] = "{id=662819,Text='不能再坐以待毙了。走吧，我们亲自前往秘密花园中的卡利斯格骑士团驻地，看看到底发生了什么。',Speaker=829378,Option='{秘密花园？,0},{终于要去门后了……,0}',}",
  [662820] = "{id=662820,Text='卡利斯格骑士团是由蔷薇骑士卡利斯格创立的。',Speaker=829378,}",
  [662821] = "{id=662821,Text='这是一个全员为女骑士组成的骑士团。',Speaker=829378,}",
  [662822] = "{id=662822,Text='但她们的实力不输于白骑士团。',Speaker=829378,}",
  [662823] = "{id=662823,Text='这里已经完全失陷了吗？',Speaker=829378,}",
  [662824] = "{id=662824,Text='继续前进吧……去她们的驻地看看……',Speaker=829378,}",
  [662825] = "{id=662825,Text='到底发生了什么？先把这里的魔物清理干净吧。',Speaker=829378,}",
  [662826] = "{id=662826,Text='是谁？',Speaker=829378,}",
  [662827] = "{id=662827,Text='……幸存者还是？',Speaker=829378,}",
  [662828] = "{id=662828,Text='跟上，但保持警戒。',Speaker=829378,}",
  [662829] = "{id=662829,Text='这朵花似乎要把我们带去什么地方？',Speaker=829378,}",
  [662830] = "{id=662830,Text='先清理这些碍事的魔物吧。',Speaker=829378,}",
  [662831] = "{id=662831,Text='来了来了！',Speaker=829389,}",
  [662832] = "{id=662832,Text='哎呀呀~',Speaker=829389,}",
  [662833] = "{id=662833,Text='冷静点！',Speaker=829389,}",
  [662834] = "{id=662834,Text='好挤呀~',Speaker=829389,}",
  [662835] = "{id=662835,Text='你们好呀，我们是——西尔芙！',Speaker=829389,}",
  [662836] = "{id=662836,Text='西尔芙！！！',Speaker=829389,}",
  [662837] = "{id=662837,Text='感谢你们帮助我们清理了这些可怕的家伙~~',Speaker=829389,}",
  [662838] = "{id=662838,Text='你们一直在这里吗？那你们是否知道卡利斯格骑士团发生了什么？',Speaker=829378,}",
  [662839] = "{id=662839,Text='真相就在遗迹里，我们会指引命定之人通往既定的方向！',Speaker=829389,}",
  [662840] = "{id=662840,Text='嗯~没错！你们是带领克雷斯特汉姆走向命定之路的人。',Speaker=829389,}",
  [662841] = "{id=662841,Text='我知道了，冒险者，我们先去将这些汇报给陛下吧。',Speaker=829378,}",
  [662842] = "{id=662842,Text='我们会在这里等着你们！~',Speaker=829389,}",
  [662843] = "{id=662843,Text='再见~~~',Speaker=829389,}",
  [662844] = "{id=662844,Text='你们回来了，情况怎么样？',Speaker=829380,}",
  [662845] = "{id=662845,Text='所以卡利斯格骑士团的骑士们都被感染了……驻地也被魔物占领……',Speaker=829380,}",
  [662846] = "{id=662846,Text='陛下……请节哀……已经到了这个地步，激动的情绪只会影响你的身体。',Speaker=829378,}",
  [662847] = "{id=662847,Text='……我只是没有想到，这一切会来的这么突然……',Speaker=829380,}",
  [662848] = "{id=662848,Text='陛下，我们在城内发现了新的诅咒光球，情况危急……',Speaker=829391,}",
  [662849] = "{id=662849,Text='传令，所有骑士团长组织骑士搜救幸存者，将所有民众安置在安全区。',Speaker=829380,}",
  [662850] = "{id=662850,Text='是！',}",
  [662851] = "{id=662851,Text='医疗队对感染的民众进行救治，延缓异变情况。',Speaker=829380,}",
  [662852] = "{id=662852,Text='施密特，你还没有完全恢复，先休息一会吧……',Speaker=829378,}",
  [662853] = "{id=662853,Text='不，如果一切的答案或许就在遗迹中，我必须用我的双眼去见证！',Speaker=829380,}",
  [662854] = "{id=662854,Text='请不要阻止我，海因里希，我想你比任何人都应该了解我的心情。',Speaker=829380,}",
  [662855] = "{id=662855,Text='……你说得对，但至少让我陪在你的身边。',Speaker=829378,}",
  [662856] = "{id=662856,Text='在挖掘遗迹时许多矿工和研究员莫名发疯。',Speaker=829378,}",
  [662857] = "{id=662857,Text='他们大喊大叫说听到了神的呼唤。',Speaker=829378,}",
  [662858] = "{id=662858,Text='所以我们让卡利斯格骑士团驻守在这里，',Speaker=829380,}",
  [662859] = "{id=662859,Text='她们意志坚定，能始终保持冷静。',Speaker=829380,}",
  [662860] = "{id=662860,Text='来啦来啦~你们回来啦~还带来了国王陛下~',Speaker=829389,}",
  [662861] = "{id=662861,Text='西尔芙……你们认识我？',Speaker=829380,}",
  [662862] = "{id=662862,Text='是呀，我们曾经孤独地生活在这里，直到你迁都到这里，我们才终于不寂寞啦。',Speaker=829389,}",
  [662863] = "{id=662863,Text='我们都很喜欢国王陛下和总司令官呢。',Speaker=829389,}",
  [662864] = "{id=662864,Text='我们是来寻找真相的。',Speaker=829378,}",
  [662865] = "{id=662865,Text='那就请跟我走吧~~',Speaker=829389,}",
  [662866] = "{id=662866,Text='它们的身上，有一种莫名的温暖……',Speaker=829380,}",
  [662867] = "{id=662867,Text='可在这之前，我们从未见过西尔芙。',Speaker=829378,}",
  [662868] = "{id=662868,Text='这里是研究员的营地……',Speaker=829378,}",
  [662869] = "{id=662869,Text='作为深受信赖的荣誉骑士，我将告诉你一些王国真正的机密。',Speaker=829378,Option='{有点期待,0},{开始吧！,0}',}",
  [662870] = "{id=662870,Text='[c][ffff00]尤佩雷斯遗迹[-][/c]最早是由[c][ffff00]雷根贝勒公司[-][/c]发现并开始挖掘的。',Speaker=829378,Option='雷根贝勒公司？！',}",
  [662871] = "{id=662871,Text='看起来你似乎知道这家公司？',Speaker=829380,Option='{当然……,0},{经历过一些事,0}',}",
  [662872] = "{id=662872,Text='雷根贝勒公司的挖掘进行到一半时，由大贤者巴特蒙德接手，直至爱丽丝重建天日。',Speaker=829378,}",
  [662873] = "{id=662873,Text='嗯，爱丽丝被挖掘发现后，老师劝说我将都城从普隆德拉迁到这里，利用爱丽丝组建更强的人类防御力量，抵御天灾。',Speaker=829380,}",
  [662874] = "{id=662874,Text='现在想来，大贤者也是在利用卢恩王国的武装力量保护爱丽丝吧？',Speaker=829378,}",
  [662875] = "{id=662875,Text='你这是在怀疑老师吗？我不认为他在利用我，他只是担心爱丽丝被居心叵测的人掌控。',Speaker=829380,}",
  [662876] = "{id=662876,Text='恕我直言，在刺伤你之后，巴特蒙德已经失去了我的信任。',Speaker=829378,Option='该怎么做？',}",
  [662877] = "{id=662877,Text='海因里希……',Speaker=829380,}",
  [662878] = "{id=662878,Text='好了，我们不必为此争执，相信真相很快就会揭晓。我们现在有更重要的事情要做。',Speaker=829378,}",
  [662879] = "{id=662879,Text='我们对爱丽丝的了解太少，贸然使用会引发不可预估的后果。',Speaker=829378,}",
  [662880] = "{id=662880,Text='雷根贝勒的研究人员应该在这里留下了相当多关于爱丽丝的研究资料。',Speaker=829378,}",
  [662881] = "{id=662881,Text='另外我也想知道巴特蒙德真正的目的是什么，荣誉骑士，希望你能找找附近的三个研究点，带回资料。',Speaker=829378,Option='{没问题,0},{交给我吧,0}',}",
  [662882] = "{id=662882,Text='你对老师有偏见……',Speaker=829380,}",
  [662883] = "{id=662883,Text='他刺伤了你！',Speaker=829378,}",
  [662884] = "{id=662884,Text='它们似乎在看守资料……没办法只能先击退它们了。',}",
  [662885] = "{id=662885,Text='警告……警告……',Speaker=829533,}",
  [662886] = "{id=662886,Text='这些破箱子太碍事了，清理一下吧。',}",
  [662887] = "{id=662887,Text='总算找到资料了。',}",
  [662888] = "{id=662888,Text='我失明了吗……哦，好像只是有点暗，找找附近有没有能点火的东西。',}",
  [662889] = "{id=662889,Text='找到了，研究资料在那边！',}",
  [662890] = "{id=662890,Text='你怎么一个人回来了？施密特刚刚等不及去找你了。',Speaker=829378,Option='{没碰见呀,0},{可能错过了吧,0}',}",
  [662891] = "{id=662891,Text='找不到你，他应该过会自己就回来了。已经将爱丽丝的研究资料全部带回了吗？',Speaker=829378,}",
  [662892] = "{id=662892,Text='你那边情况如何，找到爱丽丝的研究资料了吗？',Speaker=829378,Option='交出资料',}",
  [662893] = "{id=662893,Text='海因里希一目十行地阅读着，似乎得出了结论。',}",
  [662894] = "{id=662894,Text='雷根贝勒公司对爱丽丝的研究比我们想象中还要深入……',Speaker=829378,Option='他们总是如此……',}",
  [662895] = "{id=662895,Text='没想到，爱丽丝实际上是一个[c][ffff00]利用伊米尔之心的力量穿越时空的装置[-][/c]！',Speaker=829378,Option='{什么？,0},{穿越时空？,0}',}",
  [662896] = "{id=662896,Text='没错……尤佩雷斯文明居然掌握了时空奥秘……',Speaker=829378,}",
  [662897] = "{id=662897,Text='或许我们可以利用它让时间倒流，从而阻止希默梅斯的入侵！',Speaker=829378,Option='{或许有用！,0},{听起来很有道理。,0}',}",
  [662898] = "{id=662898,Text='不过，这只是我的脑海中有一个大致的想法，还需要和施密特讨论……',Speaker=829378,}",
  [662899] = "{id=662899,Text='不、不好啦！国王陛下不见了！',Speaker=829389,}",
  [662900] = "{id=662900,Text='刚才国王陛下被这个突然出现的法阵吸走了！',Speaker=829389,Option='{吸走了？,0},{怎么回事？,0}',}",
  [662901] = "{id=662901,Text='就是咻~的一声，然后不见了……',Speaker=829389,}",
  [662902] = "{id=662902,Text='呀！！现在总司令官大人也消失了！！！',Speaker=829389,}",
  [662903] = "{id=662903,Text='怎么会这样……',}",
  [662904] = "{id=662904,Text='这是哪里？看起来似乎发生了一场战争……可施密特又在哪里？',Speaker=829378,}",
  [662905] = "{id=662905,Text='（似乎在感应着什么）我嗅到了命运的味道，请跟我来吧。',Speaker=829389,}",
  [662906] = "{id=662906,Text='滚开！',Speaker=829380,}",
  [662907] = "{id=662907,Text='快点，施密特遇到了麻烦！',Speaker=829378,}",
  [662908] = "{id=662908,Text='你为什么总是喜欢乱跑？！',Speaker=829378,}",
  [662909] = "{id=662909,Text='我发誓，那个魔法阵是突然出现的……',Speaker=829380,}",
  [662910] = "{id=662910,Text='糟糕，这里的能量很不稳定，我们快点离开吧~',Speaker=829389,}",
  [662911] = "{id=662911,Text='（脆弱的生命就这样定格，还保留着生前挣扎的痕迹。）',Speaker=829406,}",
  [662912] = "{id=662912,Text='（欢乐的笑声被一片死寂代替，毛茸茸的肚皮如石头般僵硬。）',Speaker=829406,}",
  [662913] = "{id=662913,Text='（爱干净的小猫咪喜欢将胡须搭理的根根分明，此刻却被血黏成一团糟乱。）',Speaker=829406,}",
  [662914] = "{id=662914,Text='（曾经活泼跳跃的尾巴僵硬无力地耷拉在地上，空洞的双眼还残留着不安与恐惧。）',Speaker=829406,}",
  [662915] = "{id=662915,Text='（安静地躺在曾经嬉戏追逐的草地上，再也无法站起身。）',Speaker=829406,}",
  [662916] = "{id=662916,Text='（柔软的猫爪被染成深红色，不甘地向前伸出，似乎最后还想抓住点什么。）',Speaker=829406,}",
  [662917] = "{id=662917,Text='就是这里，我们快点离开吧~',Speaker=829389,}",
  [662918] = "{id=662918,Text='救救未来……',Speaker=829406,}",
  [662919] = "{id=662919,Text='救救未来！',Speaker=829406,}",
  [662920] = "{id=662920,Text='救救未来！！！',Speaker=829406,}",
  [662921] = "{id=662921,Text='施密特，这就是你想要的未来吗？',Speaker=829419,}",
  [662922] = "{id=662922,Text='刚才那些猫……它们口中的未来……是因为我吗？',Speaker=829380,}",
  [662923] = "{id=662923,Text='不，还记得之前疯了的矿工和研究员吗？我怀疑这里有[c][ffff00]某种诡异的磁场[-][/c]，会让我们进入幻境。',Speaker=829378,Option='{幻境？,0},{磁场？,0}',}",
  [662924] = "{id=662924,Text='可刚才给我的感觉实在太真实，就像[c][ffff00]真实[-][/c]发生的事……',Speaker=829380,}",
  [662925] = "{id=662925,Text='不要沉浸其中！施密特！我们找到了爱丽丝的资料，或许它真的能拯救克雷斯特汉姆！',Speaker=829378,Option='{它是时空装置,0},{可以让时间倒流,0}',}",
  [662926] = "{id=662926,Text='太好了！！这样我们就能提前提防内部的叛变，阻止希默梅斯的入侵！克雷斯特汉姆和大家都有救了！',Speaker=829380,}",
  [662927] = "{id=662927,Text='西尔芙，请你继续带着我们前进吧。',Speaker=829380,}",
  [662928] = "{id=662928,Text='这里这里~~',Speaker=829389,}",
  [662929] = "{id=662929,Text='你听到什么奇怪的声音了吗？',Speaker=829380,}",
  [662930] = "{id=662930,Text='小心，我怀疑我们还会陷入幻境……',Speaker=829378,}",
  [662931] = "{id=662931,Text='卡利斯格！！！怎么会这样……',Speaker=829380,}",
  [662932] = "{id=662932,Text='虽然还不知道具体发生了什么，但不难看出她们经历了一场怎样的战斗。',Speaker=829378,}",
  [662933] = "{id=662933,Text='卡利斯格骑士团是白骑士团最为特殊也最为坚韧的骑士团。',Speaker=829378,}",
  [662934] = "{id=662934,Text='哪怕濒临死亡，她们也要用自己的血肉之躯，阻挡敌人通行的道路……',Speaker=829380,}",
  [662935] = "{id=662935,Text='坚守使命，无论生死，这就是卡利斯格骑士团的骑士之道。',Speaker=829380,}",
  [662936] = "{id=662936,Text='在附近搜寻一下吧，即便可能性微弱，但万一……有幸存者呢？',Speaker=829378,}",
  [662937] = "{id=662937,Text='（如冬日里凋零的玫瑰，在最后一刻依旧保持着优雅与尊严。）',Speaker=829537,}",
  [662938] = "{id=662938,Text='（剑光归于尘土，但勇气之花将永远绽放。）',Speaker=829537,}",
  [662939] = "{id=662939,Text='（似乎战斗到了最后一刻，手掌保持着握剑姿势，脸上满是坚毅。）',Speaker=829537,}",
  [662940] = "{id=662940,Text='哈哈哈哈~',}",
  [662941] = "{id=662941,Text='可悲啊！',}",
  [662942] = "{id=662942,Text='站不起来了吗？',}",
  [662943] = "{id=662943,Text='看看是否还有幸存者吧……',}",
  [662944] = "{id=662944,Text='这里的卡利斯格骑士们全部壮烈牺牲……没有幸存者。',}",
  [662945] = "{id=662945,Text='这里是否会有幸存者呢？',}",
  [662946] = "{id=662946,Text='糟糕，她们都被感染，成了异变者！只能……',}",
  [662947] = "{id=662947,Text='愿她们能得到真正的安息……',}",
  [662948] = "{id=662948,Text='好多诅咒光球，为了避免再次出现感染，必须先清理它们。',}",
  [662949] = "{id=662949,Text='（带着不可置信的惊愕，不知道发生了什么……）',Speaker=829537,}",
  [662950] = "{id=662950,Text='（致命伤来自于……背后？怎么会这样？）',Speaker=829537,}",
  [662951] = "{id=662951,Text='现在可以安心查看卡利斯格骑士们的情况了。',}",
  [662952] = "{id=662952,Text='大家都……死了吗？',Speaker=829421,}",
  [662953] = "{id=662953,Text='小心……巴特……蒙德……',Speaker=829421,}",
  [662954] = "{id=662954,Text='说完，这位骑士便彻底失去了生命的气息。',}",
  [662955] = "{id=662955,Text='事关巴特蒙德，回去要将这件事告知海因里希。',}",
  [662956] = "{id=662956,Text='我正在观察遗迹之门刻着的文字，很明显是尤佩雷斯时代的古文字。',Speaker=829378,Option='{真是博学多识,0},{你怎么知道？,0}',}",
  [662957] = "{id=662957,Text='施密特是巴特蒙德的学生，我因此也曾跟在他的身边学习过一些。',Speaker=829378,Option='将刚才的事情告知……',}",
  [662958] = "{id=662958,Text='（陷入思索）…………',Speaker=829378,}",
  [662959] = "{id=662959,Text='果然和他有关吗？可他怎么能下得了手……卡利斯格也是他教导过的学生……',Speaker=829378,Option='{太过分了！,0},{或许有隐情,0}',}",
  [662960] = "{id=662960,Text='我会留意更多线索的，但在这之前，我需要先仔细研读遗迹之门上的内容。',Speaker=829378,}",
  [662961] = "{id=662961,Text='我有一种预感，这些很重要，或许当初巴特蒙德也从这里获得了重要信息。',Speaker=829378,Option='{很有可能,0},{毕竟他挖掘了遗迹,0}',}",
  [662962] = "{id=662962,Text='在这段时间里，麻烦你去帮我看看施密特的情况，目前这种情况，他……需要陪伴。',Speaker=829378,Option='我知道了',}",
  [662963] = "{id=662963,Text='卡利斯格骑士团是以卡利斯格的名字命名的，在整个白骑士团里，也只有她最特别。',Speaker=829380,}",
  [662964] = "{id=662964,Text='我还记得卡利斯格来到我的面前，质问我为什么白骑士团不收女人，我说这是一向的传统。',Speaker=829380,}",
  [662965] = "{id=662965,Text='她轻轻一笑，用温柔的语气却说出掷地有声的句子——传统并不意味着正确不是吗？曾经只有贵族能进入骑士团，可陛下不也让平民也有了机会。',Speaker=829380,}",
  [662966] = "{id=662966,Text='卡利斯格说规矩从来只是由制定的人打破，我沉默了，可听到消息的贵族们却格外反对。',Speaker=829380,}",
  [662967] = "{id=662967,Text='卡利斯格的家族驱逐了她，她的未婚夫也以此为由和她解除了婚约。',Speaker=829380,}",
  [662968] = "{id=662968,Text='然后卡利斯格立下赌注，拿着那把剑，挑战了数十位贵族出身反对她的骑士，无一败绩。',Speaker=829380,}",
  [662969] = "{id=662969,Text='从此以后，她有了自己的骑士团——卡利斯格骑士团。',Speaker=829380,Option='{真是了不起,0},{卡利斯格……,0}',}",
  [662970] = "{id=662970,Text='这些骑士们战死后，她们的武器也被附近的魔物抢走，无法容忍——',Speaker=829380,}",
  [662971] = "{id=662971,Text='骑士对自己的武器视若生命，拜托了，将她们的武器拿回来，放在她们身前吧。',Speaker=829380,Option='交给我！',}",
  [662972] = "{id=662972,Text='应该足够了，这些武器是骑士们的荣耀，不该落于黑暗之中。',}",
  [662973] = "{id=662973,Text='一支支武器竖立在战死的卡利斯格骑士们的身前',}",
  [662974] = "{id=662974,Text='安息吧，骑士们……',Speaker=829380,}",
  [662975] = "{id=662975,Text='荣光不散，英魂不灭。',Speaker=829378,}",
  [662976] = "{id=662976,Text='施密特王，我曾说过，卡利斯格骑士团将战斗到最后一刻，我们尽力了。',Speaker=829536,}",
  [662977] = "{id=662977,Text='你们是令我骄傲的骑士……',Speaker=829380,}",
  [662978] = "{id=662978,Text='可惜不能陪您走下去了，我真的很想看看这个世界在你的带领下，会走向怎样的未来。',Speaker=829536,}",
  [662979] = "{id=662979,Text='骑士将不分贵贱、无论男女，真遗憾啊，不能陪您走下去了。',Speaker=829536,}",
  [662980] = "{id=662980,Text='请您继续带着大家前行，不要停留……去往那个理想的国度吧。',Speaker=829536,}",
  [662981] = "{id=662981,Text='……卡利斯格，卡利斯格！！！',Speaker=829380,}",
  [662982] = "{id=662982,Text='为什么会变成这样？骑士们一个个死去，而我却无能为力……',Speaker=829380,}",
  [662983] = "{id=662983,Text='施密特……',Speaker=829378,}",
  [662984] = "{id=662984,Text='哎呀，又来了，小心！跟我在的身边！',Speaker=829389,}",
  [662985] = "{id=662985,Text='救命……',Speaker=829435,}",
  [662986] = "{id=662986,Text='大家快跑啊！',Speaker=829435,}",
  [662987] = "{id=662987,Text='不要！',Speaker=829435,}",
  [662988] = "{id=662988,Text='去死吧！',Speaker=829433,}",
  [662989] = "{id=662989,Text='女神万岁！！！',Speaker=829433,}",
  [662990] = "{id=662990,Text='不留活口！',Speaker=829433,}",
  [662991] = "{id=662991,Text='竟然还有漏网之鱼，哼！别想逃。',Speaker=829432,}",
  [662992] = "{id=662992,Text='女神的信徒是源源不绝的，所有的异教徒都该死！！！',Speaker=829432,}",
  [662993] = "{id=662993,Text='这里是幻境！浪费力气毫无用处！西尔芙，带我们离开！',Speaker=829378,}",
  [662994] = "{id=662994,Text='啊，跟我走！',Speaker=829389,}",
  [662995] = "{id=662995,Text='救救我们吧……',Speaker=829435,}",
  [662996] = "{id=662996,Text='黑暗彻底降临。',Speaker=829435,}",
  [662997] = "{id=662997,Text='我们到底做错了什么？',Speaker=829435,}",
  [662998] = "{id=662998,Text='有谁能回应我们的祈求？',Speaker=829435,}",
  [662999] = "{id=662999,Text='无尽的痛苦啊。',Speaker=829435,}",
  [663000] = "{id=663000,Text='我恨这个世界！',Speaker=829435,}",
  [663001] = "{id=663001,Text='精灵们都……',Speaker=829380,}",
  [663002] = "{id=663002,Text='施密特，这只是幻境。',Speaker=829378,}",
  [663003] = "{id=663003,Text='找到了！快！趁着幻境坍塌前离开！',Speaker=829389,}",
  [663004] = "{id=663004,Text='冒险者！！！',Speaker=829450,}",
  [663005] = "{id=663005,Text='救救艾卡拉奇，你知道……这里不该是这样。',Speaker=829450,}",
  [663006] = "{id=663006,Text='这不是既定的命运……',Speaker=829451,}",
  [663007] = "{id=663007,Text='这两个人认识冒险者！这也是幻境吗？为什么会如此真实？',Speaker=829380,}",
  [663008] = "{id=663008,Text='或许这不是普通的幻境，是[c][ffff00]希默梅斯为我们设下的圈套[-][/c]。',Speaker=829378,}",
  [663009] = "{id=663009,Text='不要动摇，施密特，先离开这里！',Speaker=829378,}",
  [663010] = "{id=663010,Text='小心，保持距离！',Speaker=829378,}",
  [663011] = "{id=663011,Text='又是他……',Speaker=829380,}",
  [663012] = "{id=663012,Text='海因里希，这些柱子上的信息，你已经解读出来了吧？',Speaker=829452,Option='{你认识海因里希？,0},{你到底是谁？,0}',}",
  [663013] = "{id=663013,Text='回答冒险者的话。',Speaker=829378,}",
  [663014] = "{id=663014,Text='（自顾自地说着）这里曾拥有人类最璀璨的文明——尤佩雷斯。',Speaker=829452,}",
  [663015] = "{id=663015,Text='那个文明的人一直致力于研究时空穿梭，伊米尔之心碎片的出现让他们的研究有了重大进展。',Speaker=829452,}",
  [663016] = "{id=663016,Text='超越人类极限、能够掌握时空的装置爱丽丝由此诞生。',Speaker=829452,}",
  [663017] = "{id=663017,Text='既然他们如此了不起，这里又怎么会变成一片废墟？',Speaker=829380,}",
  [663018] = "{id=663018,Text='历史是一面镜子，超越人类的力量所带来的不是新生，而是毁灭。',Speaker=829452,}",
  [663019] = "{id=663019,Text='这些柱子上的文字正是为了警示后人，[c][ffff00]不要试图掌控时空[-][/c]。',Speaker=829452,}",
  [663020] = "{id=663020,Text='我知道你是谁，露出你的真面目吧，[c][ffff00]巴特蒙德[-][/c]！',Speaker=829378,}",
  [663021] = "{id=663021,Text='老师……真的是你……',Speaker=829380,}",
  [663022] = "{id=663022,Text='海因里希，你一直很聪明，但尤佩雷斯的覆灭难道没有给你忠告吗？',Speaker=829453,}",
  [663023] = "{id=663023,Text='不要再前进了，无论你们再做什么，克雷斯特汉姆的覆灭已成定局。',Speaker=829453,}",
  [663024] = "{id=663024,Text='已成定局吗？……',Speaker=829380,}",
  [663025] = "{id=663025,Text='不要被影响，从巴特蒙德对你动手那一刻，我们的对立已无可避免。',Speaker=829378,}",
  [663026] = "{id=663026,Text='作为国王，如果连你都陷入迷茫，民众将失去方向！',Speaker=829378,}",
  [663027] = "{id=663027,Text='继续前行吧，正如卡利斯格所说，你要带着大家前往新的国度、新的未来！',Speaker=829378,}",
  [663028] = "{id=663028,Text='老师……卡利斯格……未来……',Speaker=829380,}",
  [663029] = "{id=663029,Text='啊，快看这里~！',Speaker=829389,}",
  [663030] = "{id=663030,Text='（嗅嗅）这里有些魔法残留的味道……闻起来……臭臭的……你们瞧。',Speaker=829389,}",
  [663031] = "{id=663031,Text='是希默梅斯！',Speaker=829378,}",
  [663032] = "{id=663032,Text='走吧，顺着这些痕迹肯定会有所发现，我们——出发！',Speaker=829380,}",
  [663033] = "{id=663033,Text='那个幻境到底是怎么回事？',Speaker=829380,}",
  [663034] = "{id=663034,Text='我似乎明白那些矿工和研究员为什么会疯癫了。',Speaker=829380,}",
  [663035] = "{id=663035,Text='你们听到了吗？诡异的声音越来越响。',Speaker=829380,}",
  [663036] = "{id=663036,Text='小心，越靠近遗迹中心，越容易失去理智。',Speaker=829378,}",
  [663037] = "{id=663037,Text='人类的大~贤~者~亲手将人类的希望交到敌人的手里~嘻嘻~有趣~',Speaker=829454,}",
  [663038] = "{id=663038,Text='拦住他们，没有伊米尔之心碎片功能，爱丽丝将无法启动！',Speaker=829378,}",
  [663039] = "{id=663039,Text='老师……你竟然……你不该和希默梅斯在一起。',Speaker=829380,}",
  [663040] = "{id=663040,Text='都追到这里了~不愧是臭虫国王！恢复能力还真是好呢~',Speaker=829454,}",
  [663041] = "{id=663041,Text='不过现在不能让你们坏事哟~',Speaker=829454,}",
  [663042] = "{id=663042,Text='我来在你身上多捅几个窟窿吧，让你变成一只可口的奶酪~！',Speaker=829454,}",
  [663043] = "{id=663043,Text='拿着它，快滚。',Speaker=829453,}",
  [663044] = "{id=663044,Text='人类的大贤者啊，也不过是为了自己的私欲，为了独占爱丽丝而选择和我合作的可怜臭虫。',Speaker=829454,}",
  [663045] = "{id=663045,Text='瞧我们陛下那张可悲的脸~！快要哭出来了似的，啧啧~可~怜~虫~',Speaker=829454,}",
  [663046] = "{id=663046,Text='闭嘴！希默梅斯！！！',Speaker=829380,}",
  [663047] = "{id=663047,Text='你竟然可以……',Speaker=829454,}",
  [663048] = "{id=663048,Text='哼，是我小瞧了你们！！',Speaker=829454,}",
  [663049] = "{id=663049,Text='巴特蒙德！巴特蒙德！！你站在那里是准备看戏吗？！快帮我！！！',Speaker=829454,}",
  [663050] = "{id=663050,Text='我们的合作已经结束，接下来你的命运和我无关。',Speaker=829453,}",
  [663051] = "{id=663051,Text='啊啊啊！该死的家伙，我怀疑你和他们串通好了，是为了引诱我进入陷阱！',Speaker=829454,}",
  [663052] = "{id=663052,Text='真是个聒噪的家伙，荣誉骑士，让她永远闭嘴吧。',Speaker=829378,}",
  [663053] = "{id=663053,Text='等等！先别动手——',Speaker=829455,Option='{又怎么了？,0},{难道这也是选择？,0}',}",
  [663054] = "{id=663054,Text='不，你不能杀死希默梅斯，这不是时空和命运既定的轨道。',Speaker=829455,Option='{可我明明是为了……,0},{改变命运啊！,0}',}",
  [663055] = "{id=663055,Text='这就要说到一些时空悖论和多维时空的理论了，我知道你还不太明白，那就长话短说。',Speaker=829455,}",
  [663056] = "{id=663056,Text='简而言之，有些命运的改变无足轻重，但有些命运一旦被更改，将会引发整个时空的毁灭。',Speaker=829455,}",
  [663057] = "{id=663057,Text='希默梅斯必须出现在未来的时间线里，所以你不能在这里让她死去。',Speaker=829455,Option='{可你一开始让我……,0},{阻止毁灭古城的人,0}',}",
  [663058] = "{id=663058,Text='我很高兴你还记得此行目的，但你搞错了目标，真正会毁灭克雷斯特汉姆的人可不是希默梅斯。',Speaker=829455,Option='那是谁？',}",
  [663059] = "{id=663059,Text='命运就是在揭晓谜底那一刻前，难以给出答案的东西……用心想想吧。',Speaker=829455,}",
  [663060] = "{id=663060,Text='再见了！哦不，永别了~臭虫们！',Speaker=829454,}",
  [663061] = "{id=663061,Text='你到底在干什么？我需要你给我一个解释！',Speaker=829378,Option='{我被时空束缚了,0},{我不能杀她,0}',}",
  [663062] = "{id=663062,Text='希默梅斯是必定会出现在未来的，所以时空的管理者是不会让任何人在过去杀死她的。',Speaker=829453,}",
  [663063] = "{id=663063,Text='我也尝试过很多次去干掉希默梅斯，最终明白这是不被允许的方法。',Speaker=829453,}",
  [663064] = "{id=663064,Text='一切都结束了。施密特，你带着其他活着的人离开克雷斯特汉姆吧。',Speaker=829453,}",
  [663065] = "{id=663065,Text='如果未来是既定的……那我们……',Speaker=829378,}",
  [663066] = "{id=663066,Text='海因里希！爱丽丝还在！希望就还在！',Speaker=829380,}",
  [663067] = "{id=663067,Text='老师，你曾经也说过她可以拯救大家，这不正是我们迁都的原因吗？',Speaker=829380,}",
  [663068] = "{id=663068,Text='我还记得那么多的劳工为此而死，如果我现在放弃，他们的死亡不也成了一场空吗？',Speaker=829380,}",
  [663069] = "{id=663069,Text='现在外面还有那么多感染的人，我必须拯救他们！老师，我绝对不会放弃。',Speaker=829380,}",
  [663070] = "{id=663070,Text='（叹气）果然如此，你[c][ffff00]每一次[-][/c]都想拯救所有人，这根本是不可能的事。',Speaker=829453,}",
  [663071] = "{id=663071,Text='你该放弃了，这是我对你最后的忠告。',Speaker=829453,}",
  [663072] = "{id=663072,Text='巴特蒙德，你又干了什么！！！',Speaker=829378,}",
  [663073] = "{id=663073,Text='…………',Speaker=829453,}",
  [663074] = "{id=663074,Text='施密特去了哪里？！',Speaker=829378,Option='{难道？,0},{又是幻境？,0}',}",
  [663075] = "{id=663075,Text='不……不是幻境！看到大贤者的法术后，我确认了一件事情！',Speaker=829389,}",
  [663076] = "{id=663076,Text='就是这个！[c][ffff00]时空能量矿石[-][/c]！大贤者使用了它们的力量！',Speaker=829389,}",
  [663077] = "{id=663077,Text='如果是用了矿石中的时空能量的话，之前的那些都不是幻境……而是折射出的，[c][ffff00]真实的未来[-][/c]！！',Speaker=829389,}",
  [663078] = "{id=663078,Text='什么？！竟是如此……可现在那里只有施密特一个人……',Speaker=829378,}",
  [663079] = "{id=663079,Text='西尔芙，想个办法，至少让我也前往施密特所在的地方，或者让我代替他！',Speaker=829378,}",
  [663080] = "{id=663080,Text='在附近找找吧，如果能收集到同样力量，应该还有机会，去找找附近的时空能量矿石吧。',Speaker=829389,Option='我们现在就去！',}",
  [663081] = "{id=663081,Text='施密特，撑住！',Speaker=829378,}",
  [663082] = "{id=663082,Text='尽快呀~~',Speaker=829389,}",
  [663083] = "{id=663083,Text='爱丽丝的制造能让我们穿越时间，超越自身，这无疑是本时代最伟大的发明！',Speaker=829456,}",
  [663084] = "{id=663084,Text='这算是我们的自吹自擂吗？哈哈哈，不过严格来说，我们的确很了不起。',Speaker=829457,}",
  [663085] = "{id=663085,Text='所以我用女儿的名字为它命名，我相信爱丽丝会带来奇迹。',Speaker=829457,}",
  [663086] = "{id=663086,Text='当然，我想它很快就会起到作用，近来周围的环境已经恶劣到几乎无法生存……',Speaker=829456,}",
  [663087] = "{id=663087,Text='关于这件事，我认为我们还是应该谨慎点，科学是从多次试验中培育出的种子，不能草率。',Speaker=829457,}",
  [663088] = "{id=663088,Text='但我们已经没有时间了，有时候科学也需要一点勇气，不是吗？',Speaker=829456,}",
  [663089] = "{id=663089,Text='我知道你是一位了不起的冒险家，但这件事还是不要太冒险……',Speaker=829457,}",
  [663090] = "{id=663090,Text='我们可以将想法提交给公民大会，毕竟那些民众也应该决定自己的命运。',Speaker=829456,}",
  [663091] = "{id=663091,Text='……抱歉，但我依旧坚持我的看法，爱丽丝不该被轻易使用。',Speaker=829457,}",
  [663092] = "{id=663092,Text='似乎是通过时空能量矿石逸散的力量，看到了一些过去的场景……',}",
  [663093] = "{id=663093,Text='我说过的！我说过的！！！伦巴第，你害了所有人，害了我的女儿！',Speaker=829457,}",
  [663094] = "{id=663094,Text='尤佩雷斯因爱丽丝产生的时空能量毁灭了！！！',Speaker=829457,}",
  [663095] = "{id=663095,Text='对不起，我愿意付出一切来忏悔，我没有想到会造成这样的后果。',Speaker=829456,}",
  [663096] = "{id=663096,Text='爱丽丝，我要再次开启爱丽丝，用爱丽丝找到我的女儿爱丽丝！',Speaker=829457,}",
  [663097] = "{id=663097,Text='冷静一点，我们根本不知道会不会产生更严重的后果，万一……',Speaker=829456,}",
  [663098] = "{id=663098,Text='闭嘴，你这个混蛋，你不该阻止我，也阻止不了我！',Speaker=829457,}",
  [663099] = "{id=663099,Text='又是过去的场景吗？先记下来，过会告诉海因里希吧。',}",
  [663100] = "{id=663100,Text='今天我们相聚在这里，是为了同一个目标——封存爱丽丝。',Speaker=829459,}",
  [663101] = "{id=663101,Text='爱丽丝为我们带来的不是变革，而是灾难。',Speaker=829459,}",
  [663102] = "{id=663102,Text='最可悲的是这个灾难是由我们中最天才的那两个人亲手造就的，他们也付出了代价。',Speaker=829458,}",
  [663103] = "{id=663103,Text='过去是不容改变的，妄图操纵时间的人，最终会陷入命运的洪流。',Speaker=829458,}",
  [663104] = "{id=663104,Text='让我们暂时封存爱丽丝，离开这里吧，就当一切都是一场梦。',Speaker=829460,}",
  [663105] = "{id=663105,Text='未来只能由现在的我们去改变，我们将这些刻在柱子上，警示后人吧。',Speaker=829458,}",
  [663106] = "{id=663106,Text='种一棵树最好的时机是现在，因为人永远无法回到十年前，如果真的回去，那等待你的将会是噩梦。',Speaker=829459,}",
  [663107] = "{id=663107,Text='愿神明保佑，希望那些最聪明的人不要犯我们犯过的错误……',Speaker=829460,}",
  [663108] = "{id=663108,Text='这就是柱子上文字的由来吗？将过去发生的这些告诉海因里希吧。',}",
  [663109] = "{id=663109,Text='太慢了！冒险者，你为什么才回来！',Speaker=829378,}",
  [663110] = "{id=663110,Text='我们不知道施密特会遭遇什么，万一他出了什么事呢？你为什么还在耽误时间？',Speaker=829378,Option='将遇到的事告知……',}",
  [663111] = "{id=663111,Text='所以你通过时空能量矿石看到了过去发生的事？抱歉，是我刚才太急躁了，请你原谅我。',Speaker=829378,Option='{理解你的心情,0},{毕竟你很担心他,0}',}",
  [663112] = "{id=663112,Text='这一切都能和遗迹之门上刻着的内容对应了……',Speaker=829378,}",
  [663113] = "{id=663113,Text='但现在最重要的是将施密特带回来！西尔芙，我们该怎么做？',Speaker=829378,}",
  [663114] = "{id=663114,Text='请将时空能量矿石放在施密特的身边吧~~',Speaker=829389,}",
  [663115] = "{id=663115,Text='拜托了……',Speaker=829378,}",
  [663116] = "{id=663116,Text='过去、现在与未来将在这一刻汇聚，时空啊，请让我们沉睡入梦，触碰未知的真实吧。',Speaker=829389,}",
  [663117] = "{id=663117,Text='这里是……普隆德拉？怎么会变成这样？',Speaker=829378,Option='{太可怕了,0},{难以想象,0}',}",
  [663118] = "{id=663118,Text='奉女神之命，抓住他们！',Speaker=829465,}",
  [663119] = "{id=663119,Text='违逆女神者，死！',Speaker=829465,}",
  [663120] = "{id=663120,Text='你们死在临头了……',Speaker=829465,}",
  [663121] = "{id=663121,Text='都站到我的身后，所有人！立刻！',Speaker=829380,}",
  [663122] = "{id=663122,Text='是施密特的声音，这个家伙显然又在乱来了，我们快点！',Speaker=829378,}",
  [663123] = "{id=663123,Text='快点，再快点！',Speaker=829378,}",
  [663124] = "{id=663124,Text='海因里希！冒险者！你们竟然也来了？',Speaker=829380,}",
  [663125] = "{id=663125,Text='乖孩子，来的正好呢。',Speaker=829495,}",
  [663126] = "{id=663126,Text='窃据米德加尔特大陆的人类啊，就此毁灭吧，神族才是这个世界上唯一的主宰。',Speaker=829495,}",
  [663127] = "{id=663127,Text='救救未来！',Speaker=829501,}",
  [663128] = "{id=663128,Text='幻境……这也是幻境吗？……如此真实……',Speaker=829380,}",
  [663129] = "{id=663129,Text='施密特！快走！',Speaker=829378,}",
  [663130] = "{id=663130,Text='这里已经彻底失控了，我们必须立刻离开。',Speaker=829389,}",
  [663131] = "{id=663131,Text='我在哪？',Speaker=829380,}",
  [663132] = "{id=663132,Text='施密特，你怎么样？',Speaker=829378,}",
  [663133] = "{id=663133,Text='我没事……可是老师……他让我看到这些幻境究竟是为什么？',Speaker=829380,}",
  [663134] = "{id=663134,Text='施密特，那不是幻境，是周围的时空能量矿石带你看到的真实的未来。',Speaker=829378,}",
  [663135] = "{id=663135,Text='这些既是虚幻的影像，但也有可能是真实的未来……即便如此，你还要走下去吗？',Speaker=829378,}",
  [663136] = "{id=663136,Text='如果连我们都迷茫的话，民众会失去方向。',Speaker=829380,}",
  [663137] = "{id=663137,Text='只是爱丽丝里的伊米尔之心碎片已经被希默梅斯带走了……',Speaker=829378,}",
  [663138] = "{id=663138,Text='不管怎么说，我们都走到这里了，必须去看看爱丽丝的情况，万一我们能找到其他能源呢？',Speaker=829380,}",
  [663139] = "{id=663139,Text='只要还有一丝希望，我们都不能放弃！',Speaker=829380,}",
  [663140] = "{id=663140,Text='西尔芙，你会带我们过去的，是吗？',Speaker=829380,}",
  [663141] = "{id=663141,Text='对不起，我不能靠近爱丽丝……但她就在那里，接下来需要你们自己过去。',Speaker=829389,}",
  [663142] = "{id=663142,Text='虽然我不能再指引你们，但倾听你们的内心吧，它会带领你们前行！',Speaker=829389,}",
  [663143] = "{id=663143,Text='我有一种很奇怪的感觉……',Speaker=829380,}",
  [663144] = "{id=663144,Text='老师他似乎变化很大，我是指气质方面……',Speaker=829380,}",
  [663145] = "{id=663145,Text='但我又很确定，他是本人，不是谁假扮的……',Speaker=829380,}",
  [663146] = "{id=663146,Text='笨蛋的嗅觉很灵敏……你大多数时候的直觉都是准确的。',Speaker=829378,}",
  [663147] = "{id=663147,Text='如果真如你感知的那样，他究竟是怎么回事？',Speaker=829378,}",
  [663148] = "{id=663148,Text='已经无法再靠近了……',Speaker=829380,}",
  [663149] = "{id=663149,Text='爱丽丝……她和我第一次见到时变化很大。',Speaker=829380,}",
  [663150] = "{id=663150,Text='哼，在矿工和研究员出事后，巴特蒙德封闭了王座之间，当初我以为他是为了保护其他人……',Speaker=829378,}",
  [663151] = "{id=663151,Text='现在看来，他有自己的算盘，很难说爱丽丝的变化是否和他有关。',Speaker=829378,}",
  [663152] = "{id=663152,Text='比如，现在一定是他做了些什么，让我们无法靠近爱丽丝。',Speaker=829378,Option='{那我们现在……,0},{该怎么办？,0}',}",
  [663153] = "{id=663153,Text='我想想……他曾经和我提及过……这应该当时他是为了保护爱丽丝设置的屏障装置。',Speaker=829380,}",
  [663154] = "{id=663154,Text='也或许恰恰相反，只是为了让其余人远离爱丽丝，方便他做点什么。',Speaker=829378,}",
  [663155] = "{id=663155,Text='按照他的习惯，开关屏障的装置应该就在附近，我们可以观察屏障能量的来源。',Speaker=829380,}",
  [663156] = "{id=663156,Text='不过想关闭装置可不容易，他肯定会放置守护者。',Speaker=829380,}",
  [663157] = "{id=663157,Text='以冒险者的实力，这些恐怕不是他需要担心的事。',Speaker=829378,Option='{没错！,0},{那你们呢？,0}',}",
  [663158] = "{id=663158,Text='我们必须在这里守着爱丽丝，防止黑暗军团或巴特蒙德靠近。',Speaker=829378,Option='{好吧,0},{我去关闭装置,0}',}",
  [663159] = "{id=663159,Text='离开这里！无论你是谁。',Speaker=829497,}",
  [663160] = "{id=663160,Text='（是否关闭屏蔽装置？）',Speaker=829496,Option='{是,11},{再想想,12}',}",
  [663161] = "{id=663161,Text='执迷不悟，你还记得那些求救的人吗？',Speaker=829497,}",
  [663162] = "{id=663162,Text='（是否关闭屏蔽装置？）',Speaker=829496,Option='{是,11},{再想想,12}',}",
  [663163] = "{id=663163,Text='人类为何总是无数次踏入同一个命运的洪流？',Speaker=829497,}",
  [663164] = "{id=663164,Text='（是否关闭屏蔽装置？）',Speaker=829496,Option='{是,11},{再想想,12}',}",
  [663165] = "{id=663165,Text='施密特，到现在你都认为之前看到的那些场景是幻境吗？',Speaker=829453,}",
  [663166] = "{id=663166,Text='…………',Speaker=829380,}",
  [663167] = "{id=663167,Text='看来你已经有了答案，爱丽丝曾在这里失控，她所产生的巨大时空能量的冲击，造成了许多看不见的时空裂隙。',Speaker=829453,}",
  [663168] = "{id=663168,Text='而那些所谓的幻境，是无数个真实的未来。',Speaker=829453,}",
  [663169] = "{id=663169,Text='那你呢？你真的是我的老师吗……',Speaker=829380,}",
  [663170] = "{id=663170,Text='是也不是，我并不是你们认识的巴特蒙德，而是来自未来。',Speaker=829453,}",
  [663171] = "{id=663171,Text='……你回到这里的目的是为了什么？！',Speaker=829380,}",
  [663172] = "{id=663172,Text='我所在的那个未来，就是你在幻境中所见到的那样，芙蕾雅要消灭除了神族以外的所有种族。',Speaker=829453,}",
  [663173] = "{id=663173,Text='我回到这里是为了将爱丽丝带回未来，作为兵器消灭芙蕾雅，拯救人类！',Speaker=829453,Option='{爱丽丝是兵器？,0},{她是时空装置！,0}',}",
  [663174] = "{id=663174,Text='没有人比我更了解爱丽丝了……我在她的身上，花费了太多的心血。',Speaker=829453,}",
  [663175] = "{id=663175,Text='你们所不知道的是，爱丽丝可以将时空之力凝聚起来，这股力量，足以将芙蕾雅撕碎！',Speaker=829453,}",
  [663176] = "{id=663176,Text='可是……只要使用爱丽丝，我们就可以回到过去，阻止希默梅斯的入侵！克雷斯特汉姆就不会……',Speaker=829380,}",
  [663177] = "{id=663177,Text='不要痴人说梦了！你以为我没有尝试过拯救克雷斯特汉姆吗？',Speaker=829453,}",
  [663178] = "{id=663178,Text='克雷斯特汉姆的覆灭已成定局，它注定会成为陨落的古城。',Speaker=829453,}",
  [663179] = "{id=663179,Text='那位时空的管理人是绝不会允许未来的走向发生如此大的改变的！',Speaker=829453,}",
  [663180] = "{id=663180,Text='或许我们还能……',Speaker=829380,}",
  [663181] = "{id=663181,Text='我知道你在想什么，你想将感染的人们送往过去或是未来的时空，让他们恢复。',Speaker=829453,}",
  [663182] = "{id=663182,Text='很可惜，这也是不可能的。时间的流逝在个体上的印记不会因为时空的改变而发生变化。',Speaker=829453,}",
  [663183] = "{id=663183,Text='就像我，从未来回到这里，可无论我的身体还是精神，都经历着三百年的时光。',Speaker=829453,}",
  [663184] = "{id=663184,Text='所以你无论用爱丽丝穿越到任何的时间点，感染都不会停止！',Speaker=829453,}",
  [663185] = "{id=663185,Text='怎么会……这样……',Speaker=829380,}",
  [663186] = "{id=663186,Text='现在的爱丽丝只能承受最后一次使用。施密特，如果你还坚持用爱丽丝，那么未来人类乃至整个天地树世界的其他种族将牺牲！',Speaker=829453,}",
  [663187] = "{id=663187,Text='你们已经用双眼看到了未来，那就是你们将造成的恶果。',Speaker=829453,}",
  [663188] = "{id=663188,Text='所以那个从阅兵庆典上[c][ffff00]将施密特传送离开[-][/c]的人，就是你吧？巴特蒙德！',Speaker=829378,}",
  [663189] = "{id=663189,Text='是我。施密特，我本以为这一次将你送去亚空间既能阻止你使用爱丽丝，又能将你救下。',Speaker=829453,}",
  [663190] = "{id=663190,Text='可没想到，这次有了新的变故，冒险者……你不该出现的。',Speaker=829453,Option='{时空龙的任务……,0},{我也有我的任务,0}',}",
  [663191] = "{id=663191,Text='奥斯卡要守护的是时空，可我要守护的是未来！',Speaker=829453,}",
  [663192] = "{id=663192,Text='为了一城之民无谓的牺牲而牺牲人类全部的未来，施密特，你应该知道如何选择！',Speaker=829453,}",
  [663193] = "{id=663193,Text='我……我的选择……未来和现在……',Speaker=829380,}",
  [663194] = "{id=663194,Text='活下去吧，我的学生……',Speaker=829453,}",
  [663195] = "{id=663195,Text='至于你们，现在就离开吧，我需要一些时间将爱丽丝的核心拆解出来。',Speaker=829453,}",
  [663196] = "{id=663196,Text='放心，大贤者阁下，我们可没有偷袭的习惯。',Speaker=829378,}",
  [663197] = "{id=663197,Text='在巴特蒙德看来克雷斯特汉姆注定毁灭。',Speaker=829378,}",
  [663198] = "{id=663198,Text='施密特又怎么可能接受这个结局？',Speaker=829378,}",
  [663199] = "{id=663199,Text='他所珍视的将化为灰烬，他所守护的将埋入地底……',Speaker=829378,}",
  [663200] = "{id=663200,Text='施密特！施密特！！',Speaker=829378,}",
  [663201] = "{id=663201,Text='别过来……让我一个人……好好想想……',Speaker=829380,}",
  [663202] = "{id=663202,Text='陛下小心！',Speaker=829499,}",
  [663203] = "{id=663203,Text='这群该死的杂碎！',Speaker=829499,}",
  [663204] = "{id=663204,Text='陛下，希默梅斯似乎已经离开了这里，但黑暗军团的余孽还在。',Speaker=829499,}",
  [663205] = "{id=663205,Text='请您放心，几位骑士团长正在城里搜寻残余魔物，我们一定会保护好群众。',Speaker=829499,}",
  [663206] = "{id=663206,Text='用我们的生命，战斗至最后一刻！',Speaker=829499,}",
  [663207] = "{id=663207,Text='呀，是国王叔叔！',Speaker=829520,}",
  [663208] = "{id=663208,Text='我们应该行礼，然后说陛下万安！',Speaker=829519,Option='不用……',}",
  [663209] = "{id=663209,Text='对啦，上次来找我们的那个骑士去哪里啦？',Speaker=829520,}",
  [663210] = "{id=663210,Text='我本来还想告诉他，奥卡姆被魔物抓走了……他没有听话，又乱跑了……',Speaker=829520,}",
  [663211] = "{id=663211,Text='白骑士的骑士叔叔们出去找他了……我们原本还约好了，晚餐后要再一起玩！',Speaker=829519,}",
  [663212] = "{id=663212,Text='国王叔叔，我们……还能见到他吗？',Speaker=829520,}",
  [663213] = "{id=663213,Text='兄弟，你先冷静一点，别激动。',Speaker=829521,}",
  [663214] = "{id=663214,Text='放开我，我要去战场！外面还有我的伙伴！',Speaker=829523,}",
  [663215] = "{id=663215,Text='乖乖躺好吧，还是你想死在战场上？',Speaker=829521,}",
  [663216] = "{id=663216,Text='陛下，您快点劝劝他吧，这个家伙实在太倔了。',Speaker=829521,}",
  [663217] = "{id=663217,Text='陛下，我不能躺在这里，我的伙伴还需要我。',Speaker=829523,Option='{你受伤了……,0},{冷静一点,0}',}",
  [663218] = "{id=663218,Text='这点伤不算什么，我……我怕我已经被感染了，如果这样，我必须趁还清醒时，多干掉几个魔物。',Speaker=829523,}",
  [663219] = "{id=663219,Text='我们有生命之水，可以暂时抑制感染。',Speaker=829521,}",
  [663220] = "{id=663220,Text='别骗我了，我知道感染是不可逆的，在变成那副鬼样子之前，就让我完成心愿吧。',Speaker=829523,}",
  [663221] = "{id=663221,Text='别这样，陛下和各位骑士团长们正在积极寻求解决办法，我们一定能战胜感染。',Speaker=829521,}",
  [663222] = "{id=663222,Text='站在你面前的这位可是施密特王，陛下总能带领我们度过困境。',Speaker=829521,}",
  [663223] = "{id=663223,Text='你说得对……陛下，我相信您一定会带我们走上胜利，哪怕这代价是付出我的生命！',Speaker=829523,}",
  [663224] = "{id=663224,Text='我的感染已经瞒不住了，把我交给骑士团吧。',Speaker=829528,}",
  [663225] = "{id=663225,Text='不……不要离开我，如果不是为了救我，你也不会被感染……',Speaker=829529,}",
  [663226] = "{id=663226,Text='战争中什么都有可能发生，不要自责，或许这就是……我的命运。',Speaker=829528,}",
  [663227] = "{id=663227,Text='可你会死的，一定会的，我偷偷听说，骑士们会把感染的人杀掉，防止他们失去理智，而这都是国王的命令！',Speaker=829529,}",
  [663228] = "{id=663228,Text='不要相信这些，骑士们一直在保护我们，不是吗？我相信国王陛下一定会想办法。',Speaker=829528,}",
  [663229] = "{id=663229,Text='……你忘记那些劳工是怎么死的了吗？忘记他是如何从庆典消失的吗？说不定黑暗军团就是他招来的！',Speaker=829529,}",
  [663230] = "{id=663230,Text='可我相信他，是他让平民有机会进入骑士团，也是他愿意公布真相，为平民伸冤，处死贵族……',Speaker=829528,}",
  [663231] = "{id=663231,Text='我不想知道他究竟是什么人，我只想让你活下去……为什么会发生这一切？为什么？！',Speaker=829529,}",
  [663232] = "{id=663232,Text='站住……啊，是陛下……请恕我无礼。',Speaker=829524,}",
  [663233] = "{id=663233,Text='（压低声音）除了黑暗军团外，我们还在城里发现了一些奸细，应该是普隆德拉那些贵族派来的。',Speaker=829524,Option='{那些贵族……,0},{普隆德拉……,0}',}",
  [663234] = "{id=663234,Text='但请您放心，我们一定会把那些老鼠都揪出来的！',Speaker=829524,}",
  [663235] = "{id=663235,Text='我们坚信在陛下的领导下，克雷斯特汉姆必将迎来新生，我们一定会取得最终的胜利。',Speaker=829524,}",
  [663236] = "{id=663236,Text='到时候我要把这段经历告诉我的后代，我后代的后代，哈哈，真让人期待啊。',Speaker=829524,}",
  [663237] = "{id=663237,Text='关于巴特蒙德说的那些话……我知道他没有说谎，但我发现了一件事。',Speaker=829378,}",
  [663238] = "{id=663238,Text='巴特蒙德虽然将伊米尔之心的碎片交给了希默梅斯，[c][ffff00]但爱丽丝里还残留有伊米尔之心的力量[-][/c]。',Speaker=829378,}",
  [663239] = "{id=663239,Text='也就是说，爱丽丝很可能还能启动……',Speaker=829378,}",
  [663240] = "{id=663240,Text='国王叔叔！',Speaker=829530,}",
  [663241] = "{id=663241,Text='这是……送给我的吗？',Speaker=829380,}",
  [663242] = "{id=663242,Text='国王叔叔，不要难过！你可是最了不起的国王叔叔呀~',Speaker=829530,}",
  [663243] = "{id=663243,Text='父王说过的话，那时意气风发的我还未曾理解，可现在我终于明白……',Speaker=829380,}",
  [663244] = "{id=663244,Text='惨烈的未来在眼前不停地浮现……',Speaker=829380,}",
  [663245] = "{id=663245,Text='可比起缥缈的未来，眼下人们的体温和眼泪我无法视而不见。',Speaker=829380,}",
  [663246] = "{id=663246,Text='我的子民、那些我想付出一切所庇护的人们……他们是无比相信胜利的到来，也相信着我这个国王。',Speaker=829380,}",
  [663247] = "{id=663247,Text='我要如何做，才能拯救这些我想付出一切来庇护的人们？',Speaker=829380,}",
  [663248] = "{id=663248,Text='穿越时间的命运之风带来了希望，我也是时候做出了最终的决定！',Speaker=829380,}",
  [663249] = "{id=663249,Text='冒险者，你的出现是这场灾难中最大的幸运，为克雷斯特汉姆带来了希望。',Speaker=829380,Option='{可是……,0},{克雷斯特汉姆现在……,0}',}",
  [663250] = "{id=663250,Text='不，还没有到该绝望的时刻，来吧，所有的白骑士们，集合！',Speaker=829380,}",
  [663251] = "{id=663251,Text='陛下！',Speaker=829501,}",
  [663252] = "{id=663252,Text='将所有幸存的民众按照感染与未感染分开！',Speaker=829380,}",
  [663253] = "{id=663253,Text='由先锋团团长费沙与骑兵团团长斯特汀率领所属骑士团将所有未感染民众护送出城。',Speaker=829380,}",
  [663254] = "{id=663254,Text='是！',}",
  [663255] = "{id=663255,Text='是！',}",
  [663256] = "{id=663256,Text='侦查团团长沙利和火枪团团长伦司，你们带人将所有感染的民众和骑士送到地下挖掘场。',Speaker=829380,}",
  [663257] = "{id=663257,Text='去吧，骑士们，将荣誉凝于剑锋，无畏前行！克雷斯克汉姆旭日不灭！',Speaker=829380,}",
  [663258] = "{id=663258,Text='旭日不灭！！！',Speaker=829501,}",
  [663259] = "{id=663259,Text='海因里希、冒险者，我们前往爱丽丝所在地吧，是时候让一切结束了。',Speaker=829380,}",
  [663260] = "{id=663260,Text='施密特……',Speaker=829378,}",
  [663261] = "{id=663261,Text='施密特……你究竟……',Speaker=829378,}",
  [663262] = "{id=663262,Text='走吧，海因里希，就像以前一样，我们会走下去的。',Speaker=829380,}",
  [663263] = "{id=663263,Text='哼，看来巴特蒙德已经猜到我们会回来，老师对学生的了解？',Speaker=829378,}",
  [663264] = "{id=663264,Text='那老师应该更了解，这些可阻止不了我这个学生！',Speaker=829380,}",
  [663265] = "{id=663265,Text='离开，施密特，最后的机会。',Speaker=829453,}",
  [663266] = "{id=663266,Text='我都到了这里，又怎么可能离开？老师，我是你学生，是你教会我不放弃一丝希望。',Speaker=829380,}",
  [663267] = "{id=663267,Text='又是这样，施密特……',Speaker=829453,}",
  [663268] = "{id=663268,Text='爱丽丝，撕裂时空裂隙，召唤来自异时空的客人——',Speaker=829453,}",
  [663269] = "{id=663269,Text='远古巴风特……不……是它的幻影！',Speaker=829380,}",
  [663270] = "{id=663270,Text='巴特蒙德，你知道这会给克雷斯特汉姆带来怎样的灾难吗？',Speaker=829380,}",
  [663271] = "{id=663271,Text='是你还不愿意面对，克雷斯特汉姆注定毁灭的事实！',Speaker=829453,}",
  [663272] = "{id=663272,Text='哼，施密特，与他多说无用！',Speaker=829378,}",
  [663273] = "{id=663273,Text='除非杀了我，否则我不会改变我的决定，[c][ffff00]我要用爱丽丝拯救克雷斯特汉姆的所有人[-][/c]。',Speaker=829380,}",
  [663274] = "{id=663274,Text='拯救现在就是毁灭未来，施密特，你听不到那些远方的求救吗？',Speaker=829453,}",
  [663275] = "{id=663275,Text='你怎么知道活下来的人不会改变未来？我不可能放弃这些鲜活的生命，去期待一个看不见的未来。',Speaker=829380,}",
  [663276] = "{id=663276,Text='爱丽丝也是先辈们创造出来的，难道以后的人不能再创造出新的爱丽丝吗？',Speaker=829380,}",
  [663277] = "{id=663277,Text='我相信我的骑士，也相信我的子民，他们才是未来的基石！',Speaker=829380,}",
  [663278] = "{id=663278,Text='…………',Speaker=829453,}",
  [663279] = "{id=663279,Text='你有你要守护的未来，我们有我们要守护的现在！',Speaker=829380,}",
  [663462] = "{id=663462,Voice='Npc_Quest/663462',Text='停止吧！',Speaker=829775,}",
  [663463] = "{id=663463,Voice='Npc_Quest/663463',Text='不要在我的面前秀你那些小伎俩！',Speaker=829775,}",
  [663464] = "{id=663464,Voice='Npc_Quest/663464',Text='又见面了，这一次没有人可以阻挡我拿到伊米尔之心碎片！',Speaker=829776,}",
  [663465] = "{id=663465,Voice='Npc_Quest/663465',Text='我们还会再见的。',Speaker=829776,}",
  [663466] = "{id=663466,Voice='Npc_Quest/663466',Text='冒险者啊，你还能再晚一点出现吗？',Speaker=829775,Option='{为什么,0},{额……,0}',}",
  [663467] = "{id=663467,Voice='Npc_Quest/663467',Text='再晚来一点这个时空就要乱成一团乱麻。',Speaker=829775,}",
  [663468] = "{id=663468,Voice='Npc_Quest/663468',Text='我还要花些时间整理一下你这一次要执行的任务~',Speaker=829775,Option='{好的,0},{明白,0}',}",
  [663469] = "{id=663469,Voice='Npc_Quest/663469',Text='好了，命运之风，听好了。',Speaker=829775,}",
  [663470] = "{id=663470,Voice='Npc_Quest/663470',Text='在过去，施密特启用爱丽丝后，虽然解决了当时的问题，但……',Speaker=829775,Option='又有新的麻烦',}"
}
Table_Dialog_Left_43.count = 2001
